def _fig_architecture_comparison(l1_preds: List[ModelPrediction]) -> go.Figure:
    """Lollipop chart comparing point estimates with per-model CI bands."""
    names = [mp.arch.value.split("(")[0].strip()[:26] for mp in l1_preds]
    pts   = [mp.point for mp in l1_preds]
    lo    = [mp.q10   for mp in l1_preds]
    hi    = [mp.q90   for mp in l1_preds]
    cols  = [MODEL_META.get(mp.arch,{}).get("colour","#94a3b8") for mp in l1_preds]
    order = sorted(range(len(pts)), key=lambda i: -pts[i])

    fig = go.Figure()
    for i in order:
        fig.add_trace(go.Scatter(
            x=[lo[i], hi[i]], y=[names[i],names[i]], mode="lines",
            line=dict(color=cols[i],width=6), opacity=0.30,
            showlegend=False,
        ))
        fig.add_trace(go.Scatter(
            x=[pts[i]], y=[names[i]], mode="markers",
            marker=dict(size=14, color=cols[i], line=dict(color="white",width=2)),
            name=names[i], showlegend=False,
        ))
    fig.update_layout(title="L1 model predictions with 80% CI",
        xaxis=dict(title="Predicted risk (0–100)", range=[0,105]),
        template=plotly_template(), height=380,
        margin=dict(l=20,r=20,t=50,b=20))
    return fig


def _fig_threat_matrix(preds: Dict) -> go.Figure:
    """Threat matrix: P(exceedance) × consequence (ENS) × risk score (bubble size)."""
    places  = sorted(preds.keys())
    if not places or 5 not in preds[places[0]]: return go.Figure()
    probs   = [preds[p][5]["prediction"].exceedance_probability*100 for p in places]
    ens_mw  = [preds[p][5]["prediction"].predicted_ens_mw for p in places]
    risks   = [preds[p][5]["prediction"].predicted_risk for p in places]
    ac      = [ALERT_COLOUR[preds[p][5]["prediction"].alert_level] for p in places]
    fig = go.Figure(go.Scatter(
        x=probs, y=ens_mw, mode="markers+text",
        text=[p[:14] for p in places], textposition="top center", textfont=dict(size=9),
        marker=dict(size=[max(16,r*0.75) for r in risks], color=ac, opacity=0.82,
                    line=dict(color="white",width=1.5)),
        hovertemplate="<b>%{text}</b><br>P(exceed)=%{x:.1f}%<br>ENS=%{y:.0f}MW<extra></extra>",
    ))
    fig.add_vline(x=EWS_THRESHOLDS["exceedance"]["amber"]*100,
        line_dash="dash",line_color="#f97316",line_width=1.2,
        annotation_text="AMBER",annotation_font_size=9)
    fig.add_hline(y=EWS_THRESHOLDS["ens_mw"]["amber"],
        line_dash="dash",line_color="#f97316",line_width=1.2)
    fig.update_layout(title="Threat matrix T+5min — size = risk score",
        xaxis=dict(title="Exceedance probability (%)", range=[0,100]),
        yaxis=dict(title="Predicted ENS (MW)", range=[0,max(ens_mw+[100])*1.2]),
        template=plotly_template(), height=360,
        margin=dict(l=20,r=20,t=50,b=20))
    return fig


def _alert_table(alerts: List[EWSAlert]) -> pd.DataFrame:
    return pd.DataFrame([{
        "Alert ID":a.alert_id, "Level":a.alert_level.name,
        "Place":a.place, "Hazard":a.hazard_type.name,
        "Horizon":f"T+{a.horizon_minutes}min",
        "Recipient":a.recipient_type.value,
        "Risk":f"{a.kpi_snapshot.get('risk',0):.1f}/100",
        "ENS (MW)":f"{a.kpi_snapshot.get('ens_mw',0):.1f}",
        "Exceedance %":f"{a.kpi_snapshot.get('exceedance_pct',0):.1f}%",
        "OOD score":f"{a.kpi_snapshot.get('ood_score',0):.3f}",
        "Total UNC %":f"{a.kpi_snapshot.get('total_unc_pct',0):.1f}%",
        "Escalated":"✅" if a.is_escalated else "—",
        "Generated":a.generated_at[:19],
    } for a in alerts]) if alerts else pd.DataFrame()


def _alert_viewer(alerts: List[EWSAlert]) -> None:
    """
    Renders alert cards: risk bar, KPI grid, actions, escalation chain.
    One card per place × horizon × alert level (deduplicated).
    """
    if not alerts:
        st.success("✅ All locations GREEN — no alerts dispatched.")
        return

    # Deduplicate
    seen: set = set()
    unique: List[EWSAlert] = []
    for a in alerts:
        key = f"{a.place}_{a.horizon_minutes}_{a.alert_level.name}"
        if key not in seen:
            seen.add(key)
            unique.append(a)

    st.caption(f"{len(unique)} alert(s) — expand any card for full detail")

    # Colour maps (light-mode safe, also work on dark bg)
    _badge_bg  = {AlertLevel.GREEN:"#d1fae5",AlertLevel.YELLOW:"#fef3c7",
                  AlertLevel.AMBER:"#fef3c7",AlertLevel.RED:"#fee2e2",
                  AlertLevel.CRITICAL:"#f3e8ff"}
    _badge_txt = {AlertLevel.GREEN:"#065f46",AlertLevel.YELLOW:"#92400e",
                  AlertLevel.AMBER:"#92400e",AlertLevel.RED:"#991b1b",
                  AlertLevel.CRITICAL:"#6b21a8"}
    _badge_brd = {AlertLevel.GREEN:"#6ee7b7",AlertLevel.YELLOW:"#fcd34d",
                  AlertLevel.AMBER:"#fcd34d",AlertLevel.RED:"#fca5a5",
                  AlertLevel.CRITICAL:"#d8b4fe"}
    _bar_col   = {AlertLevel.GREEN:"#10b981",AlertLevel.YELLOW:"#f59e0b",
                  AlertLevel.AMBER:"#d97706",AlertLevel.RED:"#dc2626",
                  AlertLevel.CRITICAL:"#9333ea"}
    _dot_col   = _bar_col

    for a in unique:
        lvl    = a.alert_level
        kpi    = a.kpi_snapshot
        risk   = kpi.get("risk", 0)
        h_label= EWS_HORIZON_LABELS.get(a.horizon_minutes,
                 f"T+{a.horizon_minutes}min").split("(")[0].strip()
        actions= [x for x in (a.recommended_actions or []) if x and x.strip()]

        b_bg   = _badge_bg.get(lvl, "#fef3c7")
        b_txt  = _badge_txt.get(lvl, "#92400e")
        b_brd  = _badge_brd.get(lvl, "#fcd34d")
        bar_c  = _bar_col.get(lvl, "#d97706")
        dot_c  = _dot_col.get(lvl, "#d97706")
        left_c = bar_c   # card left-border colour

        expander_label = (
            f"{lvl.name}  {a.place}  ·  {h_label}  ·  "
            f"{a.hazard_type.name.replace('_',' ')}  ·  Risk {risk:.0f}/100"
        )

        with st.expander(expander_label, expanded=False):

            # ── Header row: badge + title + risk bar ─────────────────
            risk_pct = clamp(risk, 0, 100)
            st.markdown(
                f'<div style="border-left:4px solid {left_c};border-radius:0 8px 8px 0;'
                f'padding:10px 14px;background:var(--color-background-secondary);'
                f'margin-bottom:12px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">'
                f'<span style="background:{b_bg};color:{b_txt};border:0.5px solid {b_brd};'
                f'border-radius:999px;padding:3px 10px;font-size:11px;font-weight:500;'
                f'white-space:nowrap;">{lvl.name}</span>'
                f'<span style="font-size:13px;font-weight:500;flex:1;min-width:140px;">{a.headline}</span>'
                f'<div style="display:flex;align-items:center;gap:6px;flex-shrink:0;">'
                f'<span style="font-size:12px;color:#6b7280;">Risk</span>'
                f'<div style="width:80px;height:7px;background:#e5e7eb;border-radius:999px;overflow:hidden;">'
                f'<div style="width:{risk_pct}%;height:100%;background:{bar_c};border-radius:999px;"></div></div>'
                f'<span style="font-size:13px;font-weight:500;color:{bar_c};">{risk:.0f}</span>'
                f'</div></div>',
                unsafe_allow_html=True,
            )

            # ── KPI grid ──────────────────────────────────────────────
            kpi_items = [
                ("Grid failure",  f"{kpi.get('gf_pct',0):.1f}%"),
                ("ENS",           f"{kpi.get('ens_mw',0):.0f} MW"),
                ("Exceedance P",  f"{kpi.get('exceedance_pct',0):.1f}%"),
                ("Confidence",    kpi.get("confidence","—")),
                ("Total UQ",      f"{kpi.get('total_unc_pct',0):.1f}%"),
                ("OOD score",     f"{kpi.get('ood_score',0):.3f}"),
            ]
            kpi_html = '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:12px;">'
            for label, val in kpi_items:
                kpi_html += (
                    f'<div style="background:var(--color-background-secondary);'
                    f'border-radius:8px;padding:8px 10px;">'
                    f'<div style="font-size:11px;color:#9ca3af;margin-bottom:2px;">{label}</div>'
                    f'<div style="font-size:15px;font-weight:500;">{val}</div></div>'
                )
            kpi_html += '</div>'
            st.markdown(kpi_html, unsafe_allow_html=True)

            # ── Actions + Escalation ──────────────────────────────────
            col_act, col_esc = st.columns([3, 2])

            with col_act:
                st.markdown(
                    '<div style="font-size:11px;font-weight:500;color:#9ca3af;'
                    'text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px;">'
                    'Recommended actions</div>',
                    unsafe_allow_html=True,
                )
                if actions:
                    acts_html = ""
                    for act in actions:
                        acts_html += (
                            f'<div style="display:flex;gap:8px;margin-bottom:5px;'
                            f'align-items:flex-start;">'
                            f'<div style="width:7px;height:7px;border-radius:50%;'
                            f'background:{dot_c};margin-top:5px;flex-shrink:0;"></div>'
                            f'<span style="font-size:12.5px;line-height:1.5;">{act}</span>'
                            f'</div>'
                        )
                    st.markdown(acts_html, unsafe_allow_html=True)
                else:
                    st.markdown(
                        '<span style="font-size:12.5px;color:#9ca3af;">'
                        'Monitor — no immediate action required.</span>',
                        unsafe_allow_html=True,
                    )

            with col_esc:
                st.markdown(
                    '<div style="font-size:11px;font-weight:500;color:#9ca3af;'
                    'text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px;">'
                    'Escalation chain</div>',
                    unsafe_allow_html=True,
                )
                esc_html = ""
                for i, step in enumerate(a.escalation_path or []):
                    esc_html += (
                        f'<div style="display:flex;gap:7px;align-items:center;'
                        f'padding:3px 0;border-bottom:0.5px solid #e5e7eb;">'
                        f'<div style="width:18px;height:18px;border-radius:50%;'
                        f'background:#eff6ff;color:#2563eb;font-size:10px;font-weight:500;'
                        f'display:flex;align-items:center;justify-content:center;'
                        f'flex-shrink:0;">{i+1}</div>'
                        f'<span style="font-size:12px;color:#6b7280;">{step}</span>'
                        f'</div>'
                    )
                st.markdown(esc_html or "<span style='font-size:12px;color:#9ca3af;'>—</span>",
                            unsafe_allow_html=True)

            # ── Footer ────────────────────────────────────────────────
            escalated_badge = (
                f'<span style="color:{bar_c};font-size:11px;">Escalated</span>'
                if a.is_escalated else
                '<span style="color:#9ca3af;font-size:11px;">Standard</span>'
            )
            st.markdown(
                f'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;'
                f'padding-top:8px;border-top:0.5px solid #e5e7eb;">'
                f'<span style="font-size:11px;color:#9ca3af;padding:2px 7px;'
                f'background:var(--color-background-secondary);border-radius:4px;">'
                f'{a.recipient_type.value}</span>'
                f'<span style="font-size:11px;color:#9ca3af;padding:2px 7px;'
                f'background:var(--color-background-secondary);border-radius:4px;">'
                f'ID: {a.alert_id}</span>'
                f'{escalated_badge}'
                f'</div>',
                unsafe_allow_html=True,
            )

# ── Main EWS tab ──────────────────────────────────────────────────────────

def render_ews_tab(region: str, active_scenario: str,
                   places: pd.DataFrame, outages: pd.DataFrame) -> None:
    """
    SAT-Guard EWS v3.0 Dashboard.

    Sections:
     A  System header + hero banner
     B  Architecture overview (expandable)
     C  KPI strip
     D  Place / horizon selectors
     E  Risk fan chart + exceedance bar
     F  Multi-horizon risk heatmap
     G  Uncertainty decomposition (4-component)
     H  Threat matrix
     I  9-model radar + lollipop CI comparison
     J  Feature importance (SHAP proxy)
     K  OOD gauges (Isolation Forest)
     L  Model performance matrix + weight chart
     M  Horizon decay + signal amplification
     N  Alert dispatch timeline
     O  Alert dispatch register (filterable)
     P  Full alert bodies (CAP format, expandable)
     Q  Model architecture cards (expandable per model)
     R  Recipient matrix reference
     S  Feature vector deep-dive
     T  EWS methodology note
     U  Export CSV (predictions, alerts, features)
    """
    st.markdown(APP_CSS, unsafe_allow_html=True)

    # ── A: Header ─────────────────────────────────────────────────────
    st.markdown(
        '<div class="card"><span style="font-size:22px;font-weight:950;color:white;">'
        '🛰 SAT-Guard EWS v3.0 — Advanced AI/ML Early Warning System</span><br>'
        '<span style="color:#94a3b8;font-size:13px;">'
        '9-model deep-learning ensemble with stacked generalisation · '
        'T+5min to T+24h horizons · '
        'Conformal prediction intervals · MC-Dropout uncertainty · '
        '4-component UQ decomposition · 9 government dispatch channels'
        '</span></div>', unsafe_allow_html=True)

    if places.empty:
        st.error("No place data — run the main pipeline first.")
        return

    # ── Run pipeline (session_state cache avoids dataclass serialisation error) ──
    _cache_key = f"ews_pipeline_{region}_{active_scenario}_{len(places)}"
    if _cache_key not in st.session_state:
        with st.spinner("🤖 Running 9-model ensemble: BiLSTM-Attn · TFT · WaveNet · CNN-BiLSTM · Neural ODE · Stacked GRU · N-BEATS · Kalman EKF · XGBoost…"):
            st.session_state[_cache_key] = run_ews_pipeline(
                region, active_scenario, places.to_dict("records"))
    res = st.session_state[_cache_key]

    preds   = res["predictions"]
    alerts  = res["alerts"]
    summary = res["summary"]
    fvs     = res["fvs"]
    shap_r  = res["shap"]
    anom_r  = res["anomaly"]

    # ── B: Architecture ───────────────────────────────────────────────
    lvl = summary["max_alert_level"]
    c   = ALERT_COLOUR[lvl]; bg = ALERT_BG[lvl]
    ts  = summary["run_ts"][:19].replace("T"," ")

    st.markdown(
        f'<div style="border:2px solid {c};background:{bg};border-radius:20px;'
        f'padding:16px 22px;margin-bottom:14px;">'
        f'<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;align-items:center;">'
        f'<div><span style="font-size:18px;font-weight:900;color:white;">🛰 SAT-Guard EWS v{EWS_VERSION}</span><br>'
        f'<span style="color:#94a3b8;font-size:12px;">{summary["places_monitored"]} locations · '
        f'{len(EWS_HORIZONS)} horizons · 9 models · {ts} UTC</span></div>'
        f'<div style="text-align:right;">{_badge(lvl)}<br>'
        f'<span style="color:#94a3b8;font-size:11px;">{summary["total_alerts_dispatched"]} alerts · '
        f'{len(summary["critical_places"])} critical</span></div></div>'
        f'<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;">'
        f'<span class="chip">Max exceedance: {summary["max_exceedance"]*100:.1f}%</span>'
        f'<span class="chip">Avg OOD: {summary["avg_ood"]:.3f}</span>'
        f'<span class="chip">Highest risk: {summary["highest_risk_place"]}</span>'
        f'<span class="chip">Scenario: {active_scenario}</span>'
        f'</div></div>', unsafe_allow_html=True)

    with st.expander("🔬 EWS v3.0 — Deep Learning Architecture Overview", expanded=False):
        st.markdown("""<div style="background:rgba(2,6,23,0.75);border:1px solid rgba(148,163,184,0.18);
border-radius:16px;padding:18px 22px;font-family:ui-monospace,monospace;font-size:11px;
color:#cbd5e1;line-height:2.0;">
<b style="color:#38bdf8;font-size:13px;">SAT-Guard EWS v3.0 — Stacked Generalisation Ensemble</b>
<pre style="margin:10px 0 0;color:#94a3b8;">
 LIVE DATA SOURCES
 ┌──────────────────────────────────────────────────────────────────────────┐
 │  Open-Meteo Weather  ·  Open-Meteo AQ  ·  NPG Outage Feed               │
 │  SAT-Guard Physics Model (risk, resilience, ENS, cascade, financials)    │
 └──────────────────────────────────────────────────────────────────────────┘
                                    ↓
 LAYER 1 — FEATURE ENGINEERING  (72 features, 8 groups)
 Meteo(13) · AQ(10) · Grid ops(12) · Physics(11) · Lags t-1/3/6(9)
 Calendar(6) · Derived/Interaction(6) · Advanced signals(5):
   rate_of_change_risk · risk_acceleration · pressure_impulse
   renewable_stress · grid_coherence
                                    ↓
 ┌────────────────────────────────────────────────────────────────────────┐
 │  LEVEL-1 MODELS  (diverse architectures for error decorrelation)       │
 │                                                                        │
 │  BiLSTM+Attention   TFT (Variable Selection)   WaveNet Dilated CNN     │
 │  Bidirectional       Known/unknown inputs        Dilation [1..128]     │
 │  w=0.20              w=0.18                      w=0.14                │
 │  RMSE=3.8            RMSE=3.5 ★                  RMSE=4.1              │
 │                                                                        │
 │  CNN-BiLSTM          Neural ODE                  Stacked GRU+Skip      │
 │  Branch A+B merge    Continuous-time dz/dt        3L + residual conn.  │
 │  w=0.13              w=0.12                      w=0.10                │
 │  RMSE=4.3            RMSE=4.0                    RMSE=4.5              │
 │                                                                        │
 │  N-BEATS Prob.       Kalman EKF                  XGBoost Baseline      │
 │  Trend+Season+Resid  Physics state [r,ṙ,r̈,gf]   100 trees, 0.4ms     │
 │  w=0.08              w=0.03                      w=0.02                │
 │  RMSE=4.6            RMSE=3.2 (smooth only)      RMSE=5.8              │
 │                                                                        │
 │  + Isolation Forest OOD detector (distributional uncertainty)         │
 └────────────────────────────────────────────────────────────────────────┘
                    ↓                         ↓
 ┌──────────────────────────────────────────────────────────────────────┐
 │  LEVEL-2 META-LEARNER  (Stacked Generalisation)                       │
 │  Ridge regression on L1 outputs + CRPS-calibrated Bayesian averaging  │
 │  Temperature scaling (T=1.15) → calibrated exceedance probability     │
 │  Conformal prediction → coverage-guaranteed 80% CI                   │
 │                                                                        │
 │  Uncertainty decomposition (quadrature):                              │
 │    Total = √(Epistemic² + Aleatoric² + Distributional²) + 0.3×Disagree│
 └──────────────────────────────────────────────────────────────────────┘
                                    ↓
 LAYER 4 — ALERT CLASSIFICATION  (GREEN → CRITICAL)
 Multi-criteria · Horizon penalty (T+24h: +20% threshold)
                                    ↓
 LAYER 5 — DISPATCH  (9 government / utility channels)
 DNO · NESO · Local Authority · NHS · Environment Agency
 Civil Contingencies (COBR) · Met Office · Police · Media (CAP v1.2)
</pre></div>""", unsafe_allow_html=True)

    st.markdown("---")

    # ── C: KPI strip ─────────────────────────────────────────────────
    k1,k2,k3,k4,k5,k6 = st.columns(6)
    k1.metric("Max alert",      lvl.name)
    k2.metric("Alerts sent",    str(summary["total_alerts_dispatched"]))
    k3.metric("Critical places",str(len(summary["critical_places"])))
    k4.metric("Max exceedance", f"{summary['max_exceedance']*100:.1f}%")
    k5.metric("Avg OOD score",  f"{summary['avg_ood']:.3f}")
    k6.metric("Highest risk",   summary["highest_risk_place"])
    st.markdown("---")

    # ── D: Selectors ─────────────────────────────────────────────────
    st.markdown("#### 📍 Location & Horizon Selection")
    sc1, sc2 = st.columns(2)
    with sc1:
        sel_place = st.selectbox("Location", sorted(preds.keys()), key="ews3_place")
    with sc2:
        h_opts = sorted({h for pv in preds.values() for h in pv})
        sel_h  = st.selectbox("Horizon (model deep-dive)", h_opts,
                               format_func=lambda h: EWS_HORIZON_LABELS.get(h,f"T+{h}min"),
                               key="ews3_hor")
    st.markdown("---")

    # ── E: Risk fan + exceedance ──────────────────────────────────────
    st.markdown("#### 📈 AI Risk Forecast — Conformal Prediction Intervals")
    fc1, fc2 = st.columns(2)
    with fc1: st.plotly_chart(_fig_risk_fan(preds, sel_place), use_container_width=True, key="ews3_fan")
    with fc2: st.plotly_chart(_fig_exceedance_bar(preds), use_container_width=True, key="ews3_eb")

    # ── F: Heatmap ────────────────────────────────────────────────────
    st.markdown("#### 🗺 Multi-Horizon Risk Heatmap")
    st.plotly_chart(_fig_heatmap(preds), use_container_width=True, key="ews3_hm")

    # ── G: Uncertainty decomposition ─────────────────────────────────
    st.markdown("#### 📊 Uncertainty Decomposition (4-component)")
    uc1, uc2 = st.columns(2)
    with uc1:
        st.plotly_chart(_fig_uncertainty_decomp(preds, sel_place), use_container_width=True, key="ews3_uc")
        st.markdown('<div class="note" style="font-size:11.5px;">'
                    '<b>Epistemic</b> — reducible with more training data or better architecture.<br>'
                    '<b>Aleatoric</b> — irreducible data noise (weather is inherently chaotic).<br>'
                    '<b>Distributional</b> — out-of-distribution score; high = novel compound event.<br>'
                    '<b>Disagreement</b> — inter-model spread; high = architectures diverge on this input.'
                    '</div>', unsafe_allow_html=True)
    with uc2:
        st.plotly_chart(_fig_threat_matrix(preds), use_container_width=True, key="ews3_tm")

    st.markdown("---")

    # ── I: 9-model radar + lollipop ──────────────────────────────────
    st.markdown("#### 🤖 9-Model Deep-Dive")
    if sel_place in preds and sel_h in preds[sel_place]:
        l1_preds = preds[sel_place][sel_h]["ensemble"]["l1_preds"]
        ens_r    = preds[sel_place][sel_h]["ensemble"]
        md1, md2 = st.columns(2)
        with md1:
            st.plotly_chart(_fig_model_radar(l1_preds, sel_place, sel_h),
                            use_container_width=True, key="ews3_mr")
        with md2:
            st.plotly_chart(_fig_architecture_comparison(l1_preds),
                            use_container_width=True, key="ews3_lp")

        # Summary table
        tbl = [{"Architecture":mp.arch.value.split("(")[0].strip()[:28],
                "Weight":f"{mp.weight:.2f}",
                "Point":f"{mp.point:.1f}",
                "Q10":f"{mp.q10:.1f}", "Q90":f"{mp.q90:.1f}",
                "Ep %":f"{mp.epistemic*100:.1f}",
                "Al %":f"{mp.aleatoric*100:.1f}",
                "RMSE":f"{mp.rmse_bench:.1f}",
                "Lat ms":f"{mp.inference_ms:.1f}"}
               for mp in l1_preds]
        st.dataframe(pd.DataFrame(tbl), use_container_width=True, hide_index=True)

        # Ensemble summary card
        po = preds[sel_place][sel_h]["prediction"]
        c_al = ALERT_COLOUR[po.alert_level]; bg_al = ALERT_BG[po.alert_level]
        st.markdown(
            f'<div style="background:{bg_al};border:1px solid {c_al}44;border-radius:12px;'
            f'padding:12px 16px;margin-top:8px;">'
            f'<div style="display:flex;gap:16px;flex-wrap:wrap;font-size:12.5px;color:#e0f2fe;">'
            f'<span><b>Alert</b>: <b style="color:{c_al};">{po.alert_level.name}</b></span>'
            f'<span><b>Hazard</b>: {po.hazard_type.name}</span>'
            f'<span><b>Risk</b>: {po.predicted_risk:.1f}/100</span>'
            f'<span><b>Grid fail</b>: {po.predicted_gf_pct:.1f}%</span>'
            f'<span><b>ENS</b>: {po.predicted_ens_mw:.1f} MW</span>'
            f'<span><b>Exceedance</b>: {po.exceedance_probability*100:.1f}%</span>'
            f'<span><b>Conf.</b>: {po.confidence_level.value}</span>'
            f'<span><b>Total UQ</b>: {po.total_unc*100:.1f}%</span>'
            f'</div>'
            f'<div style="margin-top:8px;font-size:12px;color:#94a3b8;">'
            f'Top drivers: <b>{po.top_driver_1.replace("_"," ")}</b> ({po.shap_1:.2f})  ·  '
            f'<b>{po.top_driver_2.replace("_"," ")}</b> ({po.shap_2:.2f})  ·  '
            f'<b>{po.top_driver_3.replace("_"," ")}</b> ({po.shap_3:.2f})'
            f'</div></div>',
            unsafe_allow_html=True)

    # ── J: SHAP ───────────────────────────────────────────────────────
    st.markdown("---")
    st.markdown("#### 🧠 Feature Importance (SHAP Proxy)")
    sh1, sh2 = st.columns([3,2])
    with sh1:
        if sel_place in shap_r:
            st.plotly_chart(_fig_shap(shap_r[sel_place], sel_place),
                            use_container_width=True, key="ews3_shap")
    with sh2:
        if sel_place in fvs:
            fv_d = fvs[sel_place].__dict__
            adv_rows = [
                {"Signal":"Rate of change risk",  "Value":f"{fv_d.get('rate_of_change_risk',0):+.3f}", "Note":"Leading indicator T+5min"},
                {"Signal":"Risk acceleration",    "Value":f"{fv_d.get('risk_acceleration',0):+.3f}",   "Note":"2nd derivative of risk"},
                {"Signal":"Pressure impulse",     "Value":f"{fv_d.get('pressure_impulse',0):.2f}",     "Note":"Storm precursor: |ΔP|×wind"},
                {"Signal":"Renewable stress",     "Value":f"{fv_d.get('renewable_stress',0):.3f}",     "Note":"1 − generation/demand"},
                {"Signal":"Grid coherence",       "Value":f"{fv_d.get('grid_coherence',0):.3f}",       "Note":"Spatial outage consistency"},
                {"Signal":"Grid stress index",    "Value":f"{fv_d.get('grid_stress_index',0):.4f}",    "Note":"Composite grid pressure"},
                {"Signal":"Wind × rain",          "Value":f"{fv_d.get('wind_x_rain',0):.2f}",          "Note":"Compound damage proxy"},
                {"Signal":"Compound × social",    "Value":f"{fv_d.get('compound_x_social',0):.2f}",    "Note":"Vulnerability-weighted hazard"},
            ]
            st.markdown("**Advanced signal values (live):**")
            st.dataframe(pd.DataFrame(adv_rows), use_container_width=True, hide_index=True)

    # ── K: OOD gauges ─────────────────────────────────────────────────
    st.markdown("---")
    st.markdown("#### 🔬 Out-of-Distribution Score (Isolation Forest)")
    st.caption("Score > 70% = feature combination outside training distribution → model uncertainty inflated.")
    st.plotly_chart(_fig_ood_gauges(preds, anom_r), use_container_width=True, key="ews3_ood")

    # ── L: Performance matrix + weights ──────────────────────────────
    st.markdown("---")
    st.markdown("#### 📐 Model Performance & Ensemble Configuration")
    pm1, pm2 = st.columns(2)
    with pm1: st.plotly_chart(_fig_model_performance_matrix(), use_container_width=True, key="ews3_pm")
    with pm2: st.plotly_chart(_fig_model_weight_bar(),         use_container_width=True, key="ews3_wb")

    # ── M: Horizon decay ─────────────────────────────────────────────
    st.plotly_chart(_fig_horizon_decay(), use_container_width=True, key="ews3_hd")

    # ── N: Alert timeline ─────────────────────────────────────────────
    st.markdown("---")
    st.markdown("#### 🚨 Alert Dispatch Timeline")
