# 1.5  VISUALISATION — VERIFICATION CHARTS
# ────────────────────────────────────────────────────────────────────────────

def _fig_val_rmse_grouped(results: List[VerificationResult]) -> go.Figure:
    """Grouped bar: RMSE by model × horizon."""
    models   = sorted({r.model_arch for r in results})
    horizons = sorted({r.horizon_min for r in results})
    h_labels = [EWS_HORIZON_LABELS.get(h,"").split("(")[0].strip() for h in horizons]
    colours  = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308",
                "#ef4444","#94a3b8","#0ea5e9","#84cc16","#f43f5e"]

    fig = go.Figure()
    for i, mname in enumerate(models):
        short = mname.split("(")[0].strip()[:22]
        rmses = []
        for h in horizons:
            match = next((r for r in results if r.model_arch==mname and r.horizon_min==h), None)
            rmses.append(match.rmse if match else 0)
        fig.add_trace(go.Bar(
            name=short, x=h_labels, y=rmses,
            marker_color=colours[i % len(colours)], opacity=0.85,
        ))
    fig.add_hline(y=5.0, line_dash="dot", line_color="#64748b", line_width=1,
                  annotation_text="RMSE = 5 (practical threshold)", annotation_font_size=9)
    fig.update_layout(
        barmode="group",
        title="Validation RMSE by model × forecast horizon",
        xaxis_title="Horizon", yaxis_title="RMSE (risk-score units)",
        template=plotly_template(), height=380,
        margin=dict(l=20,r=20,t=50,b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.45, font=dict(size=8)),
    )
    return fig


def _fig_val_crps_skill(results: List[VerificationResult]) -> go.Figure:
    """Line chart: CRPS skill score by model × horizon."""
    models   = sorted({r.model_arch for r in results})
    horizons = sorted({r.horizon_min for r in results})
    h_labels = [f"T+{h}m" for h in horizons]
    colours  = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308",
                "#ef4444","#94a3b8","#0ea5e9","#84cc16","#f43f5e"]

    fig = go.Figure()
    for i, mname in enumerate(models):
        short = mname.split("(")[0].strip()[:22]
        skills = []
        for h in horizons:
            match = next((r for r in results if r.model_arch==mname and r.horizon_min==h), None)
            skills.append(match.crps_skill if match else 0)
        fig.add_trace(go.Scatter(
            name=short, x=h_labels, y=skills, mode="lines+markers",
            line=dict(color=colours[i % len(colours)], width=2),
            marker=dict(size=7),
        ))
    fig.add_hline(y=0, line_dash="dash", line_color="#64748b", line_width=1,
                  annotation_text="Climatology baseline", annotation_font_size=9)
    fig.update_layout(
        title="Probabilistic skill score (CRPS — vs climatological baseline)",
        xaxis_title="Horizon",
        yaxis_title="CRPS Skill Score  (higher = better)",
        template=plotly_template(), height=360,
        margin=dict(l=20,r=20,t=50,b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.42, font=dict(size=8)),
    )
    return fig


def _fig_reliability_diagram(
    records: List[HindcastRecord],
    model_name: str,
) -> go.Figure:
    """Reliability (calibration) diagram."""
    bcs, obs_f, counts = compute_reliability_data(records, model_name)
    if not bcs:
        return go.Figure()

    fig = go.Figure()
    # Perfect calibration diagonal
    fig.add_trace(go.Scatter(
        x=[0, 1], y=[0, 1], mode="lines",
        line=dict(color="#64748b", width=1.5, dash="dash"),
        name="Perfect calibration",
    ))
    # Climatology line
    clim_freq = sum(r.exceedance_observed for r in records
                    if r.model_arch == model_name) / max(
        len([r for r in records if r.model_arch == model_name]), 1)
    fig.add_hline(y=clim_freq, line_dash="dot", line_color="#22c55e", line_width=1,
                  annotation_text=f"Climatology ({clim_freq*100:.0f}%)", annotation_font_size=9)

    # Observed frequencies (with nan handling)
    valid_x = [bcs[i] for i, f in enumerate(obs_f) if not math.isnan(f)]
    valid_y = [obs_f[i] for i, f in enumerate(obs_f) if not math.isnan(f)]
    valid_c = [counts[i] for i, f in enumerate(obs_f) if not math.isnan(f)]

    fig.add_trace(go.Scatter(
        x=valid_x, y=valid_y, mode="lines+markers",
        name=model_name.split("(")[0].strip()[:20],
        line=dict(color="#38bdf8", width=2.5),
        marker=dict(size=[max(6, min(20, c//3)) for c in valid_c],
                    color="#38bdf8", line=dict(color="white", width=1.5)),
        hovertemplate="Forecast: %{x:.2f}<br>Observed freq: %{y:.2f}<extra></extra>",
    ))
    # Shading: over-forecasting and under-forecasting regions
    fig.add_trace(go.Scatter(
        x=[0,1,1,0], y=[0,0,1,0], fill="toself",
        fillcolor="rgba(249,115,22,0.05)", line=dict(color="rgba(0,0,0,0)"),
        name="Over-forecast region", showlegend=False,
    ))
    fig.update_layout(
        title=f"Reliability diagram — {model_name.split('(')[0].strip()[:28]}",
        xaxis=dict(title="Forecast probability", range=[0, 1]),
        yaxis=dict(title="Observed frequency",   range=[0, 1]),
        template=plotly_template(), height=340,
        margin=dict(l=20,r=20,t=50,b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.28),
    )
    return fig


def _fig_rank_histogram(
    records: List[HindcastRecord],
    model_name: str,
) -> go.Figure:
    """Rank (Talagrand / PIT) histogram."""
    hist = compute_rank_histogram(records, model_name)
    n    = len(hist)
    x    = [f"{i/n:.2f}–{(i+1)/n:.2f}" for i in range(n)]
    flat = 1 / n

    fig = go.Figure()
    fig.add_trace(go.Bar(
        x=x, y=hist, marker_color="#38bdf8", opacity=0.82, name="Rank frequency",
    ))
    fig.add_hline(y=flat, line_dash="dash", line_color="#22c55e", line_width=1.5,
                  annotation_text="Ideal (uniform)", annotation_font_size=9)
    fig.update_layout(
        title=f"PIT histogram — {model_name.split('(')[0].strip()[:28]}",
        xaxis_title="Probability integral transform (PIT)",
        yaxis_title="Relative frequency",
        template=plotly_template(), height=280,
        margin=dict(l=20,r=20,t=50,b=20),
    )
    return fig


def _fig_contingency_heatmap(
    results: List[VerificationResult],
    horizon: int = 5,
) -> go.Figure:
    """Heatmap: POD × (1-FAR) = ROC space for each model at given horizon."""
    recs_h = [r for r in results if r.horizon_min == horizon]
    if not recs_h:
        return go.Figure()

    fig = go.Figure()
    colours = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308",
               "#ef4444","#94a3b8","#0ea5e9","#84cc16","#f43f5e"]

    for i, r in enumerate(sorted(recs_h, key=lambda x: -x.csi)):
        short = r.model_arch.split("(")[0].strip()[:22]
        fig.add_trace(go.Scatter(
            x=[1 - r.far], y=[r.pod],
            mode="markers+text", text=[short],
            textposition="top center", textfont=dict(size=9),
            marker=dict(size=max(12, r.csi*40),
                        color=colours[i % len(colours)],
                        opacity=0.85,
                        line=dict(color="white", width=1.5)),
            name=short,
            hovertemplate=(f"<b>{short}</b><br>"
                           f"POD={r.pod:.2f}  FAR={r.far:.2f}<br>"
                           f"CSI={r.csi:.2f}  HSS={r.hss:.2f}<extra></extra>"),
        ))

    # Diagonal (no skill)
    fig.add_trace(go.Scatter(
        x=[0,1], y=[0,1], mode="lines",
        line=dict(color="#64748b", width=1, dash="dash"),
        name="No skill", showlegend=False,
    ))
    fig.update_layout(
        title=f"ROC plot — T+{horizon}min  (size = CSI score)",
        xaxis=dict(title="1 − False Alarm Rate", range=[0,1.05]),
        yaxis=dict(title="Probability of Detection", range=[0,1.05]),
        template=plotly_template(), height=380,
        margin=dict(l=20,r=20,t=50,b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.38, font=dict(size=8)),
    )
    return fig


def _fig_coverage_test(results: List[VerificationResult]) -> go.Figure:
    """Bar chart: empirical 80% CI coverage vs 80% nominal for each model × horizon."""
    models   = sorted({r.model_arch for r in results})
    horizons = sorted({r.horizon_min for r in results})
    h_labels = [f"T+{h}m" for h in horizons]
    colours  = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308",
                "#ef4444","#94a3b8","#0ea5e9","#84cc16","#f43f5e"]

    fig = go.Figure()
    for i, mname in enumerate(models):
        short = mname.split("(")[0].strip()[:20]
        covs  = []
        for h in horizons:
            match = next((r for r in results if r.model_arch==mname and r.horizon_min==h), None)
            covs.append(match.coverage_80pct * 100 if match else 0)
        fig.add_trace(go.Bar(
            name=short, x=h_labels, y=covs,
            marker_color=colours[i % len(colours)], opacity=0.82,
        ))
    fig.add_hline(y=80, line_dash="dash", line_color="#22c55e", line_width=2,
                  annotation_text="80% nominal target", annotation_font_size=10)
    fig.add_hrect(y0=75, y1=85, fillcolor="rgba(34,197,94,0.07)",
                  line=dict(color="rgba(0,0,0,0)"))
    fig.update_layout(
        barmode="group",
        title="Empirical 80% CI coverage (nominal target = 80%)",
        yaxis=dict(title="Coverage (%)", range=[40, 100]),
        template=plotly_template(), height=360,
        margin=dict(l=20,r=20,t=50,b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.42, font=dict(size=8)),
    )
    return fig


def _fig_dm_test(results: List[VerificationResult]) -> go.Figure:
    """Bar: Diebold-Mariano statistic vs persistence for all model × T+5min."""
    recs_5 = sorted([r for r in results if r.horizon_min == 5],
                    key=lambda x: -x.dm_stat)
    names  = [r.model_arch.split("(")[0].strip()[:24] for r in recs_5]
    dm_s   = [r.dm_stat for r in recs_5]
    cols   = ["#22c55e" if d > 0 else "#ef4444" for d in dm_s]

    fig = go.Figure(go.Bar(
        y=names[::-1], x=dm_s[::-1], orientation="h",
        marker_color=cols[::-1], opacity=0.88,
        text=[f"{d:+.3f}" for d in dm_s[::-1]], textposition="outside",
    ))
    fig.add_vline(x=0, line_color="#64748b", line_width=1.5)
    fig.update_layout(
        title="Diebold-Mariano test vs persistence (T+5min)  green = beats persistence",
        xaxis_title="DM statistic (positive = better than persistence)",
        template=plotly_template(), height=360,
        margin=dict(l=20,r=20,t=50,b=20),
    )
    return fig


def _fig_economic_value(results: List[VerificationResult]) -> go.Figure:
    """Economic value score at cost-loss ratio 0.3 for each model × horizon."""
    models   = sorted({r.model_arch for r in results})
    horizons = sorted({r.horizon_min for r in results})
    h_labels = [f"T+{h}m" for h in horizons]
    colours  = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308",
                "#ef4444","#94a3b8","#0ea5e9","#84cc16","#f43f5e"]

    fig = go.Figure()
    for i, mname in enumerate(models):
        short = mname.split("(")[0].strip()[:20]
        evs   = []
        for h in horizons:
            match = next((r for r in results if r.model_arch==mname and r.horizon_min==h), None)
            evs.append(match.economic_value if match else 0)
        fig.add_trace(go.Scatter(
            name=short, x=h_labels, y=evs, mode="lines+markers",
            line=dict(color=colours[i % len(colours)], width=2),
            marker=dict(size=8),
        ))
    fig.add_hline(y=0, line_dash="dash", line_color="#64748b", line_width=1)
    fig.update_layout(
        title="Decision-theoretic economic value score (C/L = 0.3)",
        xaxis_title="Horizon",
        yaxis_title="Economic value score  (0 = no value, 1 = perfect)",
        template=plotly_template(), height=340,
        margin=dict(l=20,r=20,t=50,b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.40, font=dict(size=8)),
    )
    return fig


def _fig_sharpness_hist(records: List[HindcastRecord], model_name: str) -> go.Figure:
    """Sharpness histogram: distribution of CI widths."""
    recs_m = [r for r in records if r.model_arch == model_name]
    widths = [r.forecast_q90 - r.forecast_q10 for r in recs_m if r.forecast_q90 > r.forecast_q10]
    if not widths:
        return go.Figure()

    fig = go.Figure(go.Histogram(
        x=widths, nbinsx=20, marker_color="#38bdf8", opacity=0.82,
    ))
    mean_w = sum(widths) / len(widths)
    fig.add_vline(x=mean_w, line_dash="dash", line_color="#f97316", line_width=2,
                  annotation_text=f"Mean {mean_w:.1f}", annotation_font_size=10)
    fig.update_layout(
        title=f"Sharpness (CI width distribution) — {model_name.split('(')[0].strip()[:26]}",
        xaxis_title="80% CI width (risk-score units)",
        yaxis_title="Count",
        template=plotly_template(), height=280,
        margin=dict(l=20,r=20,t=50,b=20),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 1.6  VERIFICATION SUMMARY TABLE
# ────────────────────────────────────────────────────────────────────────────

def build_verification_summary_df(results: List[VerificationResult]) -> pd.DataFrame:
    rows = []
    for r in sorted(results, key=lambda x: (x.horizon_min, x.rmse)):
        rows.append({
            "Model":           r.model_arch.split("(")[0].strip()[:26],
            "Horizon":         EWS_HORIZON_LABELS.get(r.horizon_min,"").split("(")[0].strip(),
            "N":               r.n_records,
            "RMSE":            f"{r.rmse:.2f}",
            "MAE":             f"{r.mae:.2f}",
            "Bias":            f"{r.mean_bias:+.2f}",
            "CRPS":            f"{r.crps_mean:.4f}",
            "Skill":           f"{r.crps_skill:.3f}",
            "Coverage 80%":    f"{r.coverage_80pct*100:.1f}%",
            "Sharp.":          f"{r.sharpness:.3f}",
            "POD":             f"{r.pod:.2f}",
            "FAR":             f"{r.far:.2f}",
            "CSI":             f"{r.csi:.2f}",
            "HSS":             f"{r.hss:.2f}",
            "GSS":             f"{r.gss:.2f}",
            "DM stat":         f"{r.dm_stat:+.3f}",
            "Econ. Value":     f"{r.economic_value:.3f}",
        })
    return pd.DataFrame(rows)


# ────────────────────────────────────────────────────────────────────────────
# 1.7  STREAMLIT RENDER FUNCTION
# ────────────────────────────────────────────────────────────────────────────

def render_ews_validation_section(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
) -> None:
    """
    Render the full EWS Validation sub-tab.

    Sections:
      A  KPI strip (top-level metrics)
      B  RMSE grouped bar (all models × horizons)
      C  CRPS skill score lines
      D  Coverage test (80% CI)
      E  ROC plot (POD vs 1-FAR)
      F  Reliability diagram + PIT histogram (selectable model)
      G  Sharpness histogram
      H  Diebold-Mariano test
      I  Economic value score
      J  Full verification table (sortable)
    """
    st.markdown("#### ✅ Hindcast Validation & Probabilistic Verification")
    st.caption(
        "30-day rolling hindcast: EWS forecast–observation pairs compared against "
        "realised UK grid risk outcomes. Statistics computed per model × horizon. "
        "In production: queries live time-series DB. Here: synthetic from calibrated "
        "noise distributions matching published benchmark RMSEs."
    )

    with st.spinner("Computing hindcast verification statistics…"):
        hc_records = generate_hindcast_dataset(preds, n_days=30)
        vr_results = compute_verification_results(hc_records)

    if not vr_results:
        st.warning("No verification data available.")
        return

    # ── A: KPI strip ──────────────────────────────────────────────────
    ensemble_r5 = next((r for r in vr_results
                        if "Ensemble" in r.model_arch and r.horizon_min == 5), None)
    ensemble_r24= next((r for r in vr_results
                        if "Ensemble" in r.model_arch and r.horizon_min == 1440), None)

    v1,v2,v3,v4,v5,v6 = st.columns(6)
    v1.metric("Best RMSE (T+5)",  f"{min(r.rmse for r in vr_results if r.horizon_min==5):.2f}")
    v2.metric("Best CRPS skill",  f"{max(r.crps_skill for r in vr_results):.3f}")
    v3.metric("Ensemble POD (T+5)",
              f"{ensemble_r5.pod*100:.0f}%" if ensemble_r5 else "N/A")
    v4.metric("Ensemble FAR (T+5)",
              f"{ensemble_r5.far*100:.0f}%" if ensemble_r5 else "N/A")
    v5.metric("Coverage (T+5)",
              f"{ensemble_r5.coverage_80pct*100:.1f}%" if ensemble_r5 else "N/A")
    v6.metric("Economic value",
              f"{ensemble_r5.economic_value:.3f}" if ensemble_r5 else "N/A")

    st.markdown("---")

    # ── B + C: RMSE + CRPS ────────────────────────────────────────────
    bc1, bc2 = st.columns(2)
    with bc1: st.plotly_chart(_fig_val_rmse_grouped(vr_results),  use_container_width=True, key="val_rmse")
    with bc2: st.plotly_chart(_fig_val_crps_skill(vr_results),    use_container_width=True, key="val_crps")

    # ── D + E: Coverage + ROC ─────────────────────────────────────────
    de1, de2 = st.columns(2)
    with de1: st.plotly_chart(_fig_coverage_test(vr_results),     use_container_width=True, key="val_cov")
    with de2: st.plotly_chart(_fig_contingency_heatmap(vr_results,5), use_container_width=True, key="val_roc")

    # ── F: Reliability + PIT (model selector) ─────────────────────────
    st.markdown("##### Reliability & Rank Histogram (select model)")
    model_options = sorted({r.model_arch for r in vr_results})
    sel_model = st.selectbox("Model", model_options, key="val_model_sel")

    f1, f2 = st.columns(2)
    with f1: st.plotly_chart(_fig_reliability_diagram(hc_records, sel_model),
                              use_container_width=True, key="val_rel")
    with f2: st.plotly_chart(_fig_rank_histogram(hc_records, sel_model),
                              use_container_width=True, key="val_pit")

    # ── G: Sharpness ──────────────────────────────────────────────────
    st.plotly_chart(_fig_sharpness_hist(hc_records, sel_model),
                    use_container_width=True, key="val_sharp")

    # ── H + I: DM test + Economic value ──────────────────────────────
    hi1, hi2 = st.columns(2)
    with hi1: st.plotly_chart(_fig_dm_test(vr_results),           use_container_width=True, key="val_dm")
    with hi2: st.plotly_chart(_fig_economic_value(vr_results),    use_container_width=True, key="val_ev")

    # ── J: Full table ─────────────────────────────────────────────────
    st.markdown("##### Full Verification Table")
    st.caption("Sortable by any column. All metrics for all models × horizons.")
    vdf = build_verification_summary_df(vr_results)
    st.dataframe(vdf, use_container_width=True, hide_index=True)

    # Methodology note
    with st.expander("📖 Verification methodology", expanded=False):
        st.markdown("""<div class="note">
<b>RMSE</b> — Root Mean Squared Error on point estimates. Penalises large errors heavily.
<br><b>MAE</b>  — Mean Absolute Error. More robust to outliers than RMSE.
<br><b>CRPS</b> — Continuous Ranked Probability Score. Proper scoring rule for probabilistic
forecasts; accounts for both sharpness and calibration. Lower = better.
CRPS = 0 for a perfect deterministic forecast matching observed value.
<br><b>Skill score</b> — CRPS skill vs climatological baseline (naive frequency forecast).
Positive = better than climatology.
<br><b>Coverage</b> — Fraction of observations falling within the 80% CI. Should be ~80%.
Under-coverage → intervals too narrow (overconfident).
Over-coverage → intervals too wide (underconfident).
<br><b>POD</b> — Probability of Detection = TP / (TP + FN). Fraction of events that were warned.
<br><b>FAR</b> — False Alarm Ratio = FP / (FP + TP). Fraction of warnings that were false.
<br><b>CSI</b> — Critical Success Index = TP / (TP + FP + FN). Penalises both misses and false alarms.
<br><b>HSS</b> — Heidke Skill Score. Skill relative to random chance. 1 = perfect, 0 = no skill.
<br><b>GSS / ETS</b> — Gilbert Skill Score (Equitable Threat Score). Accounts for hits due to chance.
<br><b>DM stat</b> — Diebold-Mariano test statistic vs persistence forecast. Positive = model beats persistence.
<br><b>Economic value</b> — Decision-theoretic score at cost-loss ratio C/L = 0.3 (typical DNO storm
preparation cost vs loss from an unwarned major outage). 1 = perfect, 0 = no value.
</div>""", unsafe_allow_html=True)

