# ────────────────────────────────────────────────────────────────────────────
# 2.1  HISTORICAL EVENT CATALOGUE
# ────────────────────────────────────────────────────────────────────────────

@dataclass
class HistoricalEvent:
    """A documented UK power-grid hazard event with verified outcomes."""
    name:                str
    date:                str       # YYYY-MM-DD (peak impact)
    region:              str
    hazard_type:         HazardType
    # Meteorological peak conditions
    peak_wind_ms:        float
    peak_gust_ms:        float
    peak_precip_mmh:     float
    peak_temp_c:         float
    min_pressure_hpa:    float
    pressure_fall_3h:    float     # hPa/3h (negative = falling)
    # Grid outcomes
    peak_risk_score:     float
    customers_off:       int
    peak_ens_mw:         float
    total_loss_gbp_m:    float
    restoration_hours:   float
    substations_affected:int
    # EWS retrospective
    ews_t24h_level:      str       # what would have been issued 24h before
    ews_t6h_level:       str
    ews_t1h_level:       str
    ews_t5m_level:       str
    earliest_warning_h:  float     # hours of earliest AMBER+ warning
    # Context
    description:         str
    lessons_learned:     str
    ofgem_reference:     str = ""


