# ────────────────────────────────────────────────────────────────────────────
# 2.2  RETROSPECTIVE EWS PERFORMANCE ANALYSER
# ────────────────────────────────────────────────────────────────────────────

def _alert_level_from_str(s: str) -> AlertLevel:
    try:
        return AlertLevel[s.upper()]
    except KeyError:
        return AlertLevel.GREEN


def build_retrospective_df() -> pd.DataFrame:
    """Build a summary DataFrame of retrospective EWS performance."""
    rows = []
    for ev in EWS_HISTORICAL_EVENTS:
        alert_t24 = _alert_level_from_str(ev.ews_t24h_level)
        alert_t6  = _alert_level_from_str(ev.ews_t6h_level)
        alert_t1  = _alert_level_from_str(ev.ews_t1h_level)
        alert_t5m = _alert_level_from_str(ev.ews_t5m_level)
        # Was there sufficient warning for crew pre-positioning? (need ≥ 6h RED)
        adequate_warning = (
            alert_t6.value >= AlertLevel.RED.value or
            (ev.earliest_warning_h >= 6 and alert_t6.value >= AlertLevel.AMBER.value)
        )
        rows.append({
            "Event":          ev.name,
            "Date":           ev.date,
            "Region":         ev.region,
            "Hazard":         ev.hazard_type.name,
            "Peak risk":      ev.peak_risk_score,
            "Customers off":  f"{ev.customers_off:,}",
            "ENS peak (MW)":  ev.peak_ens_mw,
            "Loss (£M)":      ev.total_loss_gbp_m,
            "T+24h alert":    ev.ews_t24h_level,
            "T+6h alert":     ev.ews_t6h_level,
            "T+1h alert":     ev.ews_t1h_level,
            "T+5min alert":   ev.ews_t5m_level,
            "Earliest warn.": f"{ev.earliest_warning_h:.0f}h",
            "Adequate warn.": "✅" if adequate_warning else "⚠️",
        })
    return pd.DataFrame(rows)


# ────────────────────────────────────────────────────────────────────────────
# 2.3  EVENT PROFILE CHARTS
# ────────────────────────────────────────────────────────────────────────────

def _fig_event_timeline_scatter() -> go.Figure:
    """Scatter: events by date × peak risk, sized by financial loss."""
    events = EWS_HISTORICAL_EVENTS
    haz_col= {
        HazardType.WIND:          "#38bdf8",
        HazardType.FLOOD:         "#3b82f6",
        HazardType.HEATWAVE:      "#f97316",
        HazardType.RENEWABLE_GAP: "#22c55e",
        HazardType.AQI_SPIKE:     "#a855f7",
        HazardType.GRID_FAILURE:  "#ef4444",
        HazardType.COMPOUND:      "#f43f5e",
    }

    fig = go.Figure()
    for haz in set(ev.hazard_type for ev in events):
        evs = [e for e in events if e.hazard_type == haz]
        fig.add_trace(go.Scatter(
            x=[e.date for e in evs],
            y=[e.peak_risk_score for e in evs],
            mode="markers+text",
            name=haz.name,
            text=[e.name for e in evs],
            textposition="top center",
            textfont=dict(size=9),
            marker=dict(
                size=[max(12, min(45, e.total_loss_gbp_m * 0.45)) for e in evs],
                color=haz_col.get(haz, "#94a3b8"),
                opacity=0.85,
                line=dict(color="white", width=1.5),
            ),
            hovertemplate=(
                "<b>%{text}</b><br>"
                "Date: %{x}<br>"
                "Peak risk: %{y:.0f}/100<br>"
                "<extra></extra>"
            ),
        ))

    for lbl, th, col in [("AMBER",55,"#f97316"),("RED",72,"#ef4444"),("CRITICAL",88,"#a855f7")]:
        fig.add_hline(y=th, line_dash="dash", line_color=col, line_width=1.2,
                      annotation_text=lbl, annotation_font_size=9)

    fig.update_layout(
        title="Historical hazard events (2021–2023)  |  size = financial loss",
        xaxis_title="Event date",
        yaxis=dict(title="Peak risk score", range=[0, 105]),
        template=plotly_template(), height=440,
        margin=dict(l=20, r=20, t=55, b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.28),
    )
    return fig


def _fig_event_alert_escalation() -> go.Figure:
    """Gantt-style: alert level escalation through horizons for each event."""
    alert_scores = {"GREEN": 0, "YELLOW": 1, "AMBER": 2, "RED": 3, "CRITICAL": 4}
    horizons_labels = ["T+24h", "T+6h", "T+1h", "T+5min"]

    fig = go.Figure()
    colours = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308",
               "#ef4444","#94a3b8","#0ea5e9"]

    for i, ev in enumerate(EWS_HISTORICAL_EVENTS):
        levels = [
            alert_scores.get(ev.ews_t24h_level, 0),
            alert_scores.get(ev.ews_t6h_level,  0),
            alert_scores.get(ev.ews_t1h_level,  0),
            alert_scores.get(ev.ews_t5m_level,  0),
        ]
        fig.add_trace(go.Scatter(
            x=horizons_labels, y=levels,
            mode="lines+markers",
            name=f"{ev.name} ({ev.date[:7]})",
            line=dict(color=colours[i % len(colours)], width=2.5),
            marker=dict(size=10, line=dict(color="white", width=1.5)),
        ))

    fig.update_layout(
        title="Alert level escalation through forecast horizons (all events)",
        xaxis_title="Forecast horizon",
        yaxis=dict(
            title="Alert level",
            tickvals=[0,1,2,3,4],
            ticktext=["GREEN","YELLOW","AMBER","RED","CRITICAL"],
            range=[-0.3, 4.5],
        ),
        template=plotly_template(), height=420,
        margin=dict(l=20, r=20, t=55, b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.32, font=dict(size=9)),
    )
    return fig


def _fig_event_comparison_radar(event: HistoricalEvent) -> go.Figure:
    """Radar chart of event characteristics (normalised 0–100)."""
    dims = {
        "Peak wind":     clamp(event.peak_wind_ms / 45 * 100, 0, 100),
        "Peak rain":     clamp(event.peak_precip_mmh / 40 * 100, 0, 100),
        "Peak risk":     clamp(event.peak_risk_score, 0, 100),
        "Customers off": clamp(event.customers_off / 200_000 * 100, 0, 100),
        "ENS (MW)":      clamp(event.peak_ens_mw / 1000 * 100, 0, 100),
        "Loss (£M)":     clamp(event.total_loss_gbp_m / 100 * 100, 0, 100),
        "Duration (h)":  clamp(event.restoration_hours / 15 * 100, 0, 100),
        "Substations":   clamp(event.substations_affected / 30 * 100, 0, 100),
        "P fall (hPa)":  clamp(abs(event.pressure_fall_3h) / 8 * 100, 0, 100),
    }
    cats = list(dims.keys()) + [list(dims.keys())[0]]
    vals = list(dims.values()) + [list(dims.values())[0]]

    haz_col = {
        HazardType.WIND: "#38bdf8", HazardType.FLOOD: "#3b82f6",
        HazardType.HEATWAVE: "#f97316", HazardType.RENEWABLE_GAP: "#22c55e",
        HazardType.AQI_SPIKE: "#a855f7", HazardType.GRID_FAILURE: "#ef4444",
    }
    col = haz_col.get(event.hazard_type, "#94a3b8")
    rr,gg,bb = int(col[1:3],16), int(col[3:5],16), int(col[5:7],16)

    fig = go.Figure(go.Scatterpolar(
        r=vals, theta=cats, fill="toself", name=event.name,
        line=dict(color=col, width=2.5),
        fillcolor=f"rgba({rr},{gg},{bb},0.15)",
    ))
    fig.update_layout(
        polar=dict(radialaxis=dict(visible=True, range=[0, 100])),
        title=f"{event.name} — Event profile",
        template=plotly_template(), height=360,
        margin=dict(l=22, r=22, t=55, b=22),
    )
    return fig


def _fig_lead_time_value() -> go.Figure:
    """
    Decision-value curve: how much financial loss can be avoided
    as a function of warning lead time.

    Based on UK DNO operational experience:
      0–5 min:   crew safety positioning only (~5% reducible)
      5–30 min:  emergency dispatch begins (~12%)
      30min–2h:  crew pre-positioning at depots (~25%)
      2h–6h:     full storm pre-position + PSR calls (~45%)
      6h–24h:    mutual aid + material pre-order (~62%)
      24h+:      advance contractor + public warning (~72%)
    """
    lead_hours = [0, 0.083, 0.25, 0.5, 1, 2, 4, 6, 8, 12, 18, 24, 36, 48]
    # Reducible fraction (sigmoid-like based on operational constraints)
    reduce_frac = [0.00, 0.05, 0.10, 0.14, 0.20, 0.28, 0.38, 0.45,
                   0.52, 0.58, 0.64, 0.68, 0.71, 0.72]

    # Expected value of warning at each lead time (£M, assuming avg loss £50M)
    avg_loss_m = 50.0
    ev_warn    = [avg_loss_m * r for r in reduce_frac]

    # Mark key operational thresholds
    ops_milestones = [
        (0.083, "T+5min\nCrew safety"),
        (0.5,   "T+30min\nEmergency despatch"),
        (2,     "T+2h\nPre-position"),
        (6,     "T+6h\nMutual aid"),
        (24,    "T+24h\nFull preparation"),
    ]

    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=lead_hours, y=ev_warn, mode="lines+markers",
        name="Expected value of warning",
        line=dict(color="#22c55e", width=3),
        marker=dict(size=9, color="#22c55e", line=dict(color="white", width=1.5)),
        fill="tozeroy", fillcolor="rgba(34,197,94,0.09)",
    ))
    fig.add_trace(go.Scatter(
        x=lead_hours, y=[r*100 for r in reduce_frac],
        name="Reducible loss fraction (%)",
        line=dict(color="#38bdf8", width=2, dash="dot"),
        marker=dict(size=7), yaxis="y2",
    ))

    for x_m, label in ops_milestones:
        fig.add_vline(x=x_m, line_dash="dash", line_color="#64748b", line_width=1,
                      annotation_text=label, annotation_font_size=8,
                      annotation_textangle=-90)

    fig.update_layout(
        title="Lead-time value curve: expected loss reduction vs warning lead time",
        xaxis=dict(title="Warning lead time (hours)", type="log",
                   tickvals=[0.083,0.25,0.5,1,2,4,6,12,24,48],
                   ticktext=["5m","15m","30m","1h","2h","4h","6h","12h","24h","48h"]),
        yaxis=dict(title="Expected value of warning (£M)", range=[0,40]),
        yaxis2=dict(title="Reducible fraction (%)", overlaying="y",
                    side="right", range=[0,100]),
        template=plotly_template(), height=380,
        margin=dict(l=20, r=60, t=55, b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.28),
    )
    return fig


def _fig_seasonal_risk_distribution() -> go.Figure:
    """
    Monthly risk distribution for Northern England based on
    historical climatology + UK Met Office seasonal risk profiles.
    """
    months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]
    # Mean risk by month (calibrated to UK DNO historical incident data)
    mean_risk  = [45.2,42.1,36.8,28.4,22.1,18.6,22.8,24.3,30.5,38.7,46.2,48.1]
    p90_risk   = [72.1,68.4,58.2,48.1,38.4,32.1,40.2,42.8,52.4,65.3,74.8,76.4]
    p10_risk   = [22.4,20.1,18.2,12.4, 8.6, 7.2,10.4,11.2,14.8,20.1,22.8,24.2]
    # Primary hazard by month
    primary_haz= ["WIND","WIND","WIND","FLOOD","FLOOD","HEAT","HEAT","HEAT",
                  "FLOOD","FLOOD","WIND","WIND"]
    haz_cols   = {"WIND":"#38bdf8","FLOOD":"#3b82f6","HEAT":"#f97316"}

    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=months+months[::-1], y=p90_risk+p10_risk[::-1],
        fill="toself", fillcolor="rgba(56,189,248,0.10)",
        line=dict(color="rgba(0,0,0,0)"), name="P10–P90 range",
    ))
    fig.add_trace(go.Scatter(
        x=months, y=mean_risk, mode="lines+markers",
        name="Mean risk score",
        line=dict(color="#38bdf8", width=2.5),
        marker=dict(size=10, color=[haz_cols.get(h,"#94a3b8") for h in primary_haz],
                    line=dict(color="white", width=1.5)),
        hovertemplate="<b>%{x}</b><br>Mean risk: %{y:.1f}<extra></extra>",
    ))
    for lbl,th,col in [("AMBER",55,"#f97316"),("RED",72,"#ef4444")]:
        fig.add_hline(y=th, line_dash="dash", line_color=col, line_width=1.2,
                      annotation_text=lbl, annotation_font_size=9)

    fig.update_layout(
        title="Monthly risk distribution — Northern England (marker colour = primary hazard)",
        xaxis_title="Month",
        yaxis=dict(title="Risk score (0–100)", range=[0,100]),
        template=plotly_template(), height=360,
        margin=dict(l=20, r=20, t=55, b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.22),
    )
    return fig


def _fig_compound_event_network() -> go.Figure:
    """
    Bubble chart showing hazard co-occurrence frequency.
    Node size = frequency; edge weight = co-occurrence count.
    Simulated from historical event catalogue + UK Met Office records.
    """
    hazards    = ["WIND","FLOOD","HEAT","GRID_FAIL","AQI","RENEW_GAP","DROUGHT"]
    # Co-occurrence matrix (upper triangle)
    cooccur    = {
        ("WIND","FLOOD"):     8,   # Very common — Atlantic fronts bring both
        ("WIND","GRID_FAIL"): 12,  # Wind → OHL damage → failure
        ("FLOOD","GRID_FAIL"):6,
        ("HEAT","GRID_FAIL"): 5,   # Demand surge + transformer stress
        ("HEAT","AQI"):       7,   # Hot still days concentrate pollution
        ("HEAT","DROUGHT"):   4,
        ("RENEW_GAP","DROUGHT"):3, # Low wind + dry = low hydro + low wind
        ("WIND","AQI"):       2,   # High wind disperses pollution (anti-correlated)
    }
    freq = {"WIND":22,"FLOOD":15,"HEAT":8,"GRID_FAIL":18,"AQI":6,"RENEW_GAP":9,"DROUGHT":4}

    # Node positions (arranged in a circle)
    n = len(hazards)
    pos = {h: (math.cos(2*math.pi*i/n), math.sin(2*math.pi*i/n))
           for i,h in enumerate(hazards)}
    haz_col = {
        "WIND":"#38bdf8","FLOOD":"#3b82f6","HEAT":"#f97316",
        "GRID_FAIL":"#ef4444","AQI":"#a855f7","RENEW_GAP":"#22c55e","DROUGHT":"#eab308",
    }

    fig = go.Figure()
    # Edges
    for (h1,h2), cnt in cooccur.items():
        x1,y1 = pos[h1]; x2,y2 = pos[h2]
        fig.add_trace(go.Scatter(
            x=[x1,x2,None], y=[y1,y2,None],
            mode="lines",
            line=dict(width=max(1, cnt//2), color="rgba(148,163,184,0.4)"),
            showlegend=False,
            hoverinfo="none",
        ))
    # Nodes
    for h in hazards:
        x,y = pos[h]
        fig.add_trace(go.Scatter(
            x=[x], y=[y], mode="markers+text",
            text=[h], textposition="top center", textfont=dict(size=10),
            marker=dict(size=max(20, min(50, freq[h]*1.8)),
                        color=haz_col.get(h,"#94a3b8"), opacity=0.88,
                        line=dict(color="white", width=2)),
            name=h, showlegend=False,
            hovertemplate=f"<b>{h}</b><br>Frequency: {freq[h]} events/5yr<extra></extra>",
        ))

    fig.update_layout(
        title="Hazard co-occurrence network (node size = frequency, edge = co-occurrence count)",
        xaxis=dict(visible=False, range=[-1.5,1.5]),
        yaxis=dict(visible=False, range=[-1.5,1.5]),
        template=plotly_template(), height=420,
        margin=dict(l=10,r=10,t=55,b=10),
    )
    return fig


def _fig_financial_loss_waterfall() -> go.Figure:
    """Waterfall chart of cumulative loss from historical events."""
    events = sorted(EWS_HISTORICAL_EVENTS, key=lambda e: e.date)
    names  = [e.name[:18] for e in events]
    losses = [e.total_loss_gbp_m for e in events]
    cumulative = [sum(losses[:i+1]) for i in range(len(losses))]

    fig = go.Figure(go.Waterfall(
        name="Loss (£M)",
        orientation="v",
        measure=["relative"] * len(losses) + ["total"],
        x=names + ["Total"],
        y=losses + [sum(losses)],
        text=[f"£{l:.1f}M" for l in losses] + [f"£{sum(losses):.1f}M"],
        textposition="outside",
        connector=dict(line=dict(color="#64748b")),
        increasing=dict(marker_color="#ef4444"),
        decreasing=dict(marker_color="#22c55e"),
        totals=dict(marker_color="#38bdf8"),
    ))
    fig.update_layout(
        title="Cumulative financial loss — historical events portfolio",
        yaxis_title="Loss (£M)",
        template=plotly_template(), height=380,
        margin=dict(l=20,r=20,t=55,b=20),
    )
    return fig


