def render_ews_historical_section() -> None:
    """
    Render the Historical Events sub-tab.
    Sections: event overview, alert escalation, case study cards,
    lead-time value, seasonal distribution, co-occurrence network,
    financial waterfall, retrospective table.
    """
    st.markdown("#### 🗂 Historical Event Database & Retrospective Analysis")
    st.caption(
        "8 major UK power-grid hazard events (2021–2023). "
        "EWS alert levels are computed retrospectively from the feature vectors "
        "that would have been available at each forecast horizon."
    )

    # ── Overview charts ───────────────────────────────────────────────
    ov1, ov2 = st.columns(2)
    with ov1: st.plotly_chart(_fig_event_timeline_scatter(),   use_container_width=True, key="hist_tl")
    with ov2: st.plotly_chart(_fig_event_alert_escalation(),   use_container_width=True, key="hist_esc")

    # ── Lead-time + seasonal ──────────────────────────────────────────
    lt1, lt2 = st.columns(2)
    with lt1: st.plotly_chart(_fig_lead_time_value(),          use_container_width=True, key="hist_ltv")
    with lt2: st.plotly_chart(_fig_seasonal_risk_distribution(),use_container_width=True,key="hist_seas")

    # ── Co-occurrence + financial ─────────────────────────────────────
    co1, co2 = st.columns(2)
    with co1: st.plotly_chart(_fig_compound_event_network(),   use_container_width=True, key="hist_conet")
    with co2: st.plotly_chart(_fig_financial_loss_waterfall(), use_container_width=True, key="hist_wfall")

    st.markdown("---")

    # ── Case study cards ──────────────────────────────────────────────
    st.markdown("##### Event Case Studies")
    sel_event = st.selectbox(
        "Select event for detailed analysis",
        [f"{ev.name} ({ev.date})" for ev in EWS_HISTORICAL_EVENTS],
        key="hist_event_sel",
    )
    ev_idx = next(i for i, ev in enumerate(EWS_HISTORICAL_EVENTS)
                  if f"{ev.name} ({ev.date})" == sel_event)
    ev = EWS_HISTORICAL_EVENTS[ev_idx]

    ev_col = {
        HazardType.WIND:"#38bdf8", HazardType.FLOOD:"#3b82f6",
        HazardType.HEATWAVE:"#f97316", HazardType.RENEWABLE_GAP:"#22c55e",
        HazardType.AQI_SPIKE:"#a855f7", HazardType.GRID_FAILURE:"#ef4444",
    }.get(ev.hazard_type, "#94a3b8")

    c1, c2 = st.columns([3, 2])
    with c1:
        st.markdown(
            f'<div class="card" style="border-left:5px solid {ev_col};">'
            f'<b style="color:{ev_col};font-size:16px;">{ev.name}</b>'
            f'  <span style="color:#64748b;font-size:12px;">{ev.date} · {ev.region}</span><br>'
            f'<div style="margin:8px 0;display:flex;gap:8px;flex-wrap:wrap;">'
            f'<span class="chip">Peak risk: {ev.peak_risk_score:.0f}/100</span>'
            f'<span class="chip">Customers: {ev.customers_off:,}</span>'
            f'<span class="chip">ENS: {ev.peak_ens_mw:.0f} MW</span>'
            f'<span class="chip">Loss: £{ev.total_loss_gbp_m:.1f}M</span>'
            f'<span class="chip">Restoration: {ev.restoration_hours:.1f}h</span>'
            f'<span class="chip">Substations: {ev.substations_affected}</span>'
            f'</div>'
            f'<p style="color:#cbd5e1;font-size:12.5px;line-height:1.6;">{ev.description}</p>'
            f'<hr style="border-color:#334155;margin:8px 0;">'
            f'<p style="color:#94a3b8;font-size:12px;"><b>Lessons learned:</b> {ev.lessons_learned}</p>'
            f'</div>',
            unsafe_allow_html=True,
        )
        if ev.ofgem_reference:
            st.caption(f"Source: {ev.ofgem_reference}")

    with c2:
        st.plotly_chart(_fig_event_comparison_radar(ev),
                        use_container_width=True, key="hist_radar")

        # EWS performance summary for this event
        alert_colours_str = {"GREEN":"#22c55e","YELLOW":"#eab308","AMBER":"#f97316","RED":"#ef4444","CRITICAL":"#a855f7"}
        def _ac(s): return alert_colours_str.get(s.upper(),"#94a3b8")
        st.markdown(
            f'<div class="note" style="font-size:12px;">'
            f'<b>EWS Retrospective Alert Levels</b><br>'
            f'T+24h: <b style="color:{_ac(ev.ews_t24h_level)};">{ev.ews_t24h_level}</b> &nbsp;'
            f'T+6h: <b style="color:{_ac(ev.ews_t6h_level)};">{ev.ews_t6h_level}</b> &nbsp;'
            f'T+1h: <b style="color:{_ac(ev.ews_t1h_level)};">{ev.ews_t1h_level}</b> &nbsp;'
            f'T+5min: <b style="color:{_ac(ev.ews_t5m_level)};">{ev.ews_t5m_level}</b><br>'
            f'Earliest warning: <b>{ev.earliest_warning_h:.0f} hours</b> before peak impact'
            f'</div>',
            unsafe_allow_html=True,
        )

    # ── Retrospective performance table ───────────────────────────────
    st.markdown("---")
    st.markdown("##### Retrospective Performance Summary (all events)")
    retro_df = build_retrospective_df()
    st.dataframe(retro_df, use_container_width=True, hide_index=True)

    # KPI summary
    adequate = sum(1 for _, row in retro_df.iterrows() if row["Adequate warn."] == "✅")
    st.caption(
        f"Adequate warning (≥6h AMBER+ before peak): "
        f"**{adequate}/{len(retro_df)}** events ({adequate/len(retro_df)*100:.0f}%). "
        f"Average earliest warning: "
        f"**{sum(ev.earliest_warning_h for ev in EWS_HISTORICAL_EVENTS)/len(EWS_HISTORICAL_EVENTS):.1f}h**."
    )

