@dataclass
class StressTestResult:
    scenario_key:      str
    label:             str
    base_risk:         float
    stressed_risk:     float
    delta_risk:        float
    stressed_gf_pct:   float
    stressed_ens_mw:   float
    stressed_alert:    AlertLevel
    stressed_hazard:   HazardType
    stressed_exceedance: float
    ci_q10:            float
    ci_q90:            float
    total_unc:         float
    ood_score:         float
    l1_points:         Dict[str, float]   # per-model point estimates
    description:       str
    colour:            str


def run_stress_tests(
    fvs: Dict[str, EWSFeatureVector],
    preds: Dict[str, Dict[int, Dict[str, Any]]],
) -> List[StressTestResult]:
    """Run all 8 stress scenarios for each monitored place."""
    import copy
    results: List[StressTestResult] = []
    ensemble = EWSEnsemble()

    for place, fv in fvs.items():
        base_risk = preds[place][5]["prediction"].predicted_risk if (
            place in preds and 5 in preds[place]) else fv.final_risk_score
        b_gf      = fv.grid_failure_probability * 100
        b_ens     = fv.energy_not_supplied_mw

        for sc_key, sc_cfg in STRESS_SCENARIOS.items():
            # Apply modifiers to a copy of the feature vector
            fv_s   = copy.copy(fv)
            fv_d   = fv_s.__dict__
            for k, v in sc_cfg["modifiers"].items():
                if k in fv_d:
                    fv_d[k] = float(v)

            ens    = ensemble.predict(fv_s, base_risk, 5)
            pt     = ens["point"]
            ratio  = pt / max(base_risk, 1)
            hazard = _classify_hazard(fv_s)
            level  = _classify_alert(ens["exceedance"], pt,
                                     clamp(b_gf*ratio,0,100),
                                     clamp(b_ens*ratio,0,5000),
                                     fv_s.compound_hazard_proxy, 5)

            # OOD score
            fv_n   = _normalise_fv(fv_s)
            iso_r  = np.random.default_rng(abs(int(float(np.sum(fv_n*777))))%(2**31))
            paths  = []
            for _ in range(10):
                xi=fv_n.copy(); p=0
                for _ in range(8):
                    if not len(xi): break
                    fi=int(iso_r.integers(0,len(xi)))
                    xi=xi[xi<0.5] if xi[fi]<float(iso_r.uniform(0,1)) else xi[xi>=0.5]; p+=1
                paths.append(p)
            c_n = 2*(math.log(255)+0.5772)-2*255/256
            ood  = clamp(float(2**(-float(np.mean(paths))/max(c_n,1e-9))),0,1)

            l1_points = {mp.arch.value.split("(")[0].strip()[:22]: mp.point
                         for mp in ens["l1_preds"]}

            results.append(StressTestResult(
                scenario_key=sc_key, label=sc_cfg["label"],
                base_risk=round(base_risk,2), stressed_risk=round(pt,2),
                delta_risk=round(pt-base_risk,2),
                stressed_gf_pct=round(clamp(b_gf*ratio,0,100),1),
                stressed_ens_mw=round(clamp(b_ens*ratio,0,5000),1),
                stressed_alert=level, stressed_hazard=hazard,
                stressed_exceedance=round(ens["exceedance"],4),
                ci_q10=round(ens["q10"],2), ci_q90=round(ens["q90"],2),
                total_unc=round(ens["total_unc"],4),
                ood_score=round(ood,4),
                l1_points=l1_points,
                description=sc_cfg["description"],
                colour=sc_cfg["colour"],
            ))
    return results


# ────────────────────────────────────────────────────────────────────────────
# 3.2  SENSITIVITY ANALYSIS
# ────────────────────────────────────────────────────────────────────────────

def run_oat_sensitivity(
    fv: EWSFeatureVector,
    base_risk: float,
    features: Optional[List[str]] = None,
    pct_range: Tuple[float,float] = (-0.80, 2.00),
    n_steps: int = 25,
) -> List[Dict[str, Any]]:
    """
    One-at-a-time (OAT) sensitivity analysis.
    Sweeps each feature from pct_range[0] to pct_range[1] relative to baseline.
    Returns sorted list of (feature, sensitivity_magnitude, sweep_data).
    """
    import copy
    if features is None:
        # Top features by domain knowledge
        features = [
            "wind_speed_ms", "precipitation_mmh", "grid_failure_probability",
            "compound_hazard_proxy", "energy_not_supplied_mw", "temperature_c",
            "pressure_tendency_hpa", "rate_of_change_risk", "flood_depth_proxy_m",
            "renewable_stress", "grid_stress_index", "social_vulnerability",
            "pressure_impulse", "nearby_outages_25km", "european_aqi",
        ]

    ensemble = EWSEnsemble()
    steps    = np.linspace(pct_range[0], pct_range[1], n_steps)
    results  = []

    for fname in features:
        baseline_val = float(getattr(fv, fname, 0))
        sweep_vals   = []
        pred_risks   = []

        for pct in steps:
            fv_s = copy.copy(fv)
            new_val = baseline_val * (1 + pct) if abs(baseline_val) > 1e-6 else float(pct)
            if hasattr(fv_s, fname):
                setattr(fv_s, fname, float(new_val))
            ens_r = ensemble.predict(fv_s, base_risk, 5)
            sweep_vals.append(round(float(new_val), 4))
            pred_risks.append(round(ens_r["point"], 2))

        sensitivity = max(pred_risks) - min(pred_risks)
        results.append({
            "feature":       fname,
            "baseline":      round(baseline_val, 4),
            "sweep_values":  sweep_vals,
            "pred_risks":    pred_risks,
            "sensitivity":   round(sensitivity, 2),
            "max_risk":      round(max(pred_risks), 2),
            "min_risk":      round(min(pred_risks), 2),
        })

    results.sort(key=lambda x: -x["sensitivity"])
    return results


def run_mc_global_sensitivity(
    fv: EWSFeatureVector,
    base_risk: float,
    n_samples: int = 200,
) -> Dict[str, float]:
    """
    Monte Carlo global sensitivity (Sobol first-order proxy).
    Randomly perturbs each feature and measures output variance contribution.
    Returns dict of feature → first-order sensitivity index proxy.
    """
    import copy
    ensemble = EWSEnsemble()
    rng_g    = np.random.default_rng(2024)
    features = [
        "wind_speed_ms","precipitation_mmh","grid_failure_probability",
        "compound_hazard_proxy","energy_not_supplied_mw","temperature_c",
        "pressure_tendency_hpa","rate_of_change_risk","flood_depth_proxy_m",
        "renewable_stress","grid_stress_index","social_vulnerability",
        "pressure_impulse","nearby_outages_25km","risk_acceleration",
    ]

    # Baseline output
    base_out = ensemble.predict(fv, base_risk, 5)["point"]

    # Generate n_samples random perturbations
    var_contributions: Dict[str, List[float]] = {f: [] for f in features}

    for _ in range(n_samples):
        # Full random sample (all features perturbed)
        fv_A = copy.copy(fv)
        for fname in features:
            v = float(getattr(fv_A, fname, 0))
            setattr(fv_A, fname, float(v * float(rng_g.uniform(0.5, 1.8))))
        y_A = ensemble.predict(fv_A, base_risk, 5)["point"]

        # Fix-one: perturb all EXCEPT one feature, measure variance reduction
        for fname in features:
            fv_B = copy.copy(fv_A)
            # Reset this feature to baseline
            setattr(fv_B, fname, float(getattr(fv, fname, 0)))
            y_B = ensemble.predict(fv_B, base_risk, 5)["point"]
            var_contributions[fname].append(abs(y_A - y_B))

    # First-order proxy: mean absolute difference when feature is fixed
    sobol_proxy = {}
    total = sum(np.mean(v) for v in var_contributions.values()) + 1e-9
    for fname, contribs in var_contributions.items():
        sobol_proxy[fname] = round(float(np.mean(contribs)) / total, 4)

    return dict(sorted(sobol_proxy.items(), key=lambda x: -x[1]))


