def _fig_tornado_diagram(oat_results: List[Dict[str, Any]], place: str) -> go.Figure:
    """Tornado diagram: ranked OAT sensitivity bars."""
    top = oat_results[:12]
    names     = [r["feature"].replace("_"," ") for r in top][::-1]
    sens      = [r["sensitivity"] for r in top][::-1]
    max_risks = [r["max_risk"]    for r in top][::-1]
    min_risks = [r["min_risk"]    for r in top][::-1]
    base      = top[0]["pred_risks"][len(top[0]["pred_risks"])//2] if top else 30.0

    fig = go.Figure()
    for i, (nm, mn, mx) in enumerate(zip(names, min_risks, max_risks)):
        fig.add_trace(go.Bar(
            y=[nm], x=[mx - base], base=base,
            orientation="h", marker_color="#ef4444", opacity=0.75,
            name="Increase" if i == 0 else None,
            showlegend=(i == 0),
        ))
        fig.add_trace(go.Bar(
            y=[nm], x=[mn - base], base=base,
            orientation="h", marker_color="#38bdf8", opacity=0.75,
            name="Decrease" if i == 0 else None,
            showlegend=(i == 0),
        ))

    fig.add_vline(x=base, line_color="#22c55e", line_width=2,
                  annotation_text=f"Baseline {base:.1f}", annotation_font_size=9)
    fig.update_layout(
        barmode="overlay",
        title=f"Tornado diagram (OAT sensitivity) — {place}",
        xaxis_title="Predicted risk (0–100)",
        template=plotly_template(), height=420,
        margin=dict(l=20,r=20,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.22),
    )
    return fig


def _fig_sobol_bar(sobol: Dict[str, float], place: str) -> go.Figure:
    """Bar: Sobol first-order sensitivity proxy."""
    items = list(sobol.items())[:12]
    names = [k.replace("_"," ") for k,_ in items][::-1]
    vals  = [v for _,v in items][::-1]
    cols  = [f"rgba(56,189,248,{max(0.3, v/max(vals+[0.01]))})" for v in vals]

    fig = go.Figure(go.Bar(
        y=names, x=vals, orientation="h",
        marker_color=cols, opacity=0.88,
        text=[f"{v:.4f}" for v in vals], textposition="outside",
    ))
    fig.update_layout(
        title=f"Global sensitivity (Sobol proxy, MC) — {place}",
        xaxis_title="First-order sensitivity index",
        template=plotly_template(), height=400,
        margin=dict(l=20,r=20,t=55,b=20),
    )
    return fig


def _fig_stress_comparison(results: List[StressTestResult], place: str) -> go.Figure:
    """Grouped bar: base vs stressed risk per scenario, coloured by alert level."""
    place_res = [r for r in results if True]  # all for now; filter by place if needed
    # Deduplicate by scenario
    seen: set = set()
    uniq: List[StressTestResult] = []
    for r in place_res:
        if r.scenario_key not in seen:
            seen.add(r.scenario_key); uniq.append(r)

    labels   = [r.label[:28] for r in uniq]
    base_v   = [r.base_risk    for r in uniq]
    stress_v = [r.stressed_risk for r in uniq]
    al_cols  = [ALERT_COLOUR.get(r.stressed_alert, "#94a3b8") for r in uniq]

    fig = go.Figure()
    fig.add_trace(go.Bar(
        name="Base risk", x=labels, y=base_v,
        marker_color="#64748b", opacity=0.70,
    ))
    fig.add_trace(go.Bar(
        name="Stressed risk", x=labels, y=stress_v,
        marker_color=al_cols, opacity=0.88,
        text=[f"{v:.0f}" for v in stress_v], textposition="outside",
    ))
    for lbl,th,col in [("AMBER",55,"#f97316"),("RED",72,"#ef4444"),("CRITICAL",88,"#a855f7")]:
        fig.add_hline(y=th, line_dash="dash", line_color=col, line_width=1.2,
                      annotation_text=lbl, annotation_font_size=9)
    fig.update_layout(
        barmode="group",
        title=f"Scenario stress-test — base vs stressed risk ({place})",
        yaxis=dict(title="Predicted risk (0–100)", range=[0,110]),
        template=plotly_template(), height=400,
        margin=dict(l=20,r=20,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.26),
    )
    return fig


def _fig_oat_sweep(oat_result: Dict[str, Any], place: str) -> go.Figure:
    """Single-feature OAT sweep chart."""
    fname  = oat_result["feature"]
    x_vals = oat_result["sweep_values"]
    y_vals = oat_result["pred_risks"]
    base_v = oat_result["baseline"]

    fig = go.Figure(go.Scatter(
        x=x_vals, y=y_vals, mode="lines+markers",
        line=dict(color="#38bdf8", width=2.5),
        marker=dict(size=6, color="#38bdf8"),
        fill="tozeroy", fillcolor="rgba(56,189,248,0.08)",
    ))
    fig.add_vline(x=base_v, line_dash="dash", line_color="#22c55e", line_width=1.8,
                  annotation_text="Baseline", annotation_font_size=9)
    for lbl,th,col in [("AMBER",55,"#f97316"),("RED",72,"#ef4444")]:
        fig.add_hline(y=th, line_dash="dot", line_color=col, line_width=1)
    fig.update_layout(
        title=f"OAT sweep — {fname.replace('_',' ')} (Δ={oat_result['sensitivity']:.1f})",
        xaxis_title=fname.replace("_"," "),
        yaxis=dict(title="Predicted risk", range=[0,105]),
        template=plotly_template(), height=260,
        margin=dict(l=20,r=20,t=50,b=20),
    )
    return fig


