def compute_cost_of_inaction(
    predicted_loss_gbp_m: float,
    exceedance_prob:      float,
    horizon_minutes:      int,
    alert_level:          AlertLevel,
) -> Dict[str, float]:
    """
    Decision-theoretic analysis: expected value of acting vs not acting.

    E[value of warning] = P(event) × loss × preparedness_factor(horizon)
    E[cost of false alarm] = P(no event) × preparation_cost
    Net expected value = E[value] − E[cost]
    """
    pf    = PREP_FACTORS.get(horizon_minutes, 0.2)
    p_ev  = exceedance_prob
    p_no  = 1 - p_ev

    # Preparation cost ≈ 2% of at-risk loss (crew overtime, standby)
    prep_cost_m  = predicted_loss_gbp_m * 0.02

    ev_value     = p_ev * predicted_loss_gbp_m * pf
    ev_false_alm = p_no * prep_cost_m
    net_ev       = ev_value - ev_false_alm

    # Alert threshold at this horizon
    threshold_txt = f"AMBER ({EWS_THRESHOLDS['risk']['amber']:.0f}/100)"

    return {
        "expected_value_gbp_m":    round(ev_value,    3),
        "expected_false_alarm_cost":round(ev_false_alm,3),
        "net_expected_value_gbp_m": round(net_ev,      3),
        "preparedness_factor_pct":  round(pf * 100,    1),
        "action_recommended":       net_ev > 0,
        "horizon_label":            EWS_HORIZON_LABELS.get(horizon_minutes, f"T+{horizon_minutes}min"),
        "threshold":                threshold_txt,
        "crew_action":              CREW_MOBILISATION.get(horizon_minutes, "Review protocol."),
    }


# ────────────────────────────────────────────────────────────────────────────
# 3.7  SIMPLE RESOURCE ALLOCATION OPTIMISER
# ────────────────────────────────────────────────────────────────────────────

def optimise_crew_allocation(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    total_crews: int = 12,
) -> pd.DataFrame:
    """
    Simple greedy resource allocation: assign crews to locations
    proportional to expected financial loss × exceedance probability.

    In production: replaced by a proper MILP using pulp or scipy.optimize.
    """
    horizon = 5
    rows    = []

    for place, pv in preds.items():
        if horizon not in pv:
            continue
        po  = pv[horizon]["prediction"]
        ev  = po.exceedance_probability * po.predicted_loss_gbp_m
        rows.append({
            "place": place,
            "ev_loss": ev,
            "risk":   po.predicted_risk,
            "alert":  po.alert_level,
        })

    if not rows:
        return pd.DataFrame()

    rows.sort(key=lambda x: -x["ev_loss"])
    total_ev  = sum(r["ev_loss"] for r in rows) + 1e-9
    alloc_rows = []

    remaining = total_crews
    for r in rows:
        alloc = max(1, round(r["ev_loss"] / total_ev * total_crews))
        alloc = min(alloc, remaining)
        remaining -= alloc
        alloc_rows.append({
            "Location":       r["place"],
            "Alert level":    r["alert"].name,
            "Risk score":     f"{r['risk']:.1f}/100",
            "Expected loss":  f"£{r['ev_loss']:.2f}M",
            "Crews allocated":alloc,
            "Justification":  f"EV-weighted: {r['ev_loss']/total_ev*100:.0f}% of risk pool",
        })
        if remaining <= 0:
            break

    return pd.DataFrame(alloc_rows)


