def render_ews_stress_test_section(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    fvs: Dict[str, EWSFeatureVector],
) -> None:
    """Render Scenario Stress-Test sub-tab."""
    st.markdown("#### 🧪 Scenario Stress-Testing")
    st.caption(
        "8 extreme scenarios applied to the AI ensemble at T+5min. "
        "Base risk replaced by scenario-modified feature vector — "
        "tests alert classification robustness and identifies which "
        "scenarios push which locations into CRITICAL territory."
    )

    if not fvs:
        st.info("Run the main pipeline first.")
        return

    with st.spinner("Running stress tests across all 8 scenarios × all locations…"):
        st_results = run_stress_tests(fvs, preds)

    if not st_results:
        st.warning("No stress-test results.")
        return

    # ── Place selector ─────────────────────────────────────────────────
    sel_place = st.selectbox("Location for stress-test charts",
                              sorted(fvs.keys()), key="st_place_sel")
    place_res = [r for r in st_results]   # all for comparison chart

    sc1, sc2 = st.columns(2)
    with sc1:
        st.plotly_chart(_fig_stress_comparison(place_res, sel_place),
                        use_container_width=True, key="st_comp")

    with sc2:
        # Stress-test table
        tbl_rows = []
        seen_sc: set = set()
        for r in st_results:
            if r.scenario_key in seen_sc: continue
            seen_sc.add(r.scenario_key)
            tbl_rows.append({
                "Scenario":      r.label[:30],
                "Base risk":     f"{r.base_risk:.1f}",
                "Stressed risk": f"{r.stressed_risk:.1f}",
                "Δ Risk":        f"{r.delta_risk:+.1f}",
                "Alert":         r.stressed_alert.name,
                "Hazard":        r.stressed_hazard.name,
                "Exceedance":    f"{r.stressed_exceedance*100:.1f}%",
                "OOD score":     f"{r.ood_score:.3f}",
                "Total UQ":      f"{r.total_unc*100:.1f}%",
            })
        st.dataframe(pd.DataFrame(tbl_rows), use_container_width=True, hide_index=True)

    # Scenario detail cards
    st.markdown("##### Scenario Descriptions")
    card_cols = st.columns(2)
    for i, (sc_key, sc_cfg) in enumerate(STRESS_SCENARIOS.items()):
        col = sc_cfg["colour"]
        with card_cols[i % 2]:
            match = next((r for r in st_results if r.scenario_key==sc_key), None)
            al_name = match.stressed_alert.name if match else "N/A"
            al_c    = ALERT_COLOUR.get(match.stressed_alert, "#94a3b8") if match else "#94a3b8"
            st.markdown(
                f'<div class="card" style="border-left:4px solid {col};margin-bottom:8px;">'
                f'<b style="color:{col};">{sc_cfg["label"]}</b>'
                f'  <span style="color:{al_c};font-size:11px;float:right;">{al_name}</span><br>'
                f'<span style="color:#94a3b8;font-size:11.5px;">{sc_cfg["description"]}</span>'
                f'</div>',
                unsafe_allow_html=True,
            )


def render_ews_sensitivity_section(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    fvs: Dict[str, EWSFeatureVector],
) -> None:
    """Render Sensitivity Analysis sub-tab."""
    st.markdown("#### 🔁 Sensitivity Analysis")
    st.caption(
        "One-at-a-time (OAT) and global Monte Carlo (Sobol proxy) sensitivity "
        "analysis. Shows which features most drive predicted risk for the "
        "current live conditions."
    )

    if not fvs:
        st.info("Run the main pipeline first.")
        return

    sel_place = st.selectbox("Location", sorted(fvs.keys()), key="sens_place_sel")
    fv = fvs[sel_place]
    base_risk = preds[sel_place][5]["prediction"].predicted_risk if (
        sel_place in preds and 5 in preds[sel_place]) else fv.final_risk_score

    with st.spinner("Computing OAT sensitivity (15 features × 25 sweep points)…"):
        oat_res = run_oat_sensitivity(fv, base_risk)

    s1, s2 = st.columns(2)
    with s1:
        st.plotly_chart(_fig_tornado_diagram(oat_res, sel_place),
                        use_container_width=True, key="sens_tornado")
    with s2:
        with st.spinner("Computing global sensitivity (Sobol proxy, 200 MC samples)…"):
            sobol = run_mc_global_sensitivity(fv, base_risk, n_samples=200)
        st.plotly_chart(_fig_sobol_bar(sobol, sel_place),
                        use_container_width=True, key="sens_sobol")

    # Individual OAT sweeps for top 4
    st.markdown("##### Individual feature sweep charts (top 4 most sensitive)")
    sw_cols = st.columns(2)
    for i, r in enumerate(oat_res[:4]):
        with sw_cols[i % 2]:
            st.plotly_chart(_fig_oat_sweep(r, sel_place),
                            use_container_width=True, key=f"sens_sw_{i}")


def render_ews_decision_support_section(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    region: str,
) -> None:
    """Render Decision Support sub-tab."""
    st.markdown("#### 💡 Decision Support & Resource Allocation")
    st.caption(
        "Operational recommendations, cost-of-inaction analysis, "
        "and crew allocation optimisation for each monitored location."
    )

    horizon_opts = sorted({h for pv in preds.values() for h in pv})
    sel_hor = st.selectbox(
        "Horizon for decision analysis",
        horizon_opts,
        format_func=lambda h: EWS_HORIZON_LABELS.get(h, f"T+{h}min"),
        key="ds_hor_sel",
    )

    # Decision support cards (non-GREEN locations only)
    st.markdown(f"##### Actionable guidance — {EWS_HORIZON_LABELS.get(sel_hor,'')}")
    shown = 0
    for place in sorted(preds.keys()):
        if sel_hor not in preds[place]: continue
        po    = preds[place][sel_hor]["prediction"]
        level = po.alert_level
        if level == AlertLevel.GREEN: continue

        c   = ALERT_COLOUR[level]; bg = ALERT_BG[level]
        coi = compute_cost_of_inaction(
            po.predicted_loss_gbp_m, po.exceedance_probability,
            sel_hor, level,
        )

        net_ev_col = "#22c55e" if coi["net_expected_value_gbp_m"] > 0 else "#ef4444"
        st.markdown(
            f'<div class="card" style="border-left:5px solid {c};background:{bg};">'
            f'<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;">'
            f'<div><b style="color:{c};font-size:15px;">{place}</b> '
            f'<span style="background:{c}22;color:{c};border-radius:999px;'
            f'padding:2px 10px;font-size:11px;font-weight:900;">{level.name}</span></div>'
            f'<div style="font-size:12px;color:#94a3b8;">'
            f'Risk: {po.predicted_risk:.1f}/100 · '
            f'GF: {po.predicted_gf_pct:.1f}% · '
            f'ENS: {po.predicted_ens_mw:.0f} MW · '
            f'Exceedance: {po.exceedance_probability*100:.1f}%</div></div>'
            f'<div style="margin-top:8px;font-size:12.5px;color:#e0f2fe;">'
            f'<b>Crew action:</b> {coi["crew_action"]}</div>'
            f'<div style="margin-top:6px;font-size:12px;color:#94a3b8;">'
            f'Expected value of acting: <b style="color:#22c55e;">£{coi["expected_value_gbp_m"]:.2f}M</b> · '
            f'False alarm cost: £{coi["expected_false_alarm_cost"]:.2f}M · '
            f'Net EV: <b style="color:{net_ev_col};">£{coi["net_expected_value_gbp_m"]:.2f}M</b>'
            f'</div></div>',
            unsafe_allow_html=True,
        )
        shown += 1

    if shown == 0:
        st.success("✅ All locations within GREEN envelope — no action required.")

    # Action matrix reference
    st.markdown("---")
    st.markdown("##### Action Matrix by Alert Level")
    for level, actions in ACTION_MATRIX.items():
        if not actions: continue
        c  = ALERT_COLOUR[level]; bg = ALERT_BG[level]
        with st.expander(f"{level.name} — Recipient actions", expanded=False):
            for recipient, action in actions.items():
                st.markdown(f"**{recipient}:** {action}")

    # Resource allocation
    st.markdown("---")
    st.markdown("##### Crew Allocation Optimisation")
    total_crews = st.slider("Total available crews", 4, 24, 12, 2, key="ds_crews")
    alloc_df    = optimise_crew_allocation(preds, total_crews=total_crews)
    if not alloc_df.empty:
        st.dataframe(alloc_df, use_container_width=True, hide_index=True)
        st.caption(
            "Greedy allocation proportional to P(event) × expected loss. "
            "Production: replace with MILP (pulp / scipy.optimize.linprog)."
        )
    else:
        st.info("No allocation data available.")

