# ────────────────────────────────────────────────────────────────────────────
# 4.1  LIVE RISK GAUGE GRID
# ────────────────────────────────────────────────────────────────────────────

def _fig_gauge_grid(preds: Dict, horizon: int = 5) -> go.Figure:
    """Grid of Indicator gauges — one per monitored location."""
    from plotly.subplots import make_subplots
    places = sorted(preds.keys())
    n      = len(places)
    if n == 0:
        return go.Figure()

    n_cols = min(4, n)
    n_rows = math.ceil(n / n_cols)
    specs  = [[{"type":"indicator"} for _ in range(n_cols)] for _ in range(n_rows)]
    fig    = make_subplots(
        rows=n_rows, cols=n_cols, specs=specs,
        subplot_titles=[p[:16] for p in places],
    )

    for i, place in enumerate(places):
        r = i // n_cols + 1
        c = i % n_cols + 1
        if horizon not in preds[place]:
            continue
        po    = preds[place][horizon]["prediction"]
        risk  = po.predicted_risk
        al    = po.alert_level
        col   = ALERT_COLOUR[al]
        gf    = po.predicted_gf_pct

        fig.add_trace(go.Indicator(
            mode="gauge+number+delta",
            value=round(risk, 1),
            number={"suffix":"/100", "font":{"size":14}},
            delta={"reference": 30, "relative": False,
                   "increasing":{"color":"#ef4444"},
                   "decreasing":{"color":"#22c55e"}},
            gauge={
                "axis":  {"range":[0,100], "tickfont":{"size":8}},
                "bar":   {"color": col},
                "steps": [
                    {"range":[0,  35], "color":"rgba(34,197,94,0.13)"},
                    {"range":[35, 55], "color":"rgba(234,179,8,0.13)"},
                    {"range":[55, 72], "color":"rgba(249,115,22,0.13)"},
                    {"range":[72, 88], "color":"rgba(239,68,68,0.16)"},
                    {"range":[88,100], "color":"rgba(168,85,247,0.18)"},
                ],
                "threshold": {
                    "line":  {"color":"white","width":2},
                    "value": risk,
                },
            },
            title={"text": f"GF {gf:.0f}%", "font":{"size":9}},
        ), row=r, col=c)

    fig.update_layout(
        title=f"Live risk gauges — {EWS_HORIZON_LABELS.get(horizon,'T+{horizon}min')}",
        template=plotly_template(),
        height=max(240, 180 * n_rows + 60),
        margin=dict(l=10,r=10,t=60,b=10),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 4.2  ROLLING 24-HOUR RISK TREND
# ────────────────────────────────────────────────────────────────────────────

def _fig_rolling_trend(preds: Dict) -> go.Figure:
    """
    Simulated 24-hour rolling risk trend.
    In production: queried from time-series DB at 15-min resolution.
    """
    rng     = np.random.default_rng(2024)
    hours   = list(range(-23, 1))
    colours = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308",
               "#ef4444","#94a3b8","#0ea5e9","#84cc16","#f43f5e"]

    fig = go.Figure()
    for i, (place, pv) in enumerate(sorted(preds.items())):
        base = pv[5]["prediction"].predicted_risk if 5 in pv else 30.0
        # Simulate a realistic-looking 24h trajectory leading to current value
        noise  = float(rng.normal(0, 2.2, 24).mean())
        trend  = np.cumsum(rng.normal(0.2, 0.9, 24)) - 4
        series = [clamp(base - (trend[-1]-trend[j]) + float(rng.normal(0,1.8)), 0, 100)
                  for j in range(24)]

        fig.add_trace(go.Scatter(
            x=hours, y=series, mode="lines",
            name=place,
            line=dict(color=colours[i % len(colours)], width=2.2),
            hovertemplate=f"<b>{place}</b><br>T: %{{x}}h<br>Risk: %{{y:.1f}}<extra></extra>",
        ))

    for lbl,th,col in [("AMBER",55,"#f97316"),("RED",72,"#ef4444")]:
        fig.add_hline(y=th, line_dash="dash", line_color=col, line_width=1.2,
                      annotation_text=lbl, annotation_font_size=9)
    fig.add_vline(x=0, line_color="#22c55e", line_width=1.5,
                  annotation_text="Now", annotation_font_size=9)
    fig.update_layout(
        title="Simulated 24h rolling risk trend (production: from time-series DB)",
        xaxis_title="Hours before now",
        yaxis=dict(title="Risk score (0–100)", range=[0,105]),
        template=plotly_template(), height=340,
        margin=dict(l=20,r=20,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.28),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 4.3  MULTI-PLACE FAN CHART OVERLAY
# ────────────────────────────────────────────────────────────────────────────

def _fig_multiplace_fan(preds: Dict) -> go.Figure:
    """Overlay risk fan charts for all places on one axis."""
    colours = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308","#ef4444","#94a3b8"]
    horizons= sorted({h for pv in preds.values() for h in pv})
    h_labels= [EWS_HORIZON_LABELS.get(h,"").split("(")[0].strip() for h in horizons]

    fig = go.Figure()
    for i, (place, pv) in enumerate(sorted(preds.items())):
        col    = colours[i % len(colours)]
        rr,gg,bb = int(col[1:3],16), int(col[3:5],16), int(col[5:7],16)
        pts    = [pv[h]["prediction"].predicted_risk for h in horizons if h in pv]
        q10s   = [pv[h]["prediction"].q10            for h in horizons if h in pv]
        q90s   = [pv[h]["prediction"].q90            for h in horizons if h in pv]
        xl     = h_labels[:len(pts)]

        # CI band (transparent fill)
        fig.add_trace(go.Scatter(
            x=xl+xl[::-1], y=q90s+q10s[::-1],
            fill="toself", fillcolor=f"rgba({rr},{gg},{bb},0.07)",
            line=dict(color="rgba(0,0,0,0)"), showlegend=False,
        ))
        fig.add_trace(go.Scatter(
            x=xl, y=pts, mode="lines+markers",
            name=place, line=dict(color=col, width=2),
            marker=dict(size=8, line=dict(color="white",width=1)),
        ))

    for lbl,th,col_h in [("AMBER",55,"#f97316"),("RED",72,"#ef4444")]:
        fig.add_hline(y=th, line_dash="dash", line_color=col_h, line_width=1.2,
                      annotation_text=lbl, annotation_font_size=9)
    fig.update_layout(
        title="Multi-location risk fan chart overlay",
        xaxis_title="Horizon",
        yaxis=dict(title="Risk (0–100)", range=[0,108]),
        template=plotly_template(), height=360,
        margin=dict(l=20,r=20,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.28),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 4.4  ALERT RATE TRACKER
# ────────────────────────────────────────────────────────────────────────────

def _fig_alert_rate_tracker(alerts: List[EWSAlert]) -> go.Figure:
    """Bar chart: alerts dispatched per recipient type."""
    if not alerts:
        return go.Figure()

    from collections import Counter
    counts = Counter(a.recipient_type.value for a in alerts)
    items  = sorted(counts.items(), key=lambda x: -x[1])
    names  = [k[:30] for k,_ in items]
    vals   = [v for _,v in items]

    # Colour by max alert level for that recipient
    level_by_recv: Dict[str, AlertLevel] = {}
    for a in alerts:
        rv = a.recipient_type.value
        if rv not in level_by_recv or a.alert_level.value > level_by_recv[rv].value:
            level_by_recv[rv] = a.alert_level
    cols = [ALERT_COLOUR.get(level_by_recv.get(n, AlertLevel.GREEN), "#94a3b8") for n in names]

    fig = go.Figure(go.Bar(
        y=names[::-1], x=vals[::-1], orientation="h",
        marker_color=cols[::-1], opacity=0.88,
        text=[str(v) for v in vals[::-1]], textposition="outside",
    ))
    fig.update_layout(
        title="Alerts dispatched by recipient channel",
        xaxis_title="Alert count",
        template=plotly_template(), height=max(260, 40*len(names)+80),
        margin=dict(l=20,r=20,t=55,b=20),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 4.5  GRID OPERATIONAL DASHBOARD
# ────────────────────────────────────────────────────────────────────────────

def _fig_grid_ops_dashboard(preds: Dict) -> go.Figure:
    """Multi-metric bar: GF probability, ENS, outages per location at T+5min."""
    places = sorted(preds.keys())
    h = 5
    gf_vals  = [preds[p][h]["prediction"].predicted_gf_pct for p in places if h in preds[p]]
    ens_vals = [preds[p][h]["prediction"].predicted_ens_mw  for p in places if h in preds[p]]
    pl_filt  = [p for p in places if h in preds[p]]

    fig = go.Figure()
    fig.add_trace(go.Bar(
        name="Grid failure % (×5 for scale)",
        x=pl_filt, y=[v*5 for v in gf_vals],
        marker_color="#ef4444", opacity=0.80,
        yaxis="y",
    ))
    fig.add_trace(go.Bar(
        name="ENS (MW)",
        x=pl_filt, y=ens_vals,
        marker_color="#38bdf8", opacity=0.80,
        yaxis="y2",
    ))
    fig.update_layout(
        barmode="group",
        title="Grid operational KPIs — T+5min forecast",
        yaxis=dict(title="GF × 5 scale", range=[0,200]),
        yaxis2=dict(title="ENS (MW)", overlaying="y", side="right", range=[0,2000]),
        template=plotly_template(), height=320,
        margin=dict(l=20,r=60,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.26),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 4.6  RENEWABLE GENERATION DASHBOARD
# ────────────────────────────────────────────────────────────────────────────

def _fig_renewable_dashboard(fvs: Dict) -> go.Figure:
    """Bar chart: solar + wind generation vs net load stress per location."""
    places = sorted(fvs.keys())
    solar  = [fvs[p].solar_generation_mw  for p in places]
    wind_g = [fvs[p].wind_generation_mw   for p in places]
    load_s = [fvs[p].net_load_stress_mw   for p in places]
    r_strs = [fvs[p].renewable_stress      for p in places]

    fig = go.Figure()
    fig.add_trace(go.Bar(name="Solar (MW)", x=places, y=solar,
        marker_color="#eab308", opacity=0.85))
    fig.add_trace(go.Bar(name="Wind gen (MW)", x=places, y=wind_g,
        marker_color="#38bdf8", opacity=0.85))
    fig.add_trace(go.Bar(name="Net load stress (MW)", x=places, y=load_s,
        marker_color="#ef4444", opacity=0.75))
    fig.add_trace(go.Scatter(name="Renewable stress (×100)",
        x=places, y=[v*100 for v in r_strs],
        mode="markers", marker=dict(size=12, color="#a855f7",
        symbol="diamond", line=dict(color="white",width=1.5)),
        yaxis="y2"))
    fig.update_layout(
        barmode="group",
        title="Renewable generation vs load stress — current conditions",
        yaxis=dict(title="MW"),
        yaxis2=dict(title="Renewable stress (%, diamond)", overlaying="y",
                    side="right", range=[0,120]),
        template=plotly_template(), height=340,
        margin=dict(l=20,r=60,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.28),
    )
    return fig


