def render_ews_monitoring_section(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    alerts: List[EWSAlert],
    fvs: Dict[str, EWSFeatureVector],
) -> None:
    """Render Real-Time Monitoring sub-tab."""
    st.markdown("#### 🖥 Real-Time Monitoring Dashboard")

    # ── Horizon selector ──────────────────────────────────────────────
    h_opts = sorted({h for pv in preds.values() for h in pv})
    sel_h  = st.select_slider(
        "Gauge horizon",
        options=h_opts,
        format_func=lambda h: EWS_HORIZON_LABELS.get(h,f"T+{h}m").split("(")[0].strip(),
        key="mon_h_slider",
    )

    # ── Gauges + alert rate ────────────────────────────────────────────
    mg1, mg2 = st.columns([3,2])
    with mg1:
        st.plotly_chart(_fig_gauge_grid(preds, sel_h),
                        use_container_width=True, key="mon_gauges")
    with mg2:
        st.plotly_chart(_fig_alert_rate_tracker(alerts),
                        use_container_width=True, key="mon_alert_rate")

    # ── Rolling trend + fan overlay ───────────────────────────────────
    rt1, rt2 = st.columns(2)
    with rt1:
        st.plotly_chart(_fig_rolling_trend(preds),
                        use_container_width=True, key="mon_trend")
    with rt2:
        st.plotly_chart(_fig_multiplace_fan(preds),
                        use_container_width=True, key="mon_fan_over")

    # ── Grid ops + renewable ──────────────────────────────────────────
    go1, go2 = st.columns(2)
    with go1:
        st.plotly_chart(_fig_grid_ops_dashboard(preds),
                        use_container_width=True, key="mon_grid_ops")
    with go2:
        st.plotly_chart(_fig_renewable_dashboard(fvs),
                        use_container_width=True, key="mon_renew")

    # ── Drift monitor ─────────────────────────────────────────────────
    st.plotly_chart(_fig_drift_monitor_simulated(),
                    use_container_width=True, key="mon_drift")


