def render_ews_tab_v3(
    region:          str,
    active_scenario: str,
    places:          pd.DataFrame,
    outages:         pd.DataFrame,
) -> None:
    """
    SAT-Guard EWS v3.0 — Master Dashboard Tab.

    Sub-tabs:
      🎯 Overview        — Hero, KPIs, risk fan, heatmap, UQ, threat matrix
      🤖 AI Models       — 9-model radar, lollipop CI, SHAP, OOD, perf matrix
      🚨 Alerts          — Timeline, dispatch register, full CAP bodies
      ✅ Validation      — Hindcast CRPS, reliability, ROC, coverage, DM test
      🗂 History         — Event catalogue, escalation chart, case studies
      🧪 Stress Test     — 8 scenarios, tornado, Sobol sensitivity
      💡 Decisions       — Cost-of-inaction, crew allocation, action matrix
      🖥 Monitoring      — Live gauges, rolling trend, grid ops, renewables
      🚀 Deployment      — Training spec, serving arch, data pipeline, compliance
    """
    st.markdown(APP_CSS, unsafe_allow_html=True)

    # ── Header ────────────────────────────────────────────────────────
    st.markdown(
        '<div class="card"><span style="font-size:22px;font-weight:950;color:white;">'
        '🛰 SAT-Guard EWS v3.0 — Advanced AI/ML Early Warning System</span><br>'
        '<span style="color:#94a3b8;font-size:13px;">'
        '9-model deep-learning ensemble · Stacked generalisation · Conformal prediction · '
        'MC-Dropout UQ · T+5min to T+24h · 9 government dispatch channels · '
        'Full hindcast validation · Historical event database'
        '</span></div>', unsafe_allow_html=True)

    if places.empty:
        st.error("No place data — run the main pipeline first.")
        return

    # ── Run core EWS pipeline ─────────────────────────────────────────
    _cache_key = f"ews_pipeline_{region}_{active_scenario}_{len(places)}"
    if _cache_key not in st.session_state:
        with st.spinner(
            "🤖 Running 9-model ensemble: "
            "BiLSTM-Attn · TFT · WaveNet · CNN-BiLSTM · Neural ODE · "
            "Stacked GRU · N-BEATS · Kalman EKF · XGBoost…"
        ):
            st.session_state[_cache_key] = run_ews_pipeline(
                region, active_scenario, places.to_dict("records"))
    res = st.session_state[_cache_key]

    preds   = res["predictions"]
