def _fig_hist_peak_conditions_radar(event_name: str) -> go.Figure:
    """Full radar of peak meteorological and grid conditions for a named event."""
    ev = next((e for e in EWS_HISTORICAL_EVENTS if e.name == event_name), None)
    if not ev:
        return go.Figure()
    dims = {
        "Wind (norm)":    clamp(ev.peak_wind_ms / 45, 0, 1),
        "Gust (norm)":    clamp(ev.peak_gust_ms / 65, 0, 1),
        "Rain (norm)":    clamp(ev.peak_precip_mmh / 40, 0, 1),
        "Temp (norm)":    clamp((ev.peak_temp_c - (-15)) / 55, 0, 1),
        "P fall (norm)":  clamp(abs(ev.pressure_fall_3h) / 8, 0, 1),
        "Risk (norm)":    clamp(ev.peak_risk_score / 100, 0, 1),
        "ENS (norm)":     clamp(ev.peak_ens_mw / 1000, 0, 1),
        "Customers":      clamp(ev.customers_off / 200_000, 0, 1),
        "Loss (norm)":    clamp(ev.total_loss_gbp_m / 100, 0, 1),
        "Substations":    clamp(ev.substations_affected / 30, 0, 1),
    }
    cats = list(dims.keys()) + [list(dims.keys())[0]]
    vals = list(dims.values()) + [list(dims.values())[0]]
    haz_col = {
        HazardType.WIND: "#38bdf8", HazardType.FLOOD: "#3b82f6",
        HazardType.HEATWAVE: "#f97316", HazardType.RENEWABLE_GAP: "#22c55e",
        HazardType.AQI_SPIKE: "#a855f7", HazardType.GRID_FAILURE: "#ef4444",
    }.get(ev.hazard_type, "#94a3b8")
    rr, gg, bb = int(haz_col[1:3], 16), int(haz_col[3:5], 16), int(haz_col[5:7], 16)
    fig = go.Figure(go.Scatterpolar(
        r=vals, theta=cats, fill="toself",
        line=dict(color=haz_col, width=2.5),
        fillcolor=f"rgba({rr},{gg},{bb},0.15)",
        name=event_name,
    ))
    fig.update_layout(
        polar=dict(radialaxis=dict(visible=True, range=[0, 1])),
        title=f"{event_name} — peak conditions (normalised 0–1)",
        template=plotly_template(), height=380,
        margin=dict(l=22, r=22, t=55, b=22),
    )
    return fig


def _fig_hist_restoration_times() -> go.Figure:
    """Bar chart: restoration times across historical events."""
    events = EWS_HISTORICAL_EVENTS
    names  = [e.name[:20] for e in events]
    rt     = [e.restoration_hours for e in events]
    cust   = [e.customers_off / 1000 for e in events]
    cols   = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308","#ef4444","#94a3b8","#0ea5e9"]
    fig = go.Figure()
    fig.add_trace(go.Bar(
        name="Restoration time (h)", x=names, y=rt,
        marker_color=cols[:len(names)], opacity=0.85,
        text=[f"{v:.1f}h" for v in rt], textposition="outside",
    ))
    fig.add_trace(go.Scatter(
        name="Customers off (000s)", x=names, y=cust,
        mode="markers", yaxis="y2",
        marker=dict(size=12, color="#f97316", symbol="diamond",
                    line=dict(color="white", width=1.5)),
    ))
    fig.update_layout(
        title="Restoration time vs customers affected — historical events",
        yaxis=dict(title="Restoration time (hours)"),
        yaxis2=dict(title="Customers off (000s)", overlaying="y", side="right"),
        template=plotly_template(), height=340,
        margin=dict(l=20, r=60, t=55, b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.26),
    )
    return fig


def _fig_hist_monthly_frequency() -> go.Figure:
    """Bar: number of AMBER+ events per month across the historical database."""
    month_counts = [0] * 12
    month_risk   = [0.0] * 12
    for ev in EWS_HISTORICAL_EVENTS:
        m = int(ev.date[5:7]) - 1
        month_counts[m] += 1
        month_risk[m]   += ev.peak_risk_score
    months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]
    avg_risk = [month_risk[i] / max(month_counts[i], 1) for i in range(12)]
    colours  = ["#ef4444" if c > 0 else "#22c55e" for c in month_counts]
    fig = go.Figure()
    fig.add_trace(go.Bar(
        name="Event count", x=months, y=month_counts,
        marker_color=colours, opacity=0.85,
    ))
    fig.add_trace(go.Scatter(
        name="Avg peak risk", x=months, y=avg_risk,
        mode="lines+markers", yaxis="y2",
        line=dict(color="#38bdf8", width=2.5),
        marker=dict(size=8),
    ))
    fig.update_layout(
        title="Historical AMBER+ events by month",
        yaxis=dict(title="Event count"),
        yaxis2=dict(title="Avg peak risk", overlaying="y", side="right", range=[0, 110]),
        template=plotly_template(), height=320,
        margin=dict(l=20, r=60, t=55, b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.24),
    )
    return fig


def _fig_hist_warning_lead_time_scatter() -> go.Figure:
    """Scatter: peak risk vs earliest warning lead time — shows detectability."""
    fig = go.Figure()
    haz_col = {
        HazardType.WIND: "#38bdf8", HazardType.FLOOD: "#3b82f6",
        HazardType.HEATWAVE: "#f97316", HazardType.RENEWABLE_GAP: "#22c55e",
        HazardType.AQI_SPIKE: "#a855f7", HazardType.GRID_FAILURE: "#ef4444",
    }
    for ev in EWS_HISTORICAL_EVENTS:
        col = haz_col.get(ev.hazard_type, "#94a3b8")
        fig.add_trace(go.Scatter(
            x=[ev.earliest_warning_h], y=[ev.peak_risk_score],
            mode="markers+text",
            text=[ev.name[:14]], textposition="top center", textfont=dict(size=9),
            marker=dict(size=max(12, ev.total_loss_gbp_m * 0.4),
                        color=col, opacity=0.85,
                        line=dict(color="white", width=1.5)),
            name=ev.name, showlegend=False,
            hovertemplate=f"<b>{ev.name}</b><br>"
                          f"Lead: {ev.earliest_warning_h:.0f}h<br>"
                          f"Risk: {ev.peak_risk_score:.0f}<br>"
                          f"Loss: £{ev.total_loss_gbp_m:.0f}M<extra></extra>",
        ))
    fig.add_vline(x=6, line_dash="dash", line_color="#22c55e", line_width=1.5,
                  annotation_text="Min pre-position (6h)", annotation_font_size=9)
    fig.add_hline(y=72, line_dash="dash", line_color="#ef4444", line_width=1.2,
                  annotation_text="RED threshold", annotation_font_size=9)
    fig.update_layout(
        title="Peak risk vs warning lead time (size = financial loss)",
        xaxis_title="Earliest AMBER warning (hours before peak)",
        yaxis=dict(title="Peak risk score", range=[30, 100]),
        template=plotly_template(), height=380,
        margin=dict(l=20, r=20, t=55, b=20),
    )
    return fig


