def _fig_stress_delta_heatmap(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    fvs: Dict[str, EWSFeatureVector],
) -> go.Figure:
    """
    Heatmap: Δrisk (stressed − base) for all places × all 8 scenarios.
    Identifies which locations are most vulnerable to which hazard types.
    """
    import copy
    ens_obj  = EWSEnsemble()
    places   = sorted(preds.keys())
    scenarios= list(STRESS_SCENARIOS.keys())
    s_labels = [STRESS_SCENARIOS[s]["label"][:22] for s in scenarios]
    z_vals   = []
    for place in places:
        base = preds[place][5]["prediction"].predicted_risk if (
            place in preds and 5 in preds[place]) else 30.0
        row = []
        for sc_key in scenarios:
            if place not in fvs:
                row.append(0.0); continue
            fv_s = copy.copy(fvs[place])
            for k, v in STRESS_SCENARIOS[sc_key]["modifiers"].items():
                if hasattr(fv_s, k): setattr(fv_s, k, float(v))
            try:
                ens_r = ens_obj.predict(fv_s, base, 5)
                delta = ens_r["point"] - base
            except Exception:
                delta = 0.0
            row.append(round(delta, 1))
        z_vals.append(row)

    fig = go.Figure(go.Heatmap(
        z=z_vals, x=s_labels, y=places,
        colorscale="RdYlGn_r", zmid=0,
        text=[[f"{v:+.0f}" for v in row] for row in z_vals],
        texttemplate="%{text}", showscale=True,
        colorbar=dict(title="Δ Risk", thickness=12),
    ))
    fig.update_layout(
        title="Scenario stress Δrisk heatmap — places × scenarios",
        xaxis_tickangle=-35, xaxis_side="top",
        template=plotly_template(),
        height=max(200, 40 * len(places) + 120),
        margin=dict(l=20, r=20, t=80, b=20),
    )
    return fig


def _fig_stress_exceedance_shift(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    fvs: Dict[str, EWSFeatureVector],
) -> go.Figure:
    """
    Bar chart: how exceedance probability shifts from base to each scenario
    for the highest-risk location.
    """
    import copy
    if not preds or not fvs:
        return go.Figure()
    top_place = max(preds.keys(),
                    key=lambda p: preds[p][5]["prediction"].predicted_risk if 5 in preds[p] else 0)
    base_exc  = preds[top_place][5]["prediction"].exceedance_probability if (
        top_place in preds and 5 in preds[top_place]) else 0.3
    ens_obj   = EWSEnsemble()
    fv_base   = fvs.get(top_place)
    base_risk = preds[top_place][5]["prediction"].predicted_risk if (
        top_place in preds and 5 in preds[top_place]) else 30.0
    sc_labels, sc_excs, sc_cols = [], [], []
    for sc_key, sc_cfg in STRESS_SCENARIOS.items():
        if not fv_base: break
        fv_s = copy.copy(fv_base)
        for k, v in sc_cfg["modifiers"].items():
            if hasattr(fv_s, k): setattr(fv_s, k, float(v))
        try:
            ens_r = ens_obj.predict(fv_s, base_risk, 5)
            exc   = ens_r["exceedance"]
        except Exception:
            exc = base_exc
        sc_labels.append(sc_cfg["label"][:24])
        sc_excs.append(exc * 100)
        sc_cols.append(sc_cfg["colour"])
    if not sc_labels:
        return go.Figure()
    fig = go.Figure()
    fig.add_trace(go.Bar(
        x=sc_labels, y=sc_excs, marker_color=sc_cols, opacity=0.85,
        text=[f"{v:.1f}%" for v in sc_excs], textposition="outside",
    ))
    fig.add_hline(y=base_exc * 100, line_dash="dash", line_color="#22c55e",
                  line_width=2, annotation_text=f"Base {base_exc*100:.1f}%",
                  annotation_font_size=10)
    fig.add_hline(y=EWS_THRESHOLDS["exceedance"]["amber"] * 100,
                  line_dash="dot", line_color="#f97316", line_width=1.2,
                  annotation_text="AMBER trigger", annotation_font_size=9)
    fig.update_layout(
        title=f"Exceedance probability shift by scenario — {top_place}",
        xaxis_tickangle=-25,
        yaxis=dict(title="Exceedance P (%)", range=[0, 105]),
        template=plotly_template(), height=360,
        margin=dict(l=20, r=20, t=55, b=50),
    )
    return fig


