def _fig_monitor_risk_heatmap_time(preds: Dict) -> go.Figure:
    """
    Simulated: risk heatmap over 24h × locations.
    Rows = locations, columns = hours ago, value = risk.
    Shows how risk evolved to reach current state.
    """
    rng_t   = np.random.default_rng(42)
    places  = sorted(preds.keys())
    hours   = list(range(-23, 1))
    z_vals  = []
    for place in places:
        base = preds[place][5]["prediction"].predicted_risk if (
            place in preds and 5 in preds[place]) else 30.0
        drift   = float(rng_t.normal(0, 0.4, 24).cumsum()[-1])
        row_rev = []
        curr = base
        for i in range(24):
            curr = clamp(curr - float(rng_t.normal(0.2, 1.1)), 0, 100)
            row_rev.append(round(curr, 1))
        z_vals.append(row_rev[::-1])
    # Use numeric x axis so add_vline works (categorical strings crash plotly)
    fig = go.Figure(go.Heatmap(
        z=z_vals,
        x=hours,
        y=places,
        colorscale="RdYlGn_r", zmin=0, zmax=100,
        showscale=True,
        colorbar=dict(title="Risk", thickness=12),
    ))
    fig.add_vline(x=0, line_color="#22c55e", line_width=2,
                  annotation_text="Now", annotation_font_size=9)
    # Format x-axis ticks as "Nh"
    tick_vals = list(range(-23, 1, 4)) + [0]
    fig.update_layout(
        title="Rolling 24h risk heatmap — all locations",
        xaxis=dict(title="Hours from now",
                   tickvals=tick_vals,
                   ticktext=[f"{h}h" for h in tick_vals]),
        template=plotly_template(),
        height=max(200, 40 * len(places) + 100),
        margin=dict(l=20, r=20, t=55, b=20),
    )
    return fig


def _fig_monitor_model_health() -> go.Figure:
    """
    Model health dashboard: simulated uptime, error rate, latency percentiles
    for all 9 models over the last 24h.
    """
    rng_h = np.random.default_rng(2024)
    models = [meta["name"].split("(")[0].strip()[:22] for meta in MODEL_META.values()]
    uptimes  = [clamp(float(rng_h.uniform(98.2, 100.0)), 0, 100) for _ in models]
    err_rate = [clamp(float(rng_h.uniform(0.0, 0.4)), 0, 5)  for _ in models]
    lat_p99  = [meta["inference_ms"] * float(rng_h.uniform(1.8, 2.5))
                for meta in MODEL_META.values()]
