def _fig_decision_cost_benefit(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
) -> go.Figure:
    """
    Cost-benefit analysis: expected value of preparing vs not preparing
    at each horizon for each non-GREEN location.
    """
    results = []
    for place, pv in preds.items():
        for h in EWS_HORIZONS:
            if h not in pv: continue
            po  = pv[h]["prediction"]
            if po.alert_level == AlertLevel.GREEN: continue
            coi = compute_cost_of_inaction(
                po.predicted_loss_gbp_m, po.exceedance_probability, h, po.alert_level)
            results.append({
                "label":   f"{place[:12]}\n{EWS_HORIZON_LABELS.get(h,'').split('(')[0].strip()}",
                "ev_act":  coi["expected_value_gbp_m"],
                "ev_no":   coi["expected_false_alarm_cost"],
                "net":     coi["net_expected_value_gbp_m"],
                "rec":     coi["action_recommended"],
            })
    if not results:
        return go.Figure()
    labels  = [r["label"] for r in results]
    ev_act  = [r["ev_act"]  for r in results]
    ev_no   = [-r["ev_no"]  for r in results]
    net_ev  = [r["net"]     for r in results]
    net_cols= ["#22c55e" if v > 0 else "#ef4444" for v in net_ev]
    fig = go.Figure()
    fig.add_trace(go.Bar(name="Expected benefit (act)", x=labels, y=ev_act,
                         marker_color="#22c55e", opacity=0.80))
    fig.add_trace(go.Bar(name="False alarm cost (act)", x=labels, y=ev_no,
                         marker_color="#ef4444", opacity=0.80))
    fig.add_trace(go.Scatter(name="Net EV", x=labels, y=net_ev,
                             mode="markers", yaxis="y",
                             marker=dict(size=12, color=net_cols,
                                         symbol="diamond",
                                         line=dict(color="white", width=1.5))))
    fig.add_hline(y=0, line_color="#64748b", line_width=1.5)
    fig.update_layout(
        barmode="relative",
        title="Cost-benefit: expected value of acting vs false alarm cost (£M)",
        xaxis_tickangle=-25,
        yaxis_title="£M",
        template=plotly_template(), height=380,
        margin=dict(l=20, r=20, t=55, b=50),
        legend=dict(orientation="h", yanchor="bottom", y=-0.32),
    )
    return fig


def _fig_decision_time_pressure(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
) -> go.Figure:
    """
    Time-pressure matrix: alert level vs horizon remaining.
    Actionable cells highlighted — shows where decisions must be made NOW.
    """
    places   = sorted(preds.keys())
    horizons = EWS_HORIZONS
    h_labels = [EWS_HORIZON_LABELS.get(h,"").split("(")[0].strip() for h in horizons]

    # Compute "urgency score" = alert_level × (1/horizon_decay)
    z_vals = []
    for place in places:
        row = []
        for h in horizons:
            if h not in preds.get(place, {}):
                row.append(0)
                continue
            al_v  = preds[place][h]["prediction"].alert_level.value
            decay = EWS_HORIZON_DECAY.get(h, 0.7)
            urgency = al_v / max(decay, 0.3)
            row.append(round(urgency, 2))
        z_vals.append(row)

    fig = go.Figure(go.Heatmap(
        z=z_vals, x=h_labels, y=places,
        colorscale=[[0,"#22c55e"],[0.3,"#eab308"],[0.6,"#f97316"],
                    [0.8,"#ef4444"],[1.0,"#a855f7"]],
        showscale=True,
        colorbar=dict(title="Urgency", thickness=12),
        text=[[preds[p][h]["prediction"].alert_level.name[:2]
               if h in preds.get(p,{}) else "G"
               for h in horizons] for p in places],
        texttemplate="%{text}",
    ))
    fig.update_layout(
        title="Decision urgency matrix — alert level × horizon (darker = act now)",
        xaxis_side="top",
        template=plotly_template(),
        height=max(180, 40 * len(places) + 100),
        margin=dict(l=20, r=20, t=80, b=20),
    )
    return fig


def _fig_decision_psr_exposure(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    fvs: Dict[str, EWSFeatureVector],
) -> go.Figure:
    """
    PSR (Priority Services Register) exposure: estimated vulnerable customers
    at risk per location, scaled by social vulnerability score.
    """
    places    = sorted(preds.keys())
    vuln_cust = []
    alert_cols= []
    exceedance= []
    for place in places:
        fv  = fvs.get(place)
        cust = fv.affected_customers if fv else 0
        sv   = fv.social_vulnerability if fv else 50
        # ~8% of customers on PSR in high-deprivation areas
        psr_frac = 0.08 * (sv / 100)
        vuln_cust.append(round(cust * psr_frac))
        if place in preds and 5 in preds[place]:
            al = preds[place][5]["prediction"].alert_level
            alert_cols.append(ALERT_COLOUR[al])
            exceedance.append(preds[place][5]["prediction"].exceedance_probability * 100)
        else:
            alert_cols.append("#94a3b8")
            exceedance.append(0)
    fig = go.Figure()
    fig.add_trace(go.Bar(
        name="Est. PSR customers at risk",
        x=places, y=vuln_cust,
        marker_color=alert_cols, opacity=0.85,
        text=[f"{v:,}" for v in vuln_cust], textposition="outside",
    ))
    fig.add_trace(go.Scatter(
        name="Exceedance %", x=places, y=exceedance,
        mode="markers", yaxis="y2",
        marker=dict(size=10, color="#f97316", symbol="x",
                    line=dict(color="#f97316", width=2)),
    ))
    fig.update_layout(
        title="PSR vulnerable customer exposure vs exceedance probability",
        yaxis=dict(title="Est. PSR customers"),
        yaxis2=dict(title="Exceedance %", overlaying="y", side="right", range=[0, 110]),
        template=plotly_template(), height=340,
        margin=dict(l=20, r=60, t=55, b=20),
        legend=dict(orientation="h", yanchor="bottom", y=-0.24),
    )
    return fig


