def render_ews_validation_extended(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
) -> None:
    """Extended validation with additional charts from Supplement A."""
    render_ews_validation_section(preds)
    st.markdown("---")
    st.markdown("##### Extended Verification Charts")
    with st.spinner("Computing extended metrics…"):
        hc_records_ext = generate_hindcast_dataset(preds, n_days=30)
        vr_ext         = compute_verification_results(hc_records_ext)
    if not vr_ext:
        return
    ex1, ex2 = st.columns(2)
    with ex1: st.plotly_chart(_fig_val_bias_by_horizon(vr_ext),         use_container_width=True, key="vex_bias")
    with ex2: st.plotly_chart(_fig_val_mae_comparison(vr_ext),           use_container_width=True, key="vex_mae")
    ex3, ex4 = st.columns(2)
    with ex3: st.plotly_chart(_fig_val_coverage_vs_sharpness(vr_ext),    use_container_width=True, key="vex_covsharp")
    with ex4: st.plotly_chart(_fig_val_pod_far_tradeoff(vr_ext),         use_container_width=True, key="vex_podfar")
    ex5, ex6 = st.columns(2)
    with ex5: st.plotly_chart(_fig_val_crps_decomp(vr_ext),              use_container_width=True, key="vex_crpsdecomp")
    with ex6: st.plotly_chart(_fig_val_skill_waterfall(vr_ext),          use_container_width=True, key="vex_skillwf")


