def render_ews_model_cards_section() -> None:
    """Render full model card documentation for all 9 models."""
    st.markdown("#### 📋 Full Model Cards — All 9 Architectures")
    st.caption(
        "Complete technical specifications for each model: architecture, "
        "training configuration, validation metrics, failure modes, "
        "and production deployment details."
    )
    card_cols = st.columns(2)
    for i, (mk, mv) in enumerate(EWS_MODEL_CARDS.items()):
        val = mv.get("validation", {})
        col = list(MODEL_META.values())[i]["colour"] if i < len(MODEL_META) else "#94a3b8"
        with card_cols[i % 2]:
            with st.expander(f"{mv['full_name']} v{mv['version']}", expanded=False):
                st.markdown(
                    f'<div class="card" style="border-left:4px solid {col};">'
                    f'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px;">'
                    f'<span class="chip">RMSE {val.get("rmse","?")}</span>'
                    f'<span class="chip">CRPS {val.get("crps","?")}</span>'
                    f'<span class="chip">POD {val.get("pod","?")}</span>'
                    f'<span class="chip">FAR {val.get("far","?")}</span>'
                    f'<span class="chip">{mv["parameters"]} params</span>'
                    f'</div>'
                    f'<b style="color:#94a3b8;font-size:11px;">Best horizon:</b> '
                    f'<span style="color:#cbd5e1;font-size:11px;">{mv["horizon_best"]}</span><br>'
                    f'<b style="color:#94a3b8;font-size:11px;">Backend:</b> '
                    f'<span style="color:#cbd5e1;font-size:11px;">{mv["inference_backend"]}</span>'
                    f'</div>', unsafe_allow_html=True)
                st.markdown("**Architecture:**")
                st.code(mv["architecture_detail"], language="text")
                st.markdown("**Training configuration:**")
                for k, v in mv["training"].items():
                    st.markdown(f"- **{k}:** {v}")
                st.markdown(f"**⚠️ Failure modes:** {mv['failure_modes']}")
                st.markdown(f"**Production path:** `{mv['production_path']}`")

