# 7.2  FEATURE CORRELATION ANALYSIS
# ────────────────────────────────────────────────────────────────────────────

def compute_feature_correlation_matrix(
    fvs: Dict[str, EWSFeatureVector],
    top_n: int = 20,
) -> Tuple[pd.DataFrame, List[str]]:
    """
    Compute Pearson correlation matrix for top features across all locations.
    Returns (correlation DataFrame, feature names).
    """
    if not fvs:
        return pd.DataFrame(), []

    # Select top features by domain knowledge
    top_features = [
        "wind_speed_ms","precipitation_mmh","temperature_c","surface_pressure_hpa",
        "pressure_tendency_hpa","grid_failure_probability","energy_not_supplied_mw",
        "compound_hazard_proxy","social_vulnerability","resilience_index",
        "rate_of_change_risk","risk_acceleration","pressure_impulse",
        "renewable_stress","grid_coherence","grid_stress_index",
        "final_risk_score","flood_depth_proxy_m","nearby_outages_25km",
        "european_aqi",
    ][:top_n]

    # Build data matrix
    rows = []
    for place, fv in fvs.items():
        fv_d = fv.__dict__
        row = {f: float(fv_d.get(f, 0)) for f in top_features if f in fv_d}
        rows.append(row)

    if not rows:
        return pd.DataFrame(), top_features

    df   = pd.DataFrame(rows)
    corr = df.corr(method="pearson")
    return corr, top_features


def _fig_correlation_heatmap(
    fvs: Dict[str, EWSFeatureVector],
) -> go.Figure:
    """Correlation heatmap with diverging colourscale."""
    corr, features = compute_feature_correlation_matrix(fvs, top_n=16)
    if corr.empty:
        return go.Figure()

    short_names = [f.replace("_"," ")[:18] for f in features if f in corr.columns]
    z_vals      = [[corr.loc[r,c] if r in corr.index and c in corr.columns else 0
                    for c in features if c in corr.columns]
                   for r in features if r in corr.index]

    fig = go.Figure(go.Heatmap(
        z=z_vals, x=short_names, y=short_names,
        colorscale="RdBu", zmid=0, zmin=-1, zmax=1,
        text=[[f"{v:.2f}" for v in row] for row in z_vals],
        texttemplate="%{text}", textfont=dict(size=8),
        showscale=True,
        colorbar=dict(title="Pearson r", thickness=12),
    ))
    fig.update_layout(
        title="Feature correlation matrix (Pearson r)",
        template=plotly_template(),
        height=520, xaxis_side="top",
        margin=dict(l=20,r=20,t=70,b=20),
        xaxis_tickangle=-45,
    )
    return fig


def _fig_feature_importance_comparison(
    shap_r: Dict[str, List[Tuple[str,float]]],
    oat_results: Optional[List[Dict[str,Any]]] = None,
) -> go.Figure:
    """
    Compare feature importance from different methods:
    SHAP proxy, OAT sensitivity, Sobol proxy.
    Shows ranking consistency across methods.
    """
    # Aggregate SHAP across all locations
    shap_agg: Dict[str, float] = {}
    for place, vals in shap_r.items():
        for fname, sv in vals:
            shap_agg[fname] = shap_agg.get(fname, 0) + abs(sv)
    shap_total  = sum(shap_agg.values()) + 1e-9
    shap_norm   = {k: round(v/shap_total, 4) for k,v in shap_agg.items()}

    top_features = sorted(shap_norm.items(), key=lambda x: -x[1])[:12]
    names        = [k.replace("_"," ") for k,_ in top_features]
    shap_vals    = [v for _,v in top_features]

    # OAT-based importance (if available)
    oat_import: List[float] = [0.0]*len(names)
    if oat_results:
        oat_dict = {r["feature"]: r["sensitivity"] for r in oat_results}
        oat_total = max(sum(oat_dict.values()), 1e-9)
        oat_import = [oat_dict.get(k.replace(" ","_"), 0)/oat_total for k,_ in top_features]

    fig = go.Figure()
    fig.add_trace(go.Bar(
        name="SHAP (gradient-free proxy)", x=names, y=shap_vals,
        marker_color="#38bdf8", opacity=0.82,
    ))
    if any(v > 0 for v in oat_import):
        fig.add_trace(go.Bar(
            name="OAT sensitivity (normalised)", x=names, y=oat_import,
            marker_color="#f97316", opacity=0.78,
        ))

    fig.update_layout(
        barmode="group",
        title="Feature importance comparison — SHAP vs OAT sensitivity",
        yaxis_title="Normalised importance",
        xaxis_tickangle=-35,
        template=plotly_template(), height=380,
        margin=dict(l=20,r=20,t=55,b=50),
        legend=dict(orientation="h",yanchor="bottom",y=-0.30),
    )
    return fig


