def _fig_model_comparison_radar_full() -> go.Figure:
    """
    Comprehensive model comparison radar with 6 dimensions:
    RMSE, CRPS, Inference speed (inverted), Uncertainty qual.,
    Long-horizon skill, Short-horizon skill.
    """
    models_data = {
        "BiLSTM+Attn":  [3.8,  0.29, 6.2,  0.82, 0.75, 0.88],
        "TFT★":         [3.5,  0.26, 14.8, 0.85, 0.90, 0.80],
        "WaveNet":      [4.1,  0.31, 2.1,  0.79, 0.60, 0.92],
        "CNN-BiLSTM":   [4.3,  0.32, 5.8,  0.77, 0.65, 0.86],
        "Neural ODE":   [4.0,  0.30, 22.4, 0.83, 0.80, 0.72],
        "Stacked GRU":  [4.5,  0.34, 3.9,  0.75, 0.70, 0.84],
        "N-BEATS":      [4.6,  0.35, 3.2,  0.74, 0.72, 0.80],
        "Kalman EKF":   [3.2,  0.33, 0.1,  0.88, 0.78, 0.65],
        "XGBoost":      [5.8,  0.39, 0.4,  0.65, 0.55, 0.72],
        "Ensemble":     [2.9,  0.26, 45.0, 0.88, 0.92, 0.94],
    }
    dims_labels = ["Accuracy\n(inv RMSE)", "Calibration\n(inv CRPS)",
                   "Speed\n(inv lat)", "UQ Quality", "Long-horiz\nskill", "Short-horiz\nskill"]

    # Normalise to 0–1 (invert RMSE, CRPS, latency — lower=better)
    rmse_max = 6.0; crps_max = 0.45; lat_max = 50.0

    normalised = {}
    for name, vals in models_data.items():
        rmse, crps, lat, uq, lh, sh = vals
        normalised[name] = [
            1 - rmse/rmse_max,    # accuracy
            1 - crps/crps_max,    # calibration
            1 - lat/lat_max,      # speed
            uq,                    # UQ quality
            lh,                    # long-horizon
            sh,                    # short-horizon
        ]

    colours = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308",
               "#ef4444","#94a3b8","#0ea5e9","#64748b","#f43f5e"]
    cats    = dims_labels + [dims_labels[0]]

    fig = go.Figure()
    for i, (name, vals) in enumerate(normalised.items()):
        vs = vals + [vals[0]]
        c  = colours[i % len(colours)]
        rr,gg,bb = int(c[1:3],16), int(c[3:5],16), int(c[5:7],16)
        show = name in ["TFT★","Ensemble","WaveNet","BiLSTM+Attn","Kalman EKF"]
        fig.add_trace(go.Scatterpolar(
            r=vs, theta=cats, name=name, fill="toself",
            line=dict(color=c, width=2 if show else 1),
            fillcolor=f"rgba({rr},{gg},{bb},{0.12 if show else 0.04})",
            opacity=1.0 if show else 0.55,
        ))
    fig.update_layout(
        polar=dict(radialaxis=dict(visible=True, range=[0,1])),
        title="Comprehensive model comparison (6-dimensional)",
        template=plotly_template(), height=500,
        margin=dict(l=22,r=22,t=60,b=22),
        legend=dict(orientation="h", yanchor="bottom", y=-0.32, font=dict(size=9)),
    )
    return fig


