# ────────────────────────────────────────────────────────────────────────────
# 8.1  EXTENDED MONTE CARLO WITH CVaR
# ────────────────────────────────────────────────────────────────────────────

@dataclass
class ExtendedMCResult:
    """Results from extended Monte Carlo simulation with tail risk metrics."""
    place:              str
    horizon_min:        int
    n_sim:              int
    mean_risk:          float
    std_risk:           float
    var_95:             float    # 95th percentile (VaR)
    var_99:             float    # 99th percentile (VaR)
    cvar_95:            float    # Conditional VaR at 95% (Expected Shortfall)
    cvar_99:            float    # Conditional VaR at 99%
    max_risk:           float
    prob_critical:      float    # P(risk > 88)
    prob_red:           float    # P(risk > 72)
    prob_amber:         float    # P(risk > 55)
    expected_loss_gbp_m:float
    cvar_loss_95_gbp_m: float    # expected loss in worst 5% scenarios
    skewness:           float    # distribution skewness
    kurtosis:           float    # excess kurtosis (> 0 = heavy-tailed)
    samples:            List[float] = field(default_factory=list)


def run_extended_mc(
    fv: EWSFeatureVector,
    base_risk: float,
    horizon: int = 5,
    n_sim: int = 5000,
    place: str = "Unknown",
) -> ExtendedMCResult:
    """
    Extended Monte Carlo simulation with full tail risk metrics.

    Simulates n_sim scenarios by perturbing the feature vector with
    correlated noise (reflecting physical weather uncertainty).
    Computes VaR, CVaR, skewness, kurtosis from the resulting distribution.

    In production: uncertainty from ML model's learned distribution;
    correlated perturbations from weather ensemble (MOGREPS-UK, 18-member).
    """
    import copy
    rng_mc   = np.random.default_rng(abs(int(base_risk * 1000)) % (2**31))
    ensemble = EWSEnsemble()

    # Physical uncertainty parameters
    wind_sigma   = max(fv.wind_speed_ms * 0.15, 0.5)     # 15% of wind speed
    rain_sigma   = max(fv.precipitation_mmh * 0.20, 0.1) # 20% of rain rate
    pres_sigma   = 1.8                                     # hPa (NWP pressure uncertainty)
    temp_sigma   = 0.6                                     # °C

    simulated_risks: List[float] = []
    simulated_loss:  List[float] = []

    voll_per_mwh = 17_000  # £/MWh (UK VoLL)

    for _ in range(n_sim):
        fv_s = copy.copy(fv)

        # Perturb with correlated noise (simplified Cholesky decomposition)
        dw = float(rng_mc.normal(0, wind_sigma))
        dr = float(rng_mc.normal(0, rain_sigma))
        dp = float(rng_mc.normal(0, pres_sigma))
        dt = float(rng_mc.normal(0, temp_sigma))

        # Physical correlations: wind and rain are correlated (~0.6 in UK storms)
        dr_corr = dr + 0.6 * dw * rain_sigma / max(wind_sigma, 1)

        fv_s.wind_speed_ms      = clamp(fv.wind_speed_ms + dw, 0, 50)
        fv_s.wind_gust_ms       = clamp(fv.wind_gust_ms + dw*1.4, 0, 65)
        fv_s.precipitation_mmh  = clamp(fv.precipitation_mmh + dr_corr, 0, 80)
        fv_s.temperature_c      = fv.temperature_c + dt
        fv_s.surface_pressure_hpa = clamp(fv.surface_pressure_hpa + dp, 940, 1045)
        fv_s.wind_sq            = fv_s.wind_speed_ms ** 2
        fv_s.wind_x_rain        = fv_s.wind_speed_ms * fv_s.precipitation_mmh
        fv_s.pressure_impulse   = abs(fv_s.pressure_tendency_hpa + dp/3) * fv_s.wind_speed_ms

        # Grid failure propagation
        gf_perturb = clamp(fv.grid_failure_probability + float(rng_mc.normal(0, 0.02)), 0, 1)
        fv_s.grid_failure_probability = gf_perturb

        ens_r = ensemble.predict(fv_s, base_risk, horizon)
        risk  = ens_r["point"]
        simulated_risks.append(risk)

        # Financial loss (simplified VoLL model)
        ens_mw = fv.energy_not_supplied_mw * (risk / max(base_risk, 1))
        loss_m = ens_mw * voll_per_mwh * (horizon / 60) / 1e6
        simulated_loss.append(loss_m)

    # Compute statistics
    risks_arr = sorted(simulated_risks)
    loss_arr  = sorted(simulated_loss)
    n = len(risks_arr)

    var_95  = float(np.percentile(risks_arr, 95))
    var_99  = float(np.percentile(risks_arr, 99))
    cvar_95 = float(np.mean([r for r in risks_arr if r >= var_95]))
    cvar_99 = float(np.mean([r for r in risks_arr if r >= var_99]))

    var_loss_95  = float(np.percentile(loss_arr, 95))
    cvar_loss_95 = float(np.mean([l for l in loss_arr if l >= var_loss_95]))

    # Higher moments
    mean_r = float(np.mean(simulated_risks))
    std_r  = float(np.std(simulated_risks))
    skew   = float(np.mean([(r-mean_r)**3 for r in simulated_risks])) / max(std_r**3, 1e-9)
    kurt   = float(np.mean([(r-mean_r)**4 for r in simulated_risks])) / max(std_r**4, 1e-9) - 3.0

    return ExtendedMCResult(
        place=place, horizon_min=horizon, n_sim=n_sim,
        mean_risk=round(mean_r, 2), std_risk=round(std_r, 2),
        var_95=round(var_95, 2), var_99=round(var_99, 2),
        cvar_95=round(cvar_95, 2), cvar_99=round(cvar_99, 2),
        max_risk=round(max(risks_arr), 2),
        prob_critical=round(sum(1 for r in simulated_risks if r>=88)/n, 4),
        prob_red=     round(sum(1 for r in simulated_risks if r>=72)/n, 4),
        prob_amber=   round(sum(1 for r in simulated_risks if r>=55)/n, 4),
        expected_loss_gbp_m=round(float(np.mean(simulated_loss)), 3),
        cvar_loss_95_gbp_m=round(cvar_loss_95, 3),
        skewness=round(skew, 3),
        kurtosis=round(kurt, 3),
        samples=simulated_risks[:500],  # store subset for histogram
    )


def _fig_mc_risk_distribution(mc_result: ExtendedMCResult) -> go.Figure:
    """Histogram of MC risk distribution with VaR/CVaR annotations."""
    samples = mc_result.samples
    if not samples:
        return go.Figure()

    fig = go.Figure()
    fig.add_trace(go.Histogram(
        x=samples, nbinsx=40, name="Risk distribution",
        marker_color="#38bdf8", opacity=0.75,
        histnorm="probability density",
    ))

    # KDE approximation (simple Gaussian smoothing for display)
    kde_x = np.linspace(0, 100, 200)
    mean_s, std_s = float(np.mean(samples)), float(np.std(samples))
    kde_y = [_gaussian_pdf((x - mean_s) / max(std_s, 1)) / max(std_s, 1) for x in kde_x]
    fig.add_trace(go.Scatter(
        x=list(kde_x), y=kde_y, mode="lines", name="KDE",
        line=dict(color="#a855f7", width=2.5),
    ))

    # VaR lines
    fig.add_vline(x=mc_result.var_95, line_color="#f97316", line_width=2,
                  line_dash="dash",
                  annotation_text=f"VaR 95% = {mc_result.var_95:.1f}",
                  annotation_font_size=9)
    fig.add_vline(x=mc_result.var_99, line_color="#ef4444", line_width=2,
                  line_dash="dash",
                  annotation_text=f"VaR 99% = {mc_result.var_99:.1f}",
                  annotation_font_size=9)
    fig.add_vline(x=mc_result.cvar_95, line_color="#a855f7", line_width=2,
                  line_dash="dot",
                  annotation_text=f"CVaR 95% = {mc_result.cvar_95:.1f}",
                  annotation_font_size=9)

    # Alert thresholds
    for lbl, th, col in [("AMBER",55,"#f97316"),("RED",72,"#ef4444"),("CRITICAL",88,"#a855f7")]:
        fig.add_vline(x=th, line_color=col, line_width=1, line_dash="dot")

    fig.update_layout(
        title=f"Monte Carlo risk distribution — {mc_result.place} T+{mc_result.horizon_min}min "
              f"(n={mc_result.n_sim:,})",
        xaxis=dict(title="Risk score", range=[0, 105]),
        yaxis_title="Density",
        template=plotly_template(), height=360,
        margin=dict(l=20,r=20,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.24),
    )
    return fig


def _fig_cvar_comparison(mc_results: List[ExtendedMCResult]) -> go.Figure:
    """Bar comparison: VaR 95%, CVaR 95%, mean for all places."""
    places = [r.place for r in mc_results]
    means  = [r.mean_risk  for r in mc_results]
    var95  = [r.var_95     for r in mc_results]
    cvar95 = [r.cvar_95    for r in mc_results]

    fig = go.Figure()
    fig.add_trace(go.Bar(name="Mean risk",    x=places, y=means,  marker_color="#38bdf8",opacity=0.85))
    fig.add_trace(go.Bar(name="VaR 95%",      x=places, y=var95,  marker_color="#f97316",opacity=0.82))
    fig.add_trace(go.Bar(name="CVaR 95%",     x=places, y=cvar95, marker_color="#ef4444",opacity=0.80))
    for lbl,th,col in [("AMBER",55,"#f97316"),("RED",72,"#ef4444"),("CRITICAL",88,"#a855f7")]:
        fig.add_hline(y=th,line_dash="dash",line_color=col,line_width=1.2,
                      annotation_text=lbl,annotation_font_size=9)
    fig.update_layout(
        barmode="group",
        title="VaR 95% vs CVaR 95% (Expected Shortfall) — tail risk comparison",
        yaxis=dict(title="Risk score",range=[0,110]),
        template=plotly_template(), height=350,
        margin=dict(l=20,r=20,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.24),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 8.2  COPULA-BASED JOINT FAILURE MODELLING
# ────────────────────────────────────────────────────────────────────────────

def _fig_copula_joint_distribution(
    fvs: Dict[str, EWSFeatureVector],
    preds: Dict[str, Dict[int, Dict[str, Any]]],
) -> go.Figure:
    """
    Gaussian copula joint distribution of grid failure probability
    and wind speed across monitored locations.
    Shows correlation structure beyond linear Pearson r.
    """
    places = sorted(fvs.keys())
    if len(places) < 2:
        return go.Figure()

    # Get base data
    gf_vals   = [fvs[p].grid_failure_probability for p in places]
    wind_vals = [fvs[p].wind_speed_ms for p in places]
    risk_vals = [preds[p][5]["prediction"].predicted_risk if (p in preds and 5 in preds[p])
                 else fvs[p].final_risk_score for p in places]

    # Generate MC samples from Gaussian copula
    rng_cop = np.random.default_rng(42)
    n_cop   = 400

    # Correlation matrix (empirical + copula)
    mean_gf   = float(np.mean(gf_vals))
    std_gf    = max(float(np.std(gf_vals)), 0.01)
    mean_wind = float(np.mean(wind_vals))
    std_wind  = max(float(np.std(wind_vals)), 0.5)
    rho = min(0.92, max(-0.92, float(np.corrcoef(gf_vals, wind_vals)[0,1])
                         if len(gf_vals) > 1 else 0.6))

    # Bivariate normal samples (Cholesky)
    L = np.array([[1, 0],[rho, math.sqrt(1-rho**2)]])
    z = rng_cop.normal(0, 1, (n_cop, 2)) @ L.T
    # Transform to uniform via CDF → transform to marginal distribution
    u1 = [_gaussian_cdf(z_) for z_ in z[:,0]]
    u2 = [_gaussian_cdf(z_) for z_ in z[:,1]]
    x_sim = [clamp(mean_gf   + std_gf   * 4 * (u-0.5), 0, 1)    for u in u1]
    y_sim = [clamp(mean_wind + std_wind * 8 * (u-0.5), 0, 50)    for u in u2]

    # Risk-colour for actual observations
    al_cols = [ALERT_COLOUR.get(preds[p][5]["prediction"].alert_level, "#94a3b8")
               if p in preds and 5 in preds[p] else "#94a3b8" for p in places]

    fig = go.Figure()
    # Copula samples (background distribution)
    fig.add_trace(go.Scatter(
        x=x_sim, y=y_sim, mode="markers",
        name=f"Copula samples (ρ={rho:.2f})",
        marker=dict(size=4, color="rgba(56,189,248,0.12)", line=dict(width=0)),
        hoverinfo="none",
    ))
    # Observed locations
    fig.add_trace(go.Scatter(
        x=gf_vals, y=wind_vals, mode="markers+text",
        text=[p[:12] for p in places], textposition="top center", textfont=dict(size=9),
        name="Monitored locations",
        marker=dict(size=14, color=al_cols, opacity=0.88,
                    line=dict(color="white",width=1.5)),
        hovertemplate="<b>%{text}</b><br>GF: %{x:.3f}<br>Wind: %{y:.1f} m/s<extra></extra>",
    ))
    # Tail risk contour lines (simplified)
    fig.add_vline(x=EWS_THRESHOLDS["grid_fail"]["amber"]/100, line_dash="dash",
                  line_color="#f97316", line_width=1, annotation_text="GF AMBER", annotation_font_size=9)
    fig.add_hline(y=14, line_dash="dash", line_color="#f97316", line_width=1,
                  annotation_text="50 km/h", annotation_font_size=9)

    fig.update_layout(
        title=f"Gaussian copula — GF probability vs wind speed (ρ={rho:.2f})",
        xaxis_title="Grid failure probability",
        yaxis_title="Wind speed (m/s)",
        template=plotly_template(), height=380,
        margin=dict(l=20,r=20,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.24),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 8.4  FINANCIAL IMPACT DEEP-DIVE
# ────────────────────────────────────────────────────────────────────────────

# UK regulatory financial parameters (Ofgem RIIO-ED2 2023)
FINANCIAL_PARAMS = {
    "voll_per_mwh":              17_000,   # £/MWh — Value of Lost Load
    "customer_interruption":        48,    # £/customer interrupted (CML-based)
    "customer_minutes_lost":        0.80,  # £/customer per minute
    "restoration_cost_per_outage": 18_500, # £/outage event (DNO ops cost)
    "network_damage_per_fault":  12_000,   # £/structural fault (OHL, cable)
    "emergency_crew_hour":           285,  # £/crew-hour (inclusive)
    "mutual_aid_day":             18_000,  # £/crew-day for external mutual aid
    "ofgem_penalty_per_ci":          150,  # £/customer for SLA breach
    "business_multiplier":           3.8,  # commercial vs residential VoLL ratio
    "critical_infra_multiplier":     5.5,  # hospital/emergency services VoLL
}


def compute_financial_deep_dive(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    fvs: Dict[str, EWSFeatureVector],
) -> pd.DataFrame:
    """
    Detailed financial breakdown per location at T+5min.
    Components: VoLL, customer interruption, restoration, network damage,
    emergency crew costs, mutual aid, Ofgem penalties.
    """
    rows = []
    fp = FINANCIAL_PARAMS

    for place, pv in preds.items():
        if 5 not in pv:
            continue
        po  = pv[5]["prediction"]
        fv  = fvs.get(place)
        if not fv:
            continue

        ens_mw   = po.predicted_ens_mw
        cust     = max(fv.affected_customers, 0)
        outages  = fv.nearby_outages_25km
        risk     = po.predicted_risk
        alert    = po.alert_level

        # Hours of disruption (estimated from alert level)
        est_hours = {AlertLevel.GREEN:0, AlertLevel.YELLOW:0.5,
                     AlertLevel.AMBER:2.5, AlertLevel.RED:8.0, AlertLevel.CRITICAL:14.0
        }.get(alert, 0)

        voll_cost   = ens_mw * fp["voll_per_mwh"] * est_hours
        ci_cost     = cust  * fp["customer_interruption"]
        cml_cost    = cust  * fp["customer_minutes_lost"] * est_hours * 60
        rest_cost   = outages * fp["restoration_cost_per_outage"]
        damage_cost = max(0, outages - 2) * fp["network_damage_per_fault"]
        crew_cost   = max(2, outages//3) * fp["emergency_crew_hour"] * max(1, est_hours)
        mutual_aid  = (max(0, outages-5) * fp["mutual_aid_day"]
                       if alert.value >= AlertLevel.RED.value else 0)
        penalty     = (cust * fp["ofgem_penalty_per_ci"]
                       if alert.value >= AlertLevel.RED.value else 0)

        total = voll_cost + ci_cost + cml_cost + rest_cost + damage_cost + crew_cost + mutual_aid + penalty

        rows.append({
            "Location":            place,
            "Alert":               alert.name,
            "Est. hours":          f"{est_hours:.1f}",
            "VoLL (£k)":           f"{voll_cost/1e3:.1f}",
            "Customer intr. (£k)": f"{(ci_cost+cml_cost)/1e3:.1f}",
            "Restoration (£k)":    f"{rest_cost/1e3:.1f}",
            "Network damage (£k)": f"{damage_cost/1e3:.1f}",
            "Crew cost (£k)":      f"{crew_cost/1e3:.1f}",
            "Mutual aid (£k)":     f"{mutual_aid/1e3:.1f}",
            "Ofgem penalty (£k)":  f"{penalty/1e3:.1f}",
            "TOTAL (£k)":          f"{total/1e3:.1f}",
        })
    return pd.DataFrame(rows)


def _fig_financial_breakdown(
    preds: Dict[str, Dict[int, Dict[str, Any]]],
    fvs: Dict[str, EWSFeatureVector],
) -> go.Figure:
    """Stacked bar: financial loss components per location."""
    fp = FINANCIAL_PARAMS
    places = sorted(preds.keys())
    components = {
        "VoLL": [], "Customer intr.": [], "Restoration": [],
        "Network damage": [], "Crew cost": [], "Mutual aid/Penalty": [],
    }
    for place in places:
        if 5 not in preds.get(place,{}):
            for v in components.values(): v.append(0)
            continue
        po  = preds[place][5]["prediction"]
        fv  = fvs.get(place)
        if not fv:
            for v in components.values(): v.append(0)
            continue

        ens_mw  = po.predicted_ens_mw
        cust    = max(fv.affected_customers, 0)
        outages = fv.nearby_outages_25km
        alert   = po.alert_level
        est_h   = {AlertLevel.GREEN:0,AlertLevel.YELLOW:0.5,AlertLevel.AMBER:2.5,
                   AlertLevel.RED:8.0,AlertLevel.CRITICAL:14.0}.get(alert,0)

        components["VoLL"].append(ens_mw*fp["voll_per_mwh"]*est_h/1e3)
        components["Customer intr."].append((cust*fp["customer_interruption"]+cust*fp["customer_minutes_lost"]*est_h*60)/1e3)
        components["Restoration"].append(outages*fp["restoration_cost_per_outage"]/1e3)
        components["Network damage"].append(max(0,outages-2)*fp["network_damage_per_fault"]/1e3)
        components["Crew cost"].append(max(2,outages//3)*fp["emergency_crew_hour"]*max(1,est_h)/1e3)
        components["Mutual aid/Penalty"].append(
            ((max(0,outages-5)*fp["mutual_aid_day"]+cust*fp["ofgem_penalty_per_ci"])
             if alert.value>=AlertLevel.RED.value else 0)/1e3
        )

    colours = ["#ef4444","#f97316","#38bdf8","#a855f7","#eab308","#22c55e"]
    fig = go.Figure()
    for (comp_name, vals), col in zip(components.items(), colours):
        fig.add_trace(go.Bar(name=comp_name, x=places, y=vals,
                             marker_color=col, opacity=0.82))
    fig.update_layout(
        barmode="stack",
        title="Financial loss breakdown by component (£k)",
        yaxis_title="£ thousands",
        template=plotly_template(), height=380,
        margin=dict(l=20,r=20,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.28),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 8.5  HINDCAST CRPS DEEP-DIVE
# ────────────────────────────────────────────────────────────────────────────

def _fig_hindcast_crps_by_event(records: List) -> go.Figure:
    """
    CRPS by simulated historical event (aggregated from hindcast records
    that fall within each historical event's month).
    """
    from collections import defaultdict

    # Map records to event periods
    event_months = {ev.name: ev.date[:7] for ev in EWS_HISTORICAL_EVENTS}
    crps_by_event_model: Dict[str, Dict[str, List[float]]] = defaultdict(lambda: defaultdict(list))

    for r in records:
        date_m = r.date[:7]
        for ev_name, ev_month in event_months.items():
            if date_m == ev_month:
                crps_by_event_model[ev_name][r.model_arch].append(r.crps_score)

    events   = list(crps_by_event_model.keys())
    models   = sorted({m for ed in crps_by_event_model.values() for m in ed})
    colours  = ["#38bdf8","#a855f7","#22c55e","#f97316","#eab308",
                "#ef4444","#94a3b8","#0ea5e9","#84cc16","#f43f5e"]

    fig = go.Figure()
    for i, mname in enumerate(models):
        short = mname.split("(")[0].strip()[:20]
        ev_crps = [float(np.mean(crps_by_event_model[ev].get(mname, [0.5])))
                   for ev in events]
        fig.add_trace(go.Bar(
            name=short, x=events, y=ev_crps,
            marker_color=colours[i % len(colours)], opacity=0.82,
        ))

    fig.update_layout(
        barmode="group",
        title="CRPS by historical event period — model comparison",
        xaxis_tickangle=-20,
        yaxis_title="Mean CRPS (lower = better)",
        template=plotly_template(), height=380,
        margin=dict(l=20,r=20,t=55,b=40),
        legend=dict(orientation="h",yanchor="bottom",y=-0.40,font=dict(size=8)),
    )
    return fig


def _fig_error_attribution(records: List) -> go.Figure:
    """
    Forecast error attribution by time of day and month.
    Shows when models are most biased.
    """
    from collections import defaultdict
    if not records:
        return go.Figure()

    # Ensemble records only
    ens_recs = [r for r in records if "Ensemble" in r.model_arch][:240]
    if not ens_recs:
        ens_recs = records[:240]

    # Aggregate by horizon
    error_by_h: Dict[int, List[float]] = defaultdict(list)
    for r in ens_recs:
        error_by_h[r.horizon_min].append(r.error)

    horizons = sorted(error_by_h.keys())
    h_labels = [EWS_HORIZON_LABELS.get(h,"").split("(")[0].strip() for h in horizons]
    means    = [float(np.mean(error_by_h[h])) for h in horizons]
    stds     = [float(np.std(error_by_h[h]))  for h in horizons]

    fig = go.Figure()
    fig.add_trace(go.Bar(
        x=h_labels, y=means, error_y=dict(type="data", array=stds, visible=True),
        marker_color=["#22c55e" if m < 0 else "#ef4444" for m in means],
        opacity=0.82, name="Mean bias",
    ))
    fig.add_hline(y=0, line_color="#64748b", line_width=1.5)
    fig.update_layout(
        title="Forecast bias by horizon (ensemble model)",
        xaxis_title="Horizon",
        yaxis_title="Mean error (forecast − observed)",
        template=plotly_template(), height=300,
        margin=dict(l=20,r=20,t=55,b=20),
    )
    return fig


