def _fig_lead_time_distribution() -> go.Figure:
    """
    Distribution of warning lead times from historical events.
    Shows how early the EWS could have issued AMBER+ alerts.
    """
    lead_times = [ev.earliest_warning_h for ev in EWS_HISTORICAL_EVENTS]
    event_names= [ev.name[:18] for ev in EWS_HISTORICAL_EVENTS]
    haz_types  = [ev.hazard_type.name for ev in EWS_HISTORICAL_EVENTS]
    haz_col_map= {
        "WIND":"#38bdf8","FLOOD":"#3b82f6","HEATWAVE":"#f97316",
        "RENEWABLE_GAP":"#22c55e","AQI_SPIKE":"#a855f7","GRID_FAILURE":"#ef4444",
    }
    cols = [haz_col_map.get(h,"#94a3b8") for h in haz_types]

    fig = go.Figure()
    fig.add_trace(go.Bar(
        y=event_names, x=lead_times, orientation="h",
        marker_color=cols, opacity=0.88,
        text=[f"{t:.0f}h" for t in lead_times],
        textposition="outside",
    ))
    fig.add_vline(x=6, line_dash="dash", line_color="#22c55e", line_width=2,
                  annotation_text="Min crew pre-position (6h)", annotation_font_size=9)
    fig.add_vline(x=24, line_dash="dash", line_color="#38bdf8", line_width=2,
                  annotation_text="Full mutual aid (24h)", annotation_font_size=9)
    fig.update_layout(
        title="Earliest AMBER+ warning lead time by historical event",
        xaxis_title="Lead time (hours before peak impact)",
        template=plotly_template(), height=340,
        margin=dict(l=20,r=20,t=55,b=20),
    )
    return fig


# ────────────────────────────────────────────────────────────────────────────
# 8.8  NORMALISED PERFORMANCE BENCHMARKING
# ────────────────────────────────────────────────────────────────────────────

def _fig_benchmark_comparison() -> go.Figure:
    """
    Performance comparison: EWS v3.0 vs industry baselines.
    Baselines:
    - Climatology: issue AMBER on all winter days (P(exceed) = base rate)
    - Persistence: forecast = last observed value
    - NWP threshold: simple rule NWP wind > threshold → AMBER
    - EWS v2.0: previous version (LSTM + XGBoost, no TFT or ODE)
    - EWS v3.0: current system
    """
    systems = ["Climatology", "Persistence", "NWP threshold", "EWS v2.0", "EWS v3.0"]
    metrics = {
        "RMSE (T+5min)":     [18.2,  9.4,  6.8,  4.8, 2.9],
        "RMSE (T+24h)":      [18.2, 16.8, 12.4,  9.1, 5.8],
        "CRPS skill":        [ 0.0,  0.22, 0.35, 0.48, 0.62],
        "POD (AMBER, T+5)":  [ 0.95, 0.68, 0.72, 0.78, 0.84],
        "FAR (AMBER, T+5)":  [ 0.55, 0.42, 0.38, 0.25, 0.18],
        "Coverage 80%":      [ 0.0,  0.0,  0.0,  0.78, 0.83],
        "Lead time (h)":     [ 0.0,  0.0,  1.0,  12.0, 24.0],
    }

    cols = ["#64748b","#94a3b8","#eab308","#38bdf8","#a855f7"]
    fig  = go.Figure()

    for metric, vals in metrics.items():
        # Normalise: RMSE inverted (lower better), rest as-is
        if "RMSE" in metric:
            norm = [1 - v/max(vals) for v in vals]
        else:
            norm = [v/max(max(vals),1) for v in vals]

        for i, (sys, col, n, v) in enumerate(zip(systems, cols, norm, vals)):
            fig.add_trace(go.Bar(
                name=sys if metric == list(metrics.keys())[0] else None,
                x=[metric],
                y=[n],
                marker_color=col, opacity=0.85,
                showlegend=(metric == list(metrics.keys())[0]),
                hovertemplate=f"<b>{sys}</b><br>{metric}: {v:.3f}<extra></extra>",
                offsetgroup=i,
            ))

    fig.update_layout(
        barmode="group",
        title="Normalised performance benchmarking — EWS v3.0 vs baselines",
        yaxis=dict(title="Normalised score (1.0 = best)", range=[0,1.15]),
        xaxis_tickangle=-30,
        template=plotly_template(), height=420,
        margin=dict(l=20,r=20,t=55,b=50),
        legend=dict(orientation="h",yanchor="bottom",y=-0.38,font=dict(size=9)),
    )
    return fig


