def render_ews_tab_full(
    region:          str,
    active_scenario: str,
    places:          pd.DataFrame,
    outages:         pd.DataFrame,
) -> None:
    """
    SAT-Guard EWS v3.0 — Complete Dashboard (all 8 extensions integrated).

    Sub-tabs:
      🎯 Overview
      🤖 AI Models
      🚨 Alerts
      ✅ Validation
      🗂 History
      🧪 Stress Test
      💡 Decisions
      🖥 Monitoring
      📊 Advanced Analytics
      📐 Monte Carlo & Risk
      💰 Financial Impact
      🔭 Methodology
      🚀 Deployment
    """
    st.markdown(APP_CSS, unsafe_allow_html=True)

    st.markdown(
        '<div class="card"><span style="font-size:22px;font-weight:950;color:white;">'
        '🛰 SAT-Guard EWS v3.0 — Advanced AI/ML Early Warning System</span><br>'
        '<span style="color:#94a3b8;font-size:13px;">'
        '9-model ensemble · Stacked generalisation · Conformal CI · 4-component UQ · '
        'T+5m–T+24h · 9 dispatch channels · Hindcast validation · '
        'Historical DB · Stress-test · CVaR Monte Carlo · GEV return periods'
        '</span></div>', unsafe_allow_html=True)

    if places.empty:
        st.error("No place data — run the main pipeline first.")
        return

    # Cache in session_state (avoids @st.cache_data serialisation of custom dataclasses)
    _cache_key = f"ews_pipeline_{region}_{active_scenario}_{len(places)}"
    if _cache_key not in st.session_state:
        with st.spinner("🤖 Running 9-model ensemble…"):
            st.session_state[_cache_key] = run_ews_pipeline(
                region, active_scenario, places.to_dict("records"))
    res = st.session_state[_cache_key]

    preds   = res["predictions"]
    alerts  = res["alerts"]
    summary = res["summary"]
    fvs     = res["fvs"]
    shap_r  = res["shap"]
    anom_r  = res["anomaly"]

    # Hero banner
    lvl = summary["max_alert_level"]
    c   = ALERT_COLOUR[lvl]; bg = ALERT_BG[lvl]; ts = summary["run_ts"][:19].replace("T"," ")
    st.markdown(
        f'<div style="border:2px solid {c};background:{bg};border-radius:20px;'
        f'padding:16px 22px;margin-bottom:14px;">'
        f'<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;">'
        f'<div><span style="font-size:18px;font-weight:900;color:white;">'
        f'🛰 SAT-Guard EWS v{EWS_VERSION}</span><br>'
        f'<span style="color:#94a3b8;font-size:12px;">'
        f'{summary["places_monitored"]} locations · {len(EWS_HORIZONS)} horizons · '
        f'9 AI models · {ts} UTC</span></div>'
        f'<div style="text-align:right;">{_badge(lvl)}<br>'
        f'<span style="color:#94a3b8;font-size:11px;">'
        f'{summary["total_alerts_dispatched"]} alerts</span></div></div>'
        f'<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;">'
        f'<span class="chip">Exceedance: {summary["max_exceedance"]*100:.1f}%</span>'
        f'<span class="chip">OOD: {summary["avg_ood"]:.3f}</span>'
        f'<span class="chip">Peak: {summary["highest_risk_place"]}</span>'
        f'<span class="chip">{active_scenario}</span>'
        f'</div></div>', unsafe_allow_html=True)

    # KPI strip
    k1,k2,k3,k4,k5,k6 = st.columns(6)
    k1.metric("Max alert",       lvl.name)
    k2.metric("Alerts sent",     str(summary["total_alerts_dispatched"]))
    k3.metric("Critical places", str(len(summary["critical_places"])))
    k4.metric("Max exceedance",  f"{summary['max_exceedance']*100:.1f}%")
    k5.metric("Avg OOD score",   f"{summary['avg_ood']:.3f}")
    k6.metric("Highest risk",    summary["highest_risk_place"])
    st.markdown("---")

    # 13 sub-tabs
    (
        t_ov, t_md, t_al, t_vl, t_hi,
        t_st, t_ds, t_mn, t_aa, t_mc,
        t_fi, t_me, t_dp,
    ) = st.tabs([
        "🎯 Overview", "🤖 AI Models", "🚨 Alerts",
        "✅ Validation", "🗂 History",
        "🧪 Stress Test", "💡 Decisions", "🖥 Monitoring",
        "📊 Advanced Analytics", "📊 Monte Carlo & Risk",
        "💰 Financial", "🔭 Methodology", "🚀 Deployment",
    ])

    # -- OVERVIEW --
    with t_ov:
        sc1, sc2 = st.columns(2)
        with sc1:
            sel_place_ov = st.selectbox("Location", sorted(preds.keys()), key="ov2_pl")
        with sc2:
            h_opts_ov = sorted({h for pv in preds.values() for h in pv})
            sel_h_ov  = st.selectbox("Horizon", h_opts_ov,
                                      format_func=lambda h: EWS_HORIZON_LABELS.get(h,f"T+{h}min"),
                                      key="ov2_h")
        c1, c2 = st.columns(2)
        with c1: st.plotly_chart(_fig_risk_fan(preds, sel_place_ov), use_container_width=True, key="ov2_fan")
        with c2: st.plotly_chart(_fig_exceedance_bar(preds), use_container_width=True, key="ov2_exc")
        st.plotly_chart(_fig_heatmap(preds), use_container_width=True, key="ov2_hm")
