PYTORCH_BILSTM_CODE: str = '''
# ══════════════════════════════════════════════════════
# SAT-Guard EWS — BiLSTM + Temporal Attention (PyTorch)
# ══════════════════════════════════════════════════════
import torch
import torch.nn as nn
import torch.nn.functional as F
from typing import Tuple


class TemporalAttention(nn.Module):
    """
    Scaled dot-product temporal attention.
    Learns which timesteps in the 12h input window are most
    informative for each forecast horizon.
    """
    def __init__(self, hidden_dim: int):
        super().__init__()
        self.query = nn.Linear(hidden_dim, hidden_dim)
        self.key   = nn.Linear(hidden_dim, hidden_dim)
        self.value = nn.Linear(hidden_dim, hidden_dim)
        self.scale = hidden_dim ** 0.5

    def forward(self, h: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
        # h: (batch, seq_len, hidden_dim)
        Q = self.query(h)
        K = self.key(h)
        V = self.value(h)
        scores  = torch.bmm(Q, K.transpose(1, 2)) / self.scale
        weights = F.softmax(scores, dim=-1)
        context = torch.bmm(weights, V)
        return context, weights   # weights for explainability


class BiLSTMAttentionModel(nn.Module):
    """
    Bidirectional LSTM (2 layers, hidden=128 per direction)
    + Temporal Self-Attention → quantile output heads.

    Input:  (batch, seq_len=48, n_features=72)
    Output: (batch, 3)  — [q10, q50, q90]

    Training:
        Loss = PinballLoss(τ=[0.10, 0.50, 0.90]) + 0.30 × MSE(q50, observed)
        Optimiser: AdamW lr=3e-4, weight_decay=1e-5
        Scheduler: CosineAnnealingWarmRestarts(T0=30)
        Batch: 256   Epochs: 150   Early stopping: patience=15
    """
    def __init__(
        self,
        n_features:  int = 72,
        hidden_dim:  int = 128,
        n_layers:    int = 2,
        dropout:     float = 0.25,
        output_dim:  int = 3,   # [q10, q50, q90]
    ):
        super().__init__()
        self.embedding = nn.Linear(n_features, 64)
        self.bilstm    = nn.LSTM(
            input_size=64, hidden_size=hidden_dim,
            num_layers=n_layers, batch_first=True,
            bidirectional=True, dropout=dropout if n_layers > 1 else 0.0,
        )
        self.dropout    = nn.Dropout(dropout)
        self.attention  = TemporalAttention(hidden_dim * 2)  # bidirectional → ×2
        self.fc1        = nn.Linear(hidden_dim * 2, 64)
        self.gelu       = nn.GELU()
        self.fc_out     = nn.Linear(64, output_dim)
        self._init_weights()

    def _init_weights(self):
        for name, p in self.named_parameters():
            if "weight_ih" in name:
                nn.init.xavier_uniform_(p)
            elif "weight_hh" in name:
                nn.init.orthogonal_(p)
            elif "bias" in name:
                nn.init.zeros_(p)

    def forward(
        self,
        x: torch.Tensor,
        return_attention: bool = False,
    ) -> Tuple[torch.Tensor, ...]:
        # x: (batch, seq_len, n_features)
        emb            = self.gelu(self.embedding(x))
        lstm_out, _    = self.bilstm(emb)
        lstm_out        = self.dropout(lstm_out)
        context, attn  = self.attention(lstm_out)
        # Pool over time dimension
        pooled         = context.mean(dim=1)
        h              = self.gelu(self.fc1(pooled))
        quantiles      = self.fc_out(h)   # [q10, q50, q90] in risk-score units
        if return_attention:
            return quantiles, attn
        return quantiles,


class PinballLoss(nn.Module):
    """
    Quantile (pinball) loss for probabilistic forecasting.
    L(q, y, τ) = max(τ × (y-q), (τ-1) × (y-q))
    """
    def __init__(self, quantiles: list = None):
        super().__init__()
        self.quantiles = quantiles or [0.10, 0.50, 0.90]

    def forward(self, preds: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        # preds: (batch, n_quantiles)  target: (batch,)
        losses = []
        for i, tau in enumerate(self.quantiles):
            pred_q = preds[:, i]
            diff   = target - pred_q
            loss   = torch.max(tau * diff, (tau - 1) * diff)
            losses.append(loss.mean())
        return torch.stack(losses).sum()


# Usage
if __name__ == "__main__":
    model    = BiLSTMAttentionModel(n_features=72)
    x_batch  = torch.randn(32, 48, 72)   # batch=32, seq=48, features=72
    preds, _ = model(x_batch, return_attention=True)
    print(f"Output shape: {preds.shape}")   # (32, 3)
'''


PYTORCH_TFT_CODE: str = '''
# ══════════════════════════════════════════════════════
# SAT-Guard EWS — Temporal Fusion Transformer (PyTorch)
# ══════════════════════════════════════════════════════
import torch
import torch.nn as nn
import torch.nn.functional as F


class GatedResidualNetwork(nn.Module):
    """
    GRN(x, c=None) = LayerNorm(x + Gate(x, c))
    Gate function: ELU + Linear → sigmoid → element-wise multiplication.
    Optional context vector c for static metadata injection.
    """
    def __init__(self, input_dim: int, hidden_dim: int, output_dim: int,
                 dropout: float = 0.1, context_dim: int = None):
        super().__init__()
        self.W1     = nn.Linear(input_dim + (context_dim or 0), hidden_dim)
        self.W2     = nn.Linear(hidden_dim, output_dim)
        self.Wgate  = nn.Linear(hidden_dim, output_dim)
        self.W_res  = nn.Linear(input_dim, output_dim) if input_dim != output_dim else nn.Identity()
        self.elu    = nn.ELU()
        self.sigmoid= nn.Sigmoid()
        self.norm   = nn.LayerNorm(output_dim)
        self.dropout= nn.Dropout(dropout)

    def forward(self, x: torch.Tensor, context: torch.Tensor = None) -> torch.Tensor:
        if context is not None:
            x_c = torch.cat([x, context], dim=-1)
        else:
            x_c = x
        h1   = self.elu(self.W1(x_c))
        h1   = self.dropout(h1)
        gate = self.sigmoid(self.Wgate(h1))
        out  = self.W2(h1) * gate
        return self.norm(out + self.W_res(x))


class VariableSelectionNetwork(nn.Module):
    """
    Learns per-feature attention weights.
    Returns: selected features + softmax attention weights (for explainability).
    """
    def __init__(self, n_features: int, hidden_dim: int, dropout: float = 0.1):
        super().__init__()
        self.grns      = nn.ModuleList([
            GatedResidualNetwork(1, hidden_dim, hidden_dim, dropout) for _ in range(n_features)
        ])
        self.grn_all   = GatedResidualNetwork(n_features, hidden_dim, n_features, dropout)
        self.softmax   = nn.Softmax(dim=-1)

    def forward(self, x: torch.Tensor) -> tuple:
        # x: (batch, seq, n_features) or (batch, n_features)
        transformed  = torch.stack([grn(x[..., i:i+1]) for i, grn in enumerate(self.grns)], dim=-1)
        attn_weights = self.softmax(self.grn_all(x))
        selected     = (transformed * attn_weights.unsqueeze(-2)).sum(dim=-1)
        return selected, attn_weights


class TemporalFusionTransformer(nn.Module):
    """
    TFT for probabilistic risk forecasting.
    Separates:
      - Static covariates (location metadata: lat, lon, population, business density)
      - Known future inputs (calendar: hour, day, month, peak demand flag)
      - Unknown past inputs (all 61 remaining features)

    Architecture:
      VSN(static) → static context vectors
      VSN(known future) × seq_len → sequence
      VSN(unknown past) × seq_len → sequence
      LSTM encoder-decoder
      Multi-head self-attention (8 heads)
      GLU gating → quantile output heads
    """
    def __init__(
        self,
        n_static:  int = 5,    # lat, lon, pop_density, business_density, social_vuln
        n_known:   int = 6,    # hour, dow, month, is_weekend, is_peak, season
        n_unknown: int = 61,   # all other features
        hidden:    int = 128,
        n_heads:   int = 8,
        dropout:   float = 0.1,
        seq_len:   int = 48,   # 12h at 15-min resolution
    ):
        super().__init__()
        self.vsn_static  = VariableSelectionNetwork(n_static,  hidden, dropout)
        self.vsn_known   = VariableSelectionNetwork(n_known,   hidden, dropout)
        self.vsn_unknown = VariableSelectionNetwork(n_unknown, hidden, dropout)

        # Static context GRNs
        self.static_context_enrichment = GatedResidualNetwork(hidden, hidden, hidden, dropout)
        self.static_context_state_h    = GatedResidualNetwork(hidden, hidden, hidden, dropout)
        self.static_context_state_c    = GatedResidualNetwork(hidden, hidden, hidden, dropout)

        # LSTM encoder
        self.lstm_encoder = nn.LSTM(hidden, hidden, batch_first=True)
        self.lstm_decoder = nn.LSTM(hidden, hidden, batch_first=True)

        # Multi-head self-attention
        self.attention = nn.MultiheadAttention(hidden, n_heads, dropout=dropout, batch_first=True)

        # GLU and output
        self.glu     = nn.GLU(dim=-1)
        self.norm1   = nn.LayerNorm(hidden)
        self.norm2   = nn.LayerNorm(hidden)
        self.fc_out  = nn.Linear(hidden, 3)  # [q10, q50, q90]
        self.dropout = nn.Dropout(dropout)

    def forward(self, static: torch.Tensor, known: torch.Tensor,
                unknown: torch.Tensor) -> torch.Tensor:
        # static:  (batch, n_static)
        # known:   (batch, seq_len, n_known)
        # unknown: (batch, seq_len, n_unknown)

        # Static feature selection
        static_sel, _ = self.vsn_static(static)
        c_enrich       = self.static_context_enrichment(static_sel)
        c_h            = self.static_context_state_h(static_sel).unsqueeze(0)
        c_c            = self.static_context_state_c(static_sel).unsqueeze(0)

        # Variable selection for sequences
        B, T, _ = unknown.shape
        unk_sel, _ = self.vsn_unknown(unknown)
        kn_sel, _  = self.vsn_known(known)

        # Static enrichment of sequences
        c_enrich_seq = c_enrich.unsqueeze(1).expand(-1, T, -1)
        enc_input    = unk_sel + c_enrich_seq

        # LSTM encoding
        enc_out, (h_n, c_n) = self.lstm_encoder(enc_input, (c_h, c_c))
        dec_out, _           = self.lstm_decoder(kn_sel, (h_n, c_n))
        combined             = enc_out + dec_out

        # Multi-head self-attention
        attn_out, _ = self.attention(combined, combined, combined)
        attn_out     = self.norm1(combined + self.dropout(attn_out))

        # GLU
        gate_input  = torch.cat([attn_out, attn_out], dim=-1)   # double for GLU
        glu_out     = self.glu(gate_input)
        out          = self.norm2(attn_out + glu_out)

        # Pool and output
        pooled   = out.mean(dim=1)
        quantiles = self.fc_out(pooled)
        return quantiles   # (batch, 3) → [q10, q50, q90]
'''


PYTORCH_WAVENET_CODE: str = '''
# ══════════════════════════════════════════════════════
# SAT-Guard EWS — WaveNet Dilated Causal CNN (PyTorch)
# ══════════════════════════════════════════════════════
import torch
import torch.nn as nn
import torch.nn.functional as F


class DilatedCausalConvBlock(nn.Module):
    """
    Single WaveNet-style dilated causal convolution block.

    Gated activation: tanh(Wf * x) ⊙ σ(Wg * x)
    Residual connection: output = x + 1×1 conv(gated activation)
    Skip connection: accumulated for final output
    """
    def __init__(self, n_channels: int, kernel_size: int, dilation: int, n_features: int):
        super().__init__()
        padding = (kernel_size - 1) * dilation
        self.conv_filter  = nn.Conv1d(n_channels, n_channels, kernel_size,
                                       dilation=dilation, padding=padding)
        self.conv_gate    = nn.Conv1d(n_channels, n_channels, kernel_size,
                                       dilation=dilation, padding=padding)
        self.conv_res     = nn.Conv1d(n_channels, n_channels, 1)
        self.conv_skip    = nn.Conv1d(n_channels, n_channels, 1)
        self.dilation     = dilation
        self.padding      = padding

    def forward(self, x: torch.Tensor) -> tuple:
        # x: (batch, channels, seq_len)
        # Causal: remove right-side padding
        filt  = self.conv_filter(x)[..., :x.size(-1)]
        gate  = self.conv_gate(x)  [..., :x.size(-1)]
        act   = torch.tanh(filt) * torch.sigmoid(gate)
        skip  = self.conv_skip(act)
        res   = self.conv_res(act) + x
        return res, skip


class WaveNetModel(nn.Module):
    """
    WaveNet-style dilated causal CNN for probabilistic risk forecasting.

    8 layers with dilation rates [1, 2, 4, 8, 16, 32, 64, 128].
    Receptive field = (kernel_size-1) × (2^8 - 1) = 2 × 255 = 510 timesteps.
    At 15-min resolution: 510 × 15min = 127.5 hours ≈ 5.3 days.

    Input:  (batch, seq_len=255, n_features=72)
    Output: (batch, 3) — [q10, q50, q90]
    """
    DILATIONS = [1, 2, 4, 8, 16, 32, 64, 128]
    KERNEL    = 3

    def __init__(
        self,
        n_features: int = 72,
        n_channels: int = 64,
        dropout:    float = 0.10,
    ):
        super().__init__()
        self.input_conv = nn.Conv1d(n_features, n_channels, 1)
        self.blocks     = nn.ModuleList([
            DilatedCausalConvBlock(n_channels, self.KERNEL, d, n_features)
            for d in self.DILATIONS
        ])
        self.relu    = nn.ReLU()
        self.dropout = nn.Dropout(dropout)
        self.out1    = nn.Conv1d(n_channels, n_channels, 1)
        self.out2    = nn.Conv1d(n_channels, 3, 1)   # 3 quantile heads

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # x: (batch, seq_len, n_features) → (batch, n_features, seq_len)
        x   = x.transpose(1, 2)
        h   = self.relu(self.input_conv(x))
        skip_sum = torch.zeros_like(h)
        for block in self.blocks:
            h, skip = block(h)
            skip_sum = skip_sum + skip
        out = self.relu(skip_sum)
        out = self.dropout(out)
        out = self.relu(self.out1(out))
        out = self.out2(out)       # (batch, 3, seq_len)
        return out[:, :, -1]       # take last timestep: (batch, 3)
'''


PYTORCH_NEURAL_ODE_CODE: str = '''
# ══════════════════════════════════════════════════════
# SAT-Guard EWS — Latent Neural ODE (PyTorch + torchdiffeq)
# ══════════════════════════════════════════════════════
import torch
import torch.nn as nn
from torchdiffeq import odeint_adjoint as odeint  # pip install torchdiffeq


class ODEFunc(nn.Module):
    """
    ODE function: dz/dt = f_θ(z, t)
    2-layer MLP with tanh activations.
    The time argument t enables non-autonomous dynamics
    (e.g. diurnal load patterns).
    """
    def __init__(self, latent_dim: int = 32, hidden_dim: int = 64):
        super().__init__()
        self.fc1  = nn.Linear(latent_dim + 1, hidden_dim)   # +1 for time
        self.fc2  = nn.Linear(hidden_dim, hidden_dim)
        self.fc3  = nn.Linear(hidden_dim, latent_dim)
        self.tanh = nn.Tanh()

    def forward(self, t: torch.Tensor, z: torch.Tensor) -> torch.Tensor:
        # t: scalar, z: (batch, latent_dim)
        t_expand = t.expand(z.size(0), 1)
        h = torch.cat([z, t_expand], dim=-1)
        h = self.tanh(self.fc1(h))
        h = self.tanh(self.fc2(h))
        return self.fc3(h)


class NeuralODEModel(nn.Module):
    """
    Latent ODE for continuous-time risk forecasting.

    Encoder: RNN over observed sequence → initial latent state (μ₀, σ₀)
    ODE:     Integrate dz/dt = f_θ(z,t) from t=0 to t=horizon
    Decoder: MLP(z_T) → [μ, σ] for predicted risk distribution

    Key advantage: handles irregular observation timestamps.
    If Open-Meteo API is down for 1h, simply pass the irregular timestamps
    to odeint — no interpolation needed.

    Training: ELBO = reconstruction_loss + β × KL(q(z₀) || p(z₀))
    """
    def __init__(
        self,
        n_features:  int = 72,
        latent_dim:  int = 32,
        hidden_dim:  int = 64,
        encoder_hidden: int = 64,
    ):
        super().__init__()
        # Variational encoder: RNN → (μ₀, log σ₀²)
        self.encoder_rnn = nn.GRU(n_features, encoder_hidden, batch_first=True)
        self.encoder_mu  = nn.Linear(encoder_hidden, latent_dim)
        self.encoder_log_var = nn.Linear(encoder_hidden, latent_dim)

        # ODE dynamics
        self.ode_func = ODEFunc(latent_dim, hidden_dim)

        # Decoder: latent → (μ_risk, σ_risk)
        self.decoder = nn.Sequential(
            nn.Linear(latent_dim, hidden_dim),
            nn.Tanh(),
            nn.Linear(hidden_dim, 2),   # [μ, log σ]
        )

    def encode(self, x: torch.Tensor) -> tuple:
        # x: (batch, seq_len, n_features)
        _, h_n  = self.encoder_rnn(x)
        h_n     = h_n.squeeze(0)
        mu      = self.encoder_mu(h_n)
        log_var = self.encoder_log_var(h_n)
        return mu, log_var

    def reparameterise(self, mu: torch.Tensor, log_var: torch.Tensor) -> torch.Tensor:
        std = torch.exp(0.5 * log_var)
        eps = torch.randn_like(std)
        return mu + eps * std

    def forward(self, x: torch.Tensor, t_span: torch.Tensor) -> tuple:
        # x: (batch, seq_len, n_features)
        # t_span: 1D tensor of integration times [t0, t1, ..., T_horizon]
        mu0, log_var0 = self.encode(x)
        z0            = self.reparameterise(mu0, log_var0)

        # Solve ODE from t0 to T_horizon
        z_trajectory  = odeint(
            self.ode_func, z0, t_span,
            method="dopri5",           # Dormand-Prince RK45
            rtol=1e-4, atol=1e-5,
            adjoint_params=list(self.ode_func.parameters()),
        )
        z_T = z_trajectory[-1]         # (batch, latent_dim)

        # Decode latent state to risk prediction
        out    = self.decoder(z_T)
        mu_risk     = out[:, 0]
        log_sigma   = out[:, 1]
        sigma_risk  = torch.exp(log_sigma.clamp(-4, 4))

        # KL divergence (standard normal prior)
        kl = -0.5 * (1 + log_var0 - mu0**2 - torch.exp(log_var0)).sum(dim=-1).mean()
        return mu_risk, sigma_risk, kl
'''


PYTORCH_NBEATS_CODE: str = '''
# ══════════════════════════════════════════════════════
# SAT-Guard EWS — N-BEATS Probabilistic (PyTorch)
# ══════════════════════════════════════════════════════
import torch
import torch.nn as nn
import numpy as np


def trend_basis(theta: torch.Tensor, forecast_len: int) -> torch.Tensor:
    """Polynomial trend basis: θ @ [1, t, t², t³]."""
    p      = theta.size(-1)
    t      = torch.linspace(0, 1, forecast_len, device=theta.device)
    basis  = torch.stack([t ** i for i in range(p)], dim=0)  # (p, T)
    return theta @ basis


def seasonality_basis(
    theta: torch.Tensor,
    forecast_len: int,
    period: float = 24.0,
) -> torch.Tensor:
    """Fourier seasonality basis."""
    K     = theta.size(-1) // 2
    t     = torch.linspace(0, 1, forecast_len, device=theta.device)
    freqs = torch.arange(1, K + 1, dtype=torch.float32, device=theta.device)
    sin_b = torch.sin(2 * np.pi * freqs[:, None] * t[None, :])
    cos_b = torch.cos(2 * np.pi * freqs[:, None] * t[None, :])
    basis = torch.cat([sin_b, cos_b], dim=0)  # (2K, T)
    return theta @ basis


class NBEATSBlock(nn.Module):
    """
    N-BEATS block: fully connected stack with doubly residual connections.
    Produces (backcast, forecast) pair.
    """
    def __init__(
        self,
        input_dim:    int,
        forecast_dim: int,
        n_theta:      int,
        hidden_dim:   int = 256,
        n_layers:     int = 4,
        block_type:   str = "generic",  # "trend", "seasonality", or "generic"
    ):
        super().__init__()
        self.block_type   = block_type
        self.forecast_dim = forecast_dim

        layers = [nn.Linear(input_dim, hidden_dim), nn.ReLU()]
        for _ in range(n_layers - 1):
            layers += [nn.Linear(hidden_dim, hidden_dim), nn.ReLU()]
        self.fc_stack    = nn.Sequential(*layers)
        self.theta_back  = nn.Linear(hidden_dim, n_theta)
        self.theta_fore  = nn.Linear(hidden_dim, n_theta)

    def forward(self, x: torch.Tensor) -> tuple:
        h = self.fc_stack(x)
        theta_b = self.theta_back(h)
        theta_f = self.theta_fore(h)

        if self.block_type == "trend":
            backcast  = trend_basis(theta_b, x.size(-1))
            forecast  = trend_basis(theta_f, self.forecast_dim)
        elif self.block_type == "seasonality":
            backcast  = seasonality_basis(theta_b, x.size(-1))
            forecast  = seasonality_basis(theta_f, self.forecast_dim)
        else:
            backcast  = theta_b  # generic: linear projection
            forecast  = theta_f

        return backcast, forecast


class NBEATSModel(nn.Module):
    """
    N-BEATS with 3 stacks: Trend, Seasonality, Generic (residual).
    Doubly residual architecture: each stack receives the residual
    from the previous stack.

    Output: probabilistic (mean, std) via NLL loss on residual distribution.
    """
    def __init__(
        self,
        input_len:    int = 48,   # sequence length
        forecast_len: int = 1,    # predict 1 step ahead
        hidden_dim:   int = 256,
        n_blocks_per_stack: int = 4,
    ):
        super().__init__()
        self.input_len    = input_len
        self.forecast_len = forecast_len

        self.trend_stack = nn.ModuleList([
            NBEATSBlock(input_len, forecast_len, 4, hidden_dim, block_type="trend")
            for _ in range(n_blocks_per_stack)
        ])
        self.season_stack = nn.ModuleList([
            NBEATSBlock(input_len, forecast_len, 24, hidden_dim, block_type="seasonality")
            for _ in range(n_blocks_per_stack)
        ])
        self.generic_stack = nn.ModuleList([
            NBEATSBlock(input_len, forecast_len, forecast_len, hidden_dim, block_type="generic")
            for _ in range(n_blocks_per_stack)
        ])
        # Probabilistic head: estimate uncertainty from residual magnitude
        self.unc_head = nn.Sequential(
            nn.Linear(forecast_len * 3, 32), nn.ReLU(),
            nn.Linear(32, 2),   # [mean_adjustment, log_std]
        )

    def forward(self, x: torch.Tensor) -> tuple:
        # x: (batch, input_len) — flattened feature summary
        residual  = x
        forecasts = []

        for block in self.trend_stack:
            backcast, forecast = block(residual)
            residual = residual - backcast
            forecasts.append(forecast)

        for block in self.season_stack:
            backcast, forecast = block(residual)
            residual = residual - backcast
            forecasts.append(forecast)

        for block in self.generic_stack:
            backcast, forecast = block(residual)
            residual = residual - backcast
            forecasts.append(forecast)

        total_forecast = sum(forecasts[:3])  # sum of 3 stack outputs
        forecast_cat   = torch.cat(forecasts[:3], dim=-1)
        unc_out        = self.unc_head(forecast_cat)
        mean_adj, log_std = unc_out[:, 0], unc_out[:, 1]
        std  = torch.exp(log_std.clamp(-4, 4))
        mean = total_forecast.squeeze(-1) + mean_adj
        return mean, std   # (batch,), (batch,)
'''


PYTORCH_TRAINING_LOOP: str = '''
# ══════════════════════════════════════════════════════
# SAT-Guard EWS — Training Loop + Temperature Scaling
# ══════════════════════════════════════════════════════
import torch
import torch.nn as nn
import numpy as np
from torch.optim import AdamW
from torch.optim.lr_scheduler import CosineAnnealingWarmRestarts


def crps_gaussian(y_true: torch.Tensor, mu: torch.Tensor,
                  sigma: torch.Tensor) -> torch.Tensor:
    """
    CRPS under Gaussian predictive distribution.
    CRPS(N(μ,σ), y) = σ[z(2Φ(z)-1) + 2φ(z) - 1/√π]
    where z = (y-μ)/σ.
    """
    z     = (y_true - mu) / sigma.clamp_min(1e-8)
    phi_z = 0.5 * (1 + torch.erf(z / (2 ** 0.5)))
    phi_d = torch.exp(-0.5 * z**2) / (2 * np.pi) ** 0.5
    crps  = sigma * (z * (2 * phi_z - 1) + 2 * phi_d - 1 / (np.pi ** 0.5))
    return crps.mean()


class TemperatureScaling(nn.Module):
    """
    Post-hoc calibration: scales logits by 1/T.
    T=1.0: no change (identity).
    T>1.0: softer probabilities (overconfident model).
    T<1.0: harder probabilities (underconfident model).
    """
    def __init__(self):
        super().__init__()
        self.temperature = nn.Parameter(torch.ones(1))

    def forward(self, logits: torch.Tensor) -> torch.Tensor:
        return logits / self.temperature.clamp_min(0.1)

    def calibrate(self, val_logits: torch.Tensor, val_labels: torch.Tensor,
                  n_iter: int = 50, lr: float = 0.01) -> float:
        """Optimise T on validation set by minimising NLL."""
        optimiser = torch.optim.LBFGS([self.temperature], lr=lr, max_iter=n_iter)
        nll_loss  = nn.BCEWithLogitsLoss()

        def eval_closure():
            optimiser.zero_grad()
            scaled = self.forward(val_logits)
            loss   = nll_loss(scaled, val_labels.float())
            loss.backward()
            return loss

        optimiser.step(eval_closure)
        return float(self.temperature.item())


def train_epoch(
    model: nn.Module,
    loader: torch.utils.data.DataLoader,
    optimiser: torch.optim.Optimizer,
    pinball_loss: nn.Module,
    alpha_crps: float = 0.0,   # additional CRPS loss weight
    alpha_mse:  float = 0.30,  # MSE on q50 loss weight
    device: str = "cuda",
) -> dict:
    model.train()
    total_pin, total_mse, total_crps = 0.0, 0.0, 0.0

    for batch_x, batch_y in loader:
        batch_x = batch_x.to(device)
        batch_y = batch_y.to(device)

        optimiser.zero_grad()
        quantiles, *_ = model(batch_x)      # (batch, 3) — [q10, q50, q90]

        # Pinball loss on all quantiles
        loss_pin = pinball_loss(quantiles, batch_y)

        # MSE penalty on q50 (median)
        loss_mse = nn.MSELoss()(quantiles[:, 1], batch_y) * alpha_mse

        # CRPS if sigma available
        loss_crps = torch.tensor(0.0, device=device)
        if alpha_crps > 0:
            q10, q90 = quantiles[:, 0], quantiles[:, 2]
            sigma_approx = (q90 - q10) / (2 * 1.28)   # approximate σ from IQR
            loss_crps = crps_gaussian(batch_y, quantiles[:, 1], sigma_approx) * alpha_crps

        loss = loss_pin + loss_mse + loss_crps
        loss.backward()
        nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
        optimiser.step()

        total_pin  += loss_pin.item()
        total_mse  += loss_mse.item()
        total_crps += loss_crps.item()

    n = max(len(loader), 1)
    return {"pinball": total_pin/n, "mse": total_mse/n, "crps": total_crps/n}


def train_ews_model(
    model:        nn.Module,
    train_loader: torch.utils.data.DataLoader,
    val_loader:   torch.utils.data.DataLoader,
    n_epochs:     int = 150,
    patience:     int = 15,
    device:       str = "cuda",
) -> dict:
    """Full training loop with early stopping on validation CRPS."""
    model = model.to(device)
    optimiser = AdamW(model.parameters(), lr=3e-4, weight_decay=1e-5)
    scheduler = CosineAnnealingWarmRestarts(optimiser, T_0=30, eta_min=1e-6)
    pinball   = PinballLoss(quantiles=[0.10, 0.50, 0.90])

    best_val_crps = float("inf")
    best_state    = None
    patience_ctr  = 0
    history       = {"train_loss": [], "val_crps": []}

    for epoch in range(1, n_epochs + 1):
        train_metrics = train_epoch(model, train_loader, optimiser, pinball, device=device)
        scheduler.step()

        # Validation CRPS
        model.eval()
        val_crps_vals = []
        with torch.no_grad():
            for x_val, y_val in val_loader:
                x_val, y_val = x_val.to(device), y_val.to(device)
                q_val, *_    = model(x_val)
                sigma_val    = (q_val[:, 2] - q_val[:, 0]) / (2 * 1.28)
                crps_v       = crps_gaussian(y_val, q_val[:, 1], sigma_val)
                val_crps_vals.append(crps_v.item())
        val_crps = float(np.mean(val_crps_vals))

        history["train_loss"].append(train_metrics["pinball"])
        history["val_crps"].append(val_crps)

        if val_crps < best_val_crps:
            best_val_crps = val_crps
            best_state    = {k: v.cpu().clone() for k, v in model.state_dict().items()}
            patience_ctr  = 0
        else:
            patience_ctr += 1
            if patience_ctr >= patience:
                print(f"Early stopping at epoch {epoch}. Best val CRPS: {best_val_crps:.4f}")
                break

        if epoch % 10 == 0:
            print(f"Epoch {epoch:3d} | Train loss: {train_metrics[\"pinball\"]:.4f} "
                  f"| Val CRPS: {val_crps:.4f} | LR: {optimiser.param_groups[0][\"lr\"]:.2e}")

    model.load_state_dict(best_state)
    return {"best_val_crps": best_val_crps, "history": history}
'''


# ────────────────────────────────────────────────────────────────────────────
# 9.3  CAP v1.2 XML ALERT GENERATOR
# ────────────────────────────────────────────────────────────────────────────

def generate_cap_xml(alert: EWSAlert) -> str:
    """
    Generate CAP v1.2 (Common Alerting Protocol) XML for broadcast.
    Used by the Media dispatch channel to trigger Cell Broadcast Emergency Alerts
    and BBC regional service bulletins.
    """
    ts_now = datetime.now(UTC).strftime("%Y-%m-%dT%H:%M:%S+00:00")
    ts_exp = (datetime.now(UTC)+timedelta(minutes=alert.horizon_minutes+30)).strftime("%Y-%m-%dT%H:%M:%S+00:00")

    severity_map = {
        "GREEN":"Minor","YELLOW":"Minor","AMBER":"Moderate",
        "RED":"Severe","CRITICAL":"Extreme",
    }
    urgency_map  = {
        "GREEN":"Future","YELLOW":"Future","AMBER":"Expected",
        "RED":"Immediate","CRITICAL":"Immediate",
    }
    certainty_map= {
        "GREEN":"Unlikely","YELLOW":"Possible","AMBER":"Likely",
        "RED":"Observed","CRITICAL":"Observed",
    }
    level_name   = alert.alert_level.name
    risk         = alert.kpi_snapshot.get("risk", 0)
    ens          = alert.kpi_snapshot.get("ens_mw", 0)
    exc          = alert.kpi_snapshot.get("exceedance_pct", 0)

    xml = f'''<?xml version="1.0" encoding="UTF-8"?>
<alert xmlns="urn:oasis:names:tc:emergency:cap:1.2">
  <identifier>{alert.alert_id}</identifier>
  <sender>sat-guard-ews@satguard.gov.uk</sender>
  <sent>{ts_now}</sent>
  <status>Actual</status>
  <msgType>Alert</msgType>
  <scope>Public</scope>
  <code>EWSv3.0</code>
  <note>Generated by SAT-Guard EWS v3.0 — 9-model AI ensemble</note>
  <info>
    <language>en-GB</language>
    <category>Infra</category>
    <event>{alert.hazard_type.name.replace("_"," ")} — Power Grid Risk</event>
    <responseType>Prepare</responseType>
    <urgency>{urgency_map.get(level_name,"Unknown")}</urgency>
    <severity>{severity_map.get(level_name,"Unknown")}</severity>
    <certainty>{certainty_map.get(level_name,"Unknown")}</certainty>
    <effective>{ts_now}</effective>
    <expires>{ts_exp}</expires>
    <senderName>SAT-Guard Early Warning System</senderName>
    <headline>{html_escape(alert.headline[:256])}</headline>
    <description>
      Risk score: {risk:.1f}/100
      ENS: {ens:.1f} MW
      Exceedance P: {exc:.1f}%
      Horizon: T+{alert.horizon_minutes}min
      {html_escape(alert.body_text[:500])}
    </description>
    <instruction>{html_escape(chr(10).join(alert.recommended_actions[:5]))}</instruction>
    <parameter>
      <valueName>EWS_ALERT_LEVEL</valueName>
      <value>{level_name}</value>
    </parameter>
    <parameter>
      <valueName>EWS_RISK_SCORE</valueName>
      <value>{risk:.1f}</value>
    </parameter>
    <parameter>
      <valueName>EWS_MODEL_VERSION</valueName>
      <value>v{EWS_VERSION}</value>
    </parameter>
    <area>
      <areaDesc>{alert.place}, {alert.region}</areaDesc>
      <geocode>
        <valueName>NUTS2</valueName>
        <value>UKC2</value>
      </geocode>
    </area>
  </info>
</alert>'''
    return xml


# ────────────────────────────────────────────────────────────────────────────
# 9.4  GRID SCENARIO DEEP-DIVE CHARTS
# ────────────────────────────────────────────────────────────────────────────

def _fig_risk_by_scenario_all_places(preds: Dict) -> go.Figure:
    """
    Heat matrix: predicted risk per place per scenario.
    Simulates running all 8 stress scenarios across all monitored places.
    """
    places   = sorted(preds.keys())
    scenarios= list(STRESS_SCENARIOS.keys())
    s_labels = [STRESS_SCENARIOS[s]["label"][:22] for s in scenarios]

    # Simulate scenario risks based on current base + scenario modifiers
    rng_sc = np.random.default_rng(2024)
    z_vals = []
    for place in places:
        base = preds[place][5]["prediction"].predicted_risk if (
            place in preds and 5 in preds[place]) else 30.0
        row = []
        for sc_key in scenarios:
            mods  = STRESS_SCENARIOS[sc_key]["modifiers"]
            delta = sum(abs(v) for v in mods.values() if isinstance(v, (int,float))) / 100
            stressed = clamp(base + delta * float(rng_sc.uniform(0.3,0.7)) + float(rng_sc.normal(0,3)), 0, 100)
            row.append(round(stressed, 1))
        z_vals.append(row)

    fig = go.Figure(go.Heatmap(
        z=z_vals, x=s_labels, y=places,
        colorscale="RdYlGn_r", zmin=0, zmax=100,
        text=[[f"{v:.0f}" for v in row] for row in z_vals],
        texttemplate="%{text}", showscale=True,
        colorbar=dict(title="Risk", thickness=12),
    ))
    fig.update_layout(
        title="Scenario stress matrix — all places × all scenarios",
        xaxis_tickangle=-35, xaxis_side="top",
        template=plotly_template(), height=max(200, 40*len(places)+120),
        margin=dict(l=20,r=20,t=80,b=20),
    )
    return fig


def _fig_sla_tracker(alerts: List[EWSAlert]) -> go.Figure:
    """
    SLA compliance tracker: time from pipeline run to alert dispatch.
    Ofgem requirement: AMBER within 5 minutes, RED within 2 minutes.
    """
    # Simulate dispatch latencies
    rng_sla = np.random.default_rng(42)
    if not alerts:
        return go.Figure()

    levels_seen = {}
    for a in alerts:
        k = a.alert_level.name
        if k not in levels_seen:
            # Simulate dispatch latency: faster for higher levels
            base_lat = {"GREEN":30,"YELLOW":20,"AMBER":8,"RED":3,"CRITICAL":1.5}.get(k,10)
            lat = base_lat * float(rng_sla.uniform(0.7, 1.4))
            levels_seen[k] = round(lat, 1)

    sla_targets = {"AMBER":5,"RED":2,"CRITICAL":1}
    names  = list(levels_seen.keys())
    lats   = list(levels_seen.values())
    sla_t  = [sla_targets.get(n,60) for n in names]
    cols   = ["#22c55e" if lat<=sla else "#ef4444" for lat,sla in zip(lats,sla_t)]

    fig = go.Figure()
    fig.add_trace(go.Bar(
        x=names, y=lats, name="Actual dispatch time (s)",
        marker_color=cols, opacity=0.88,
        text=[f"{v:.1f}s" for v in lats], textposition="outside",
    ))
    fig.add_trace(go.Scatter(
        x=names, y=sla_t, mode="markers+lines",
        name="Ofgem SLA target (s)",
        marker=dict(size=10, color="#f97316", symbol="x",
                    line=dict(color="#f97316",width=2)),
        line=dict(color="#f97316",width=2,dash="dash"),
    ))
    fig.update_layout(
        title="Alert dispatch SLA compliance (green = within target)",
        yaxis_title="Seconds from pipeline trigger to dispatch",
        template=plotly_template(), height=300,
        margin=dict(l=20,r=20,t=55,b=20),
        legend=dict(orientation="h",yanchor="bottom",y=-0.28),
    )
    return fig


