def render_ews_production_code_section() -> None:
    """Render Production Code sub-tab with PyTorch model skeletons."""
    st.markdown("#### 🐍 Production PyTorch Code Skeletons")
    st.caption(
        "Full model definitions ready for production training. "
        "Replace SAT-Guard's simulation-mode predictors with these "
        "trained PyTorch models by implementing the .predict() interface."
    )

    code_tabs = st.tabs([
        "BiLSTM + Attention",
        "Temporal Fusion Transformer",
        "WaveNet",
        "Neural ODE",
        "N-BEATS",
        "Training Loop",
    ])

    code_contents = [
        PYTORCH_BILSTM_CODE,
        PYTORCH_TFT_CODE,
        PYTORCH_WAVENET_CODE,
        PYTORCH_NEURAL_ODE_CODE,
        PYTORCH_NBEATS_CODE,
        PYTORCH_TRAINING_LOOP,
    ]

    for tab, code in zip(code_tabs, code_contents):
        with tab:
            st.code(code, language="python")

    # CAP XML example
    st.markdown("---")
    st.markdown("##### CAP v1.2 XML Alert Example")
    st.caption("Generated for any AMBER+ alert. Used by Media dispatch channel.")
    dummy_alert = EWSAlert(
        alert_id="EWS-NCL-0005-ABCDEF12",
        recipient_type=RecipientType.MEDIA,
        alert_level=AlertLevel.AMBER,
        hazard_type=HazardType.WIND,
        place="Newcastle",
        region="North East",
        horizon_minutes=5,
        generated_at=datetime.now(UTC).isoformat(),
        valid_until=(datetime.now(UTC)+timedelta(minutes=35)).isoformat(),
        headline="AMBER: Extreme wind — Newcastle T+5min — Risk 58/100. OHL damage likely.",
        body_text="SAT-Guard EWS v3.0 alert body.",
        recommended_actions=["Alert on-call engineer.","Pre-position repair crews."],
        kpi_snapshot={"risk":58.0,"ens_mw":124.0,"exceedance_pct":48.2,
                      "total_unc_pct":14.2,"ood_score":0.21},
        escalation_path=["Control Room Duty Engineer","Engineering Manager on Call"],
    )
    st.code(generate_cap_xml(dummy_alert), language="xml")

    # SLA tracker
    st.markdown("---")
    st.markdown("##### Dispatch SLA Tracker (Ofgem compliance)")
    st.caption("GREEN = within Ofgem SLA target. RED = SLA breach.")


def html_escape(s: str) -> str:
    """Escape HTML special characters for XML output."""
    return (s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
             .replace('"',"&quot;").replace("'","&apos;"))

