    with t_mc:
        st.markdown("#### 📊 Monte Carlo & Tail Risk")
        sel_pl_mc = st.selectbox("Location", sorted(fvs.keys()), key="fv_mc_pl")
        mc_n      = st.slider("Simulations", 500, 5000, 2000, 500, key="fv_mc_n")
